insert into public.themen (id, name, beschreibung, symptome) values
  (1, 'Arzttermine', 'Lange Wartezeiten und schwer erreichbare Praxen.', '[{"nr":1,"alltag":"Ich warte beim Facharzt monatelang auf einen Termin","ursachen_ids":[102,103]}]'::jsonb),
  (2, 'Miete', 'Hohe Mieten und schwierige Wohnungssuche.', '[{"nr":1,"alltag":"Ich finde keine bezahlbare Wohnung","ursachen_ids":[201,202,203,205,206]}]'::jsonb),
  (3, 'Energiepreise', 'Hohe Kosten für Strom und Heizung.', '[{"nr":1,"alltag":"Mein Strom ist zu teuer","ursachen_ids":[301,302,304]},{"nr":2,"alltag":"Meine Heizkosten sind zu hoch","ursachen_ids":[302,303,305]}]'::jsonb),
  (4, 'Schule', 'Unterrichtsausfall, fehlende Lehrkräfte und marode Schulgebäude.', '[]'::jsonb),
  (5, 'Arbeitsplätze', 'Unsichere Jobs, Stellenabbau und schwache Wirtschaft.', '[{"nr":1,"alltag":"Ich habe Angst, meinen Arbeitsplatz zu verlieren","ursachen_ids":[501,502,505]}]'::jsonb),
  (6, 'Zuwanderung und Integration', 'Probleme bei Aufnahme, Integration und Rückführung von Zugewanderten.', '[{"nr":1,"alltag":"Menschen, die nicht hierbleiben dürften, bleiben trotzdem","ursachen_ids":[604,605]}]'::jsonb),
  (7, 'Rente', 'Niedrige Renten und Sorge um die Altersvorsorge.', '[]'::jsonb),
  (8, 'Bus und Bahn', 'Seltene Verbindungen, Ausfälle, Verspätungen und teure Tickets.', '[]'::jsonb),
  (9, 'Sicherheit', 'Opfer von Gewalt, Diebstahl oder Betrug werden – zu Hause, unterwegs oder im Internet – oder sich im Alltag unsicher fühlen.', '[]'::jsonb),
  (10, 'Pflege', 'Pflegeplatz oder Pflegedienst finden, hohe Kosten, überlastete Angehörige.', '[{"nr":1,"alltag":"Das Pflegeheim ist so teuer, dass wir es kaum bezahlen können","ursachen_ids":[1002,1005]}]'::jsonb),
  (11, 'Preise und Löhne', 'Lebensmittel und Dinge des Alltags sind teuer geworden, der Lohn reicht kaum.', '[{"nr":1,"alltag":"Lebensmittel sind zu teuer geworden","ursachen_ids":[1101,1102]},{"nr":2,"alltag":"Von meinem Lohn bleibt mir zu wenig zum Leben","ursachen_ids":[1103,1104]}]'::jsonb),
  (12, 'Straßen und Brücken', 'Kaputte Straßen, gesperrte Brücken, lange Umwege und gefährliche Radwege.', '[{"nr":1,"alltag":"Die Straßen in meiner Gemeinde werden nicht repariert","ursachen_ids":[1202,1203]}]'::jsonb),
  (13, 'Internet und Mobilfunk', 'Langsames Internet zu Hause und Funklöcher unterwegs.', '[]'::jsonb),
  (14, 'Behördengänge', 'Lange Wartezeiten auf Termine und Bescheide, viel Papier, dieselben Angaben immer wieder.', '[]'::jsonb),
  (15, 'Autofahren', 'Teures Tanken, wenige Lademöglichkeiten und teure Elektroautos.', '[{"nr":1,"alltag":"Tanken ist zu teuer","ursachen_ids":[1501,1502,1503]}]'::jsonb),
  (16, 'Heizungstausch', 'Unsicherheit und hohe Kosten, wenn die Heizung erneuert werden muss oder soll.', '[{"nr":1,"alltag":"Ich weiß nicht, welche Heizung ich einbauen soll","ursachen_ids":[1602,1603]}]'::jsonb),
  (17, 'Kita-Betreuung', 'Familien finden keinen passenden Betreuungsplatz oder erleben, dass die Betreuung zu wenig Personal hat, ausfällt oder zu viel kostet.', '[{"nr":1,"alltag":"In der Kita meines Kindes fehlt Personal, und die Betreuung leidet","ursachen_ids":[1702,1703,1704]}]'::jsonb),
  (18, 'Hitze und Unwetter', 'Hitzewellen, Starkregen und Hochwasser belasten die Gesundheit und beschädigen Wohnungen und Eigentum.', '[]'::jsonb),
  (19, 'Diskriminierung im Alltag', 'Menschen werden wegen zugeschriebener Herkunft, Religion, sexueller oder geschlechtlicher Identität bei der Wohnungs- und Arbeitssuche, in Behörden, Schulen und im öffentlichen Raum benachteiligt oder angefeindet.', '[]'::jsonb),
  (20, 'Freizeitangebote und Treffpunkte für Jugendliche', 'Jugendliche finden vor Ort keine passenden Freizeitangebote oder Treffpunkte, können Aktivitäten nicht bezahlen oder verlieren Aufenthaltsorte durch Konflikte mit Anwohnenden und anderen Nutzenden (etwa Lärmbeschwerden über Jugendliche an ihrem Treffpunkt).', '[]'::jsonb),
  (21, 'Armut und Kinderarmut', 'Menschen haben zu wenig Geld für grundlegende Bedürfnisse und gesellschaftliche Teilhabe. Kinder wachsen unter finanziellen Einschränkungen auf, auch wenn ihre Familien Unterstützung erhalten.', '[]'::jsonb),
  (22, 'Radikalisierung und Extremismus', 'Menschen erleben die Hinwendung zu extremistischen Gruppen und Einstellungen sowie politische Konflikte, in denen gegenseitige Abwertung und Gesprächsabbrüche den Austausch erschweren.', '[{"nr":1,"alltag":"Jemand in meinem Umfeld wird immer radikaler","ursachen_ids":[2201,2202,2203,2204]},{"nr":2,"alltag":"Mit Menschen, die politisch anders denken, kann man kaum noch reden","ursachen_ids":[2205,2206]}]'::jsonb),
  (23, 'Mobbing und Druck in der Schule', 'Schülerinnen und Schüler erleben Mobbing, Cybermobbing, Ausgrenzung oder belastenden Leistungs- und Prüfungsdruck im Schulalltag.', '[{"nr":1,"alltag":"Mein Kind wird in der Schule gemobbt","ursachen_ids":[2301,2302]}]'::jsonb),
  (24, 'Abwanderung aus strukturschwachen Regionen', 'In strukturschwachen Regionen in Ost und West fehlen Zukunftsperspektiven. Junge Menschen ziehen weg, die Bevölkerung wird älter und schrumpft, und die Versorgung vor Ort gerät unter Druck: Läden, Arztpraxen und Schulen schließen.', '[]'::jsonb),
  (25, 'Hass und Anfeindungen im Internet', 'Privatpersonen und politisch Aktive erleben online Hassnachrichten, Beleidigungen, Bedrohungen und Schikanen, etwa Cybermobbing oder das Veröffentlichen persönlicher Daten zur Einschüchterung.', '[{"nr":1,"alltag":"Im Netz werde ich oder werden andere ständig beleidigt und angefeindet","ursachen_ids":[2501,2502,2503]}]'::jsonb),
  (26, 'Barrieren für Menschen mit Behinderung', 'Menschen mit Behinderung stoßen beim Wohnen, unterwegs, in Gebäuden, bei digitalen Angeboten, im Arbeitsleben und beim Zugang zu Teilhabeleistungen auf Hindernisse.', '[{"nr":1,"alltag":"Ich finde mit Behinderung keine Arbeit","ursachen_ids":[2602,2603]}]'::jsonb),
  (27, 'Arbeitsbelastung im Gesundheitswesen', 'Beschäftigte in Pflege, Medizin, Kliniken und Rettungsdienst erleben Zeitdruck, belastende Dienste, knappe Personalbesetzung, aufwendige Dokumentation und unzureichende Anerkennung ihrer Arbeit.', '[{"nr":1,"alltag":"Die Arbeit ist kaum noch zu schaffen","ursachen_ids":[2701,2702,2703]}]'::jsonb),
  (28, 'Sexismus und Benachteiligung von Frauen', 'Frauen erleben Benachteiligung im Beruf, ungleich verteilte Sorgearbeit, sexuelle Belästigung und widersprüchliche Erwartungen an ihre Lebensgestaltung.', '[]'::jsonb),
  (29, 'Einsamkeit und psychische Belastung', 'Menschen aller Altersgruppen fühlen sich einsam oder psychisch belastet. Manche können ihre Gefühle schwer einordnen oder ausdrücken und finden nicht rechtzeitig passende Unterstützung.', '[]'::jsonb),
  (30, 'Sucht und Glücksspiel', 'Alkohol, Tabak, Drogen, Medikamente oder Glücksspiel beeinträchtigen Gesundheit, Beziehungen und finanzielle Sicherheit. Betroffene erleben Kontrollverlust oder Schwierigkeiten, passende Hilfe zu erhalten.', '[]'::jsonb),
  (31, 'Kosten von Studium und Ausbildung', 'Studierende und Auszubildende haben Schwierigkeiten, Lebenshaltung, Wohnen und Ausbildung zu finanzieren. Nebenjobs und spätere Darlehensrückzahlungen können zusätzlich belasten.', '[]'::jsonb),
  (32, 'Räume für Kultur und Clubs', 'Clubs, Kulturorte, soziokulturelle Zentren, Freilichtbühnen und kulturell genutzte selbstverwaltete Hausprojekte verlieren Räume oder können sie wegen Kosten für Miete, Betrieb und Programm, Lärmkonflikten mit der Nachbarschaft und baulichen Hürden nur eingeschränkt nutzen.', '[{"nr":1,"alltag":"Unser Club oder Kulturort kann Miete und Betrieb kaum noch bezahlen","ursachen_ids":[3201,3203]}]'::jsonb),
  (33, 'Mediennutzung von Kindern und Jugendlichen', 'Kinder und Jugendliche verbringen länger als gewollt Zeit am Bildschirm oder in sozialen Medien. Familien erleben Schwierigkeiten beim Begrenzen sowie Sorgen um Schlaf, Konzentration und altersgerechte Nutzung.', '[]'::jsonb),
  (34, 'Umgang der Polizei mit jungen Menschen', 'Junge Menschen erleben Polizeikontrollen oder Einsätze als belastend, unangemessen oder schwer nachvollziehbar und können mögliche Fehler nur schwer klären lassen.', '[{"nr":1,"alltag":"Ich wurde von der Polizei schlecht behandelt","ursachen_ids":[3402,3403]}]'::jsonb),
  (35, 'Kosten für den Führerschein', 'Der Führerscheinerwerb ist teuer. Fahrschulpreise, Fahrstunden, Prüfungen und Wartezeiten können Kosten und Dauer schwer planbar machen.', '[]'::jsonb),
  (36, 'Leerstand und Geschäftsschließungen in Innenstädten', 'In Innenstädten und Ortskernen schließen Geschäfte. Ladenflächen stehen leer, Einkaufsangebote verschwinden und manche Orte werden weniger besucht.', '[]'::jsonb),
  (37, 'Finanzierung von Sportvereinen und Sportstätten', 'Breiten- und Amateursportvereinen fehlen finanzielle Spielräume, Unterstützung für ehrenamtliche Trainer und Übungsleiter oder geeignete Sportstätten wie Sporthallen, Sportplätze und Schwimmbäder, um Training, Schwimmkurse und Wettkämpfe dauerhaft anzubieten.', '[{"nr":1,"alltag":"Unserem Verein fehlen Geld und gute Sportstätten","ursachen_ids":[3701,3702,3703]}]'::jsonb),
  (38, 'Krankenkasse: Beiträge und Leistungen', 'Viele Versicherte sehen den Zusatzbeitrag steigen und erleben, dass Leistungen begrenzt sind oder Zuzahlungen und Eigenanteile anfallen.', '[]'::jsonb),
  (39, 'Wohneigentum', 'Viele Menschen möchten eine eigene Wohnung oder ein eigenes Haus, sehen aber Kaufpreise, Eigenkapital und Nebenkosten als kaum erreichbar an.', '[]'::jsonb),
  (40, 'Arbeitszeit, Erreichbarkeit und Vereinbarkeit', 'Viele Beschäftigte arbeiten länger als vereinbart, werden in der Freizeit erreicht oder können ihre Arbeitszeit nicht so gestalten, wie es zu Kindern oder pflegebedürftigen Angehörigen passt.', '[]'::jsonb),
  (41, 'Schutz im Krisen- und Kriegsfall', 'Viele Menschen wissen nicht, wie sie in einer Großlage wie Krieg, Sabotage oder langem Stromausfall gewarnt werden und wo sie Schutz und Versorgung finden. Es geht um den Schutz und die Versorgung der Bevölkerung, nicht um die Verhinderung von Konflikten.', '[]'::jsonb)
on conflict (id) do update set name = excluded.name, beschreibung = excluded.beschreibung, symptome = excluded.symptome;

insert into public.ursachen (id, thema_id, beschreibung, quelle_url, ebene, alltag, gilt_fuer) values
  (101, 1, 'Zu wenige Hausarztpraxen, besonders auf dem Land: Viele Ärztinnen und Ärzte gehen bald in den Ruhestand, zu wenige lassen sich als Hausarzt nieder', 'https://idw-online.de/de/news769524', 'bund', 'Ich finde keine Hausarztpraxis in meiner Nähe, die noch neue Patienten nimmt', 'Hausarztpraxen, nicht Fach- oder Zahnarztpraxen'),
  (102, 1, 'Termine und Wege durch das Gesundheitssystem werden kaum gesteuert; knappes Personal wird nicht gezielt eingesetzt', 'https://www.svr-gesundheit.de/publikationen/gutachten-2024/', 'bund', 'Ich weiß nicht, wohin ich mich wenden soll, und lande bei Terminen und Wegen im Kreis', null),
  (103, 1, 'Unterschiedliche Vergütung: Facharztpraxen vergeben Termine bevorzugt an Privatversicherte', 'https://idw-online.de/de/news750098', 'bund', 'Als Kassenpatient bekomme ich beim Facharzt viel später einen Termin als Privatversicherte', null),
  (201, 2, 'Es werden weniger Wohnungen gebaut als gebraucht (Bedarf laut Prognose rund 320.000 pro Jahr)', 'https://www.bbsr.bund.de/BBSR/DE/presse/presseinformationen/2025/wohnungsbedarfsprognose.html', 'bund', 'Ich finde keine Wohnung, weil es zu wenige gibt', null),
  (202, 2, 'Mieten bei Neuvermietung liegen rund 43 % über Bestandsmieten, in großen Städten besonders hoch', 'https://www.bbsr.bund.de/BBSR/DE/startseite/topmeldungen/entwicklung-wohnungsmieten-2025.html', 'bund', 'Für eine neue Wohnung soll ich viel mehr Miete zahlen als die Leute, die schon lange dort wohnen', 'Menschen, die eine neue Wohnung suchen'),
  (203, 2, 'Stark gestiegene Baukosten: Wohngebäude wurden 2010 bis 2025 um 89 % teurer, mehr als doppelt so stark wie die Inflation', 'https://www.destatis.de/DE/Themen/Wirtschaft/Preise/Baupreise-Immobilienpreisindex/_inhalt.html', 'bund', 'Neubauwohnungen sind so teuer, dass sich kaum jemand die Miete leisten kann', null),
  (204, 2, 'Mieten in laufenden Verträgen steigen weiter (Nettokaltmieten 2025 im Schnitt +2,1 %)', 'https://www.destatis.de/DE/Presse/Pressemitteilungen/2026/01/PD26_019_611.html', 'bund', 'Meine Miete steigt Jahr für Jahr, obwohl ich nicht umgezogen bin', 'laufender Mietvertrag ohne Umzug'),
  (205, 2, 'Die Nachfrage wächst vor allem in wirtschaftlich starken Großstädten: mehr Haushalte durch Zuwanderung und Zuzug aus dem Inland, dazu höhere Einkommen', 'https://www.iwkoeln.de/fileadmin/user_upload/Studien/Report/PDF/2026/IW-Report_2026-Migration-und-Wohnungsmarkt.pdf', 'bund', 'In meiner Stadt wollen so viele Menschen wohnen, dass es kaum freie Wohnungen gibt', null),
  (206, 2, 'Jedes Jahr fallen mehr Sozialwohnungen aus der Bindung, als neue gefördert werden (2025: rund 27.000 neu gefördert, rund 55.000 fallen jährlich heraus)', 'https://www.bundestag.de/presse/hib/kurzmeldungen-1200778', 'land', 'Es gibt immer weniger Sozialwohnungen, und ich bekomme keine bezahlbare Wohnung', null),
  (301, 3, 'Hohe Netzentgelte für den Betrieb und Ausbau der Stromnetze', 'https://www.bundesnetzagentur.de/DE/Vportal/Energie/PreiseAbschlaege/Tarife-table.html', 'bund', 'Auf meiner Stromrechnung stecken hohe Gebühren für das Stromnetz', null),
  (302, 3, 'Steuern, Abgaben und Umlagen machen einen großen Teil der Strom- und Gaspreise aus, beim Gas auch der CO₂-Preis', 'https://www.bundesnetzagentur.de/DE/Vportal/Energie/PreiseAbschlaege/Tarife-table.html', 'bund', 'Auf meiner Strom- und Gasrechnung stecken viele Steuern, Abgaben und der CO₂-Preis', null),
  (303, 3, 'Rund 70 % der Energie wird importiert, vor allem Öl, Gas und Steinkohle', 'https://www.umweltbundesamt.de/daten/umweltzustand-trends/energie/primaerenergiegewinnung-importe', 'bund', 'Ich mache mir Sorgen, weil wir Öl und Gas aus dem Ausland brauchen und die Preise davon abhängen', null),
  (304, 3, 'Der Strompreis an der Börse richtet sich nach dem teuersten noch benötigten Kraftwerk, heute oft einem Gaskraftwerk', 'https://www.bundestag.de/resource/blob/918822/abb4747668630cbe6d457512d42265c4/WD-5-121-22-pdf-data.pdf', 'bund', 'Strom wird teuer, weil teure Gaskraftwerke den Preis bestimmen, obwohl auch billiger Strom erzeugt wird', null),
  (305, 3, 'Drei Viertel der Wohnungen wurden 2022 mit Gas oder Öl beheizt (Zensus); die Heizkosten hängen deshalb stark von deren Preisen ab', 'https://www.destatis.de/DE/Presse/Pressemitteilungen/Zensus2022-Pressemitteilungen/PM_zenus2022_45.html', 'bund', 'Ich heize mit Gas oder Öl, und meine Heizkosten schwanken mit deren Preisen', null),
  (401, 4, 'Zu wenige Lehrkräfte: Kurzfristig liegt das Angebot deutlich unter dem Einstellungsbedarf', 'https://www.kmk.org/downloads-dokumente/statistik/schulstatistik/lehrkraefteeinstellungsbedarf-und-angebot.html', 'land', 'Bei uns fällt Unterricht aus, weil Lehrkräfte fehlen', null),
  (402, 4, 'Großer Sanierungsstau bei Schulgebäuden (rund 68 Mrd. Euro, größter Posten der Kommunen)', 'https://www.bundestag.de/resource/blob/1157306/KfW-Kommunalpanel-2025.pdf', 'land', 'Die Schule meines Kindes ist in schlechtem Zustand: marode Toiletten, undichte Dächer, alte Ausstattung', null),
