, 9974, 9975, 9976, 9977, 9978, 9979, 9980, 9981, 9982, 10112, 10113, 10114, 10115, 10116, 10117, 10118, 10119, 10120, 10121, 10122, 10123, 10124, 10125, 10126, 10127, 10128, 10129, 10130, 10131, 10132, 10227, 10228, 10229, 10230, 10231, 10232, 10233, 10234, 10235, 10236, 10237, 10238, 10239, 10240, 10302, 10320, 10321, 10322, 10323, 10324, 10356, 10357, 10358, 10377, 10378, 10379, 10380, 10381, 10382, 10383, 10384, 10385, 10386, 10387, 10443, 10444, 10445, 10446, 10447, 10448, 10449, 10450, 10451, 10452, 10453, 10454, 10455, 10456, 10457, 10458, 10459, 10460, 10461, 10462, 10566, 10567, 10568, 10569, 10570, 10571, 10572, 10573, 10574, 10575, 10576, 10615, 10616, 10617, 10618, 10619, 10620, 10621, 10622, 10623, 10624, 10625, 10626, 10627, 10628, 10693, 10694, 10695, 10696, 10697, 10698, 10699, 10700, 10701, 10741, 10742, 10743);

insert into public.massnahmen (id, thema_id, partei_id, land, beschreibung, ursachen_ids, instrument_id, wirksamkeit, umsetzbarkeit,
  rollen_modifikator, begruendung, beleg_programm_url, beleg_studie_url, evidenz, stand, geprueft, ki_entwurf, entwurf_herkunft) values
  (2001, 2, 11, null, 'Bauordnungsrecht entschlacken, Gebäudetyp E, befristete Ausnahmen vom Planungsrecht in angespannten Wohnungsmärkten', '{201,203,205}', null, 2, 2, null, 'Senkt Baukosten und beschleunigt Planung; Bauordnungen sind Ländersache, die Wirkung hängt daher auch von den Ländern ab.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=73', null, 'gemischt', '2026-09-30', false, true, null),
  (2002, 2, 11, null, 'Mehr Bauland: Brach- und Konversionsflächen sowie bundeseigene Grundstücke für den Wohnungsbau nutzen', '{201,205}', null, 2, 2, null, 'Mehr verfügbare Flächen erleichtern Neubau in Wachstumsregionen; Umfang und Tempo hängen von Kommunen und Ländern ab.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=73', null, 'gemischt', '2026-09-30', false, true, null),
  (2003, 2, 11, null, 'Keine neuen kostentreibenden Standards (Baukostenmoratorium), Genehmigungsverfahren digitalisieren und beschleunigen', '{203}', 6641, 2, 3, null, 'Verhindert weitere Kostensteigerungen durch Vorschriften und verkürzt Verfahren; bereits gestiegene Material-, Lohn- und Zinskosten bleiben. Wie viel Standards an den Baukosten ausmachen, ist umstritten.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=73', null, 'gemischt', '2026-09-27', false, true, null),
  (2004, 2, 11, null, 'Höhere befristete Sonderabschreibung und degressive Abschreibung für bezahlbaren Mietwohnungsbau in angespannten Märkten', '{201}', 6640, 2, 2, null, 'Steuerliche Anreize können Neubau anstoßen; kostet Steuereinnahmen, und ob die Wohnungen günstig vermietet werden, ist nicht gesichert. Frühere Sonderabschreibungen wirkten vor allem bei ohnehin geplanten Projekten.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=73', null, 'gemischt', '2026-09-27', false, true, null),
  (2005, 2, 11, null, 'Sozialen Wohnungsbau solide fördern und Wohngeld regelmäßig anpassen', '{201,202,206}', null, 1, 3, null, 'Hält bestehende Instrumente aufrecht, ohne Umfang oder Ausbau zu beziffern; Wohngeld entlastet, schafft aber keine Wohnungen.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=73', null, 'belegt', '2026-09-27', false, true, null),
  (2006, 2, 11, null, 'Steuerliche Nachteile für Vermieter abschaffen, die weniger als die ortsübliche Vergleichsmiete verlangen', '{202}', null, 1, 3, null, 'Setzt einen kleinen Anreiz für günstige Mieten, vor allem bei privaten Vermietern; die Wirkung auf das Mietniveau ist begrenzt.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=73', null, 'offen', '2026-09-27', false, true, null),
  (2011, 2, 12, null, 'Mietpreisbremse unbefristet verlängern, auf Wohnungen bis Baujahr 2019 ausweiten und Umgehung über möblierte oder befristete Angebote verhindern', '{202}', null, 2, 2, '{"mieter":{"wert":1,"begruendung":"Begrenzt die Miete bei Neuvermietung unmittelbar."},"eigentuemer":{"wert":-1,"begruendung":"Begrenzt mögliche Mieteinnahmen bei Neuvermietung."}}'::jsonb, 'Dämpft Mieten bei Neuvermietung in angespannten Märkten; schafft keine neuen Wohnungen. Eine unbefristete Geltung ist verfassungsrechtlich weniger abgesichert als die befristete.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=20', null, 'gemischt', '2026-09-27', false, true, null),
  (2012, 2, 12, null, 'Mieterhöhungen im Bestand in angespannten Märkten auf 6 % in drei Jahren begrenzen, Indexmieten deckeln', '{204}', null, 2, 3, '{"mieter":{"wert":1,"begruendung":"Begrenzt Mieterhöhungen im laufenden Mietverhältnis."},"eigentuemer":{"wert":-1,"begruendung":"Begrenzt Mieterhöhungen im Bestand."}}'::jsonb, 'Begrenzt Erhöhungen in laufenden Mietverträgen spürbar, vor allem in angespannten Märkten; schafft keine neuen Wohnungen.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=21', null, 'gemischt', '2026-09-27', false, true, null),
  (2013, 2, 12, null, 'Sozialen Wohnungsbau stärken; Wohnungsgesellschaften und Genossenschaften über einen Deutschlandfonds mit Eigenkapital ausstatten', '{201,206}', null, 2, 2, null, 'Mehr Kapital für gemeinwohlorientierte Bauherren kann das Angebot günstiger Wohnungen erhöhen; erfordert erhebliche öffentliche Mittel.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=21', null, 'offen', '2026-09-27', false, true, null),
  (2014, 2, 12, null, 'Baukosten senken: Gebäudetyp E weiterentwickeln, serielles und modulares Bauen fördern, Bauverwaltung digitalisieren', '{203}', 6641, 2, 3, null, 'Verhindert weitere Kostensteigerungen durch Vorschriften und verkürzt Verfahren; bereits gestiegene Material-, Lohn- und Zinskosten bleiben. Wie viel Standards an den Baukosten ausmachen, ist umstritten.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=22', null, 'gemischt', '2026-09-27', false, true, null),
  (2015, 2, 12, null, 'Neue bundeseigene Wohnungsgesellschaft gründen', '{201}', null, 1, 2, null, 'Schafft zusätzliche Wohnungen, laut Programm vor allem für Beschäftigte des Bundes; die Wirkung auf den allgemeinen Markt ist begrenzt.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=22', null, 'offen', '2026-09-27', false, true, null),
  (2021, 2, 13, null, 'Mietpreisbremse verlängern, Ausnahmen abschaffen, auf Wohnungen älter als fünf Jahre anwenden und Schlupflöcher (möbliert, Ferienwohnung) schließen', '{202}', null, 2, 3, '{"mieter":{"wert":1,"begruendung":"Begrenzt die Miete bei Neuvermietung unmittelbar."},"eigentuemer":{"wert":-1,"begruendung":"Begrenzt mögliche Mieteinnahmen bei Neuvermietung."}}'::jsonb, 'Dämpft Mieten bei Neuvermietung in angespannten Märkten; schafft keine neuen Wohnungen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=69', null, 'gemischt', '2026-09-27', false, true, null),
  (2022, 2, 13, null, 'Mietenstopp in angespannten Wohnungsmärkten ermöglichen und Kappungsgrenzen senken', '{204}', 6639, 2, 2, '{"mieter":{"wert":1,"begruendung":"Verhindert Mieterhöhungen im laufenden Mietverhältnis."},"eigentuemer":{"wert":-1,"begruendung":"Schließt Mieterhöhungen im Bestand zeitweise aus."}}'::jsonb, 'Stoppt Erhöhungen in laufenden Mietverträgen in angespannten Märkten; schafft keine neuen Wohnungen und kann Instandhaltung und Modernisierung bremsen. Ein Mietenstopp wirft verfassungsrechtliche Fragen auf.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=69', null, 'gemischt', '2026-09-27', false, true, null),
  (2023, 2, 13, null, 'Mehr Wohnraum im Bestand: Aufstockung, Umwandlung von Büros, Dachausbau; Baurecht vereinfachen, Verfahren digitalisieren, Standards zurückführen', '{201,203,205}', null, 2, 2, null, 'Nutzt vorhandene Gebäude und senkt Kosten durch einfachere Regeln; wie viele Wohnungen so entstehen, ist unsicher.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=71', null, 'gemischt', '2026-09-30', false, true, null),
  (2024, 2, 13, null, 'Fördermittel für sozialen und gemeinnützigen Wohnungsbau erhöhen, Miet- und Belegungsbindungen unbefristet', '{201,206}', 6642, 2, 2, null, 'Schafft preisgebundene Wohnungen für Haushalte mit geringem Einkommen; erfordert erhebliche öffentliche Mittel, der Umfang ist nicht beziffert.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=72', null, 'belegt', '2026-09-27', false, true, null),
  (2031, 2, 14, null, 'Steuerliche Abschreibungen im Wohnungsbau verbessern, Sonderabschreibung fortführen', '{201}', 6640, 2, 2, null, 'Steuerliche Anreize können Neubau anstoßen; kostet Steuereinnahmen, und ob die Wohnungen günstig vermietet werden, ist nicht gesichert. Frühere Sonderabschreibungen wirkten vor allem bei ohnehin geplanten Projekten.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=43', null, 'gemischt', '2026-09-27', false, true, null),
  (2032, 2, 14, null, 'Baukostenmoratorium, Bau-Auflagen auf Mindeststandards reduzieren, serielles Bauen mit bundesweiten Standards', '{203}', null, 2, 2, null, 'Setzt an Vorschriften als Kostentreiber an; Mindeststandards bei Gebäudeenergie sind teils durch EU-Recht vorgegeben.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=44', null, 'gemischt', '2026-09-27', false, true, null),
  (2033, 2, 14, null, 'Genehmigungsfiktion für Bauanträge, durchgehend digitale Planung, einfachere Ausweisung neuer Bauflächen', '{201}', null, 2, 2, null, 'Beschleunigt Verfahren und erweitert das Flächenangebot; Personalmangel in Bauämtern bleibt ein Engpass.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=44', null, 'offen', '2026-09-27', false, true, null),
  (2034, 2, 14, null, 'Mietpreisbremse auslaufen lassen, um Anreize für Neubau zu setzen', '{201}', 6637, 1, 3, '{"mieter":{"wert":-1,"begruendung":"Fällt die Begrenzung weg, können Neuvermietungsmieten in angespannten Märkten stärker steigen."},"eigentuemer":{"wert":1,"begruendung":"Mehr Spielraum bei der Miethöhe."}}'::jsonb, 'Soll Investitionen anregen; Neubauten sind von der Mietpreisbremse ohnehin ausgenommen, die Wirkung auf den Neubau ist daher gering. Studien finden keinen deutlichen Rückgang des Neubaus durch die Bremse.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=44', null, 'gemischt', '2026-09-27', false, true, null),
  (2041, 2, 15, null, 'Gebäudeenergiegesetz abschaffen und kostentreibende EU-Bauvorschriften ablehnen', '{203}', null, 1, 1, null, 'Senkt einzelne Anforderungen an Neubauten; das Gesetz setzt zum Teil EU-Recht um, eine Abschaffung wäre daher nur eingeschränkt möglich.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=37', null, 'offen', '2026-09-27', false, true, null),
  (2042, 2, 15, null, 'Mehr Wohngeld und zusätzliches kommunales Wohngeld statt sozialem Wohnungsbau', '{202,206}', null, 1, 2, null, 'Entlastet Haushalte mit geringem Einkommen direkt; schafft keine zusätzlichen Wohnungen, der Verzicht auf sozialen Wohnungsbau verringert das Angebot günstiger Wohnungen.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=38', null, 'belegt', '2026-09-30', false, true, null),
  (2043, 2, 15, null, 'Mietpreisbremse und Mietendeckel ablehnen, um Investitionshemmnisse abzubauen', '{201}', 6637, 1, 3, '{"mieter":{"wert":-1,"begruendung":"Fällt die Begrenzung weg, können Neuvermietungsmieten in angespannten Märkten stärker steigen."},"eigentuemer":{"wert":1,"begruendung":"Mehr Spielraum bei der Miethöhe."}}'::jsonb, 'Soll Investitionen anregen; Neubauten sind von der Mietpreisbremse ohnehin ausgenommen, die Wirkung auf den Neubau ist daher gering. Studien finden keinen deutlichen Rückgang des Neubaus durch die Bremse.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=39', null, 'gemischt', '2026-09-27', false, true, null),
  (2051, 2, 16, null, 'Bundesweiter Mietendeckel; besonders hohe Mieten in angespannten Märkten absenken', '{202}', 6638, 2, 1, '{"mieter":{"wert":1,"begruendung":"Senkt oder begrenzt die Miete unmittelbar."},"eigentuemer":{"wert":-1,"begruendung":"Begrenzt oder senkt Mieteinnahmen."}}'::jsonb, 'Begrenzt Mieten direkt, auch bei Neuvermietung, schafft aber keine neuen Wohnungen; in Berlin sanken 2020/21 die regulierten Mieten, zugleich wurden weniger Wohnungen angeboten. Ob ein bundesweiter Deckel mit Absenkung verfassungsgemäß wäre, ist offen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=8', null, 'gemischt', '2026-09-28', false, true, null),
  (2052, 2, 16, null, 'Mieterhöhungen bundesweit für sechs Jahre ausschließen; Staffel- und Indexmieten verbieten', '{204}', null, 2, 1, '{"mieter":{"wert":1,"begruendung":"Verhindert Mieterhöhungen im laufenden Mietverhältnis."},"eigentuemer":{"wert":-1,"begruendung":"Schließt Mieterhöhungen im Bestand zeitweise aus."}}'::jsonb, 'Stoppt Erhöhungen in laufenden Mietverträgen vollständig; ein bundesweiter Stopp über sechs Jahre wirft erhebliche verfassungsrechtliche Fragen auf.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=8', null, 'gemischt', '2026-09-28', false, true, null),
  (2053, 2, 16, null, '20 Milliarden Euro im Jahr für gemeinnützigen Wohnungsbau, Sozialbindung dauerhaft, Investitionen von der Schuldenbremse ausnehmen', '{201,206,205}', null, 2, 1, null, 'Würde das Angebot dauerhaft günstiger Wohnungen deutlich erhöhen; die Ausnahme von der Schuldenbremse erfordert eine Verfassungsänderung.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=9', null, 'belegt', '2026-09-30', false, true, null),
  (2054, 2, 16, null, 'Wohnungsbestände von Konzernen mit mehr als 3.000 Wohnungen vergesellschaften', '{202}', null, 1, 1, null, 'Kann Mieten im übernommenen Bestand dämpfen, schafft aber keine neuen Wohnungen; Entschädigung unter Marktwert ist rechtlich umstritten und teuer.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=9', null, 'offen', '2026-09-28', false, true, null),
  (2055, 2, 16, null, 'Leerstand erfassen und mit einer Abgabe von 10 Euro pro Quadratmeter belegen', '{201}', null, 1, 2, null, 'Kann leerstehende Wohnungen auf den Markt bringen; in angespannten Märkten ist der Leerstand gering, ein großer Teil liegt in schrumpfenden Regionen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=9', null, 'offen', '2026-09-28', false, true, null),
  (2056, 2, 16, null, 'Regulierungen beim Neubau überprüfen, soweit sie nur die Preise treiben', '{203}', null, 1, 3, null, 'Setzt an Vorschriften als Kostentreiber an, bleibt aber allgemein und nennt keine konkreten Regeln.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=9', null, 'offen', '2026-09-28', false, true, null),
  (2061, 2, 17, null, 'Gemeinnützigen und kommunalen Wohnungsbau stärken: zinsvergünstigte Kredite, großes Wohnungsbauprogramm, dauerhafte Sozialbindung', '{201,206,205}', 6642, 2, 2, null, 'Schafft preisgebundene Wohnungen für Haushalte mit geringem Einkommen; erfordert erhebliche öffentliche Mittel, der Umfang ist nicht beziffert.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=28', null, 'belegt', '2026-09-30', false, true, null),
  (2062, 2, 17, null, 'Bundesweiter Mietendeckel statt Mietpreisbremse', '{202}', 6638, 2, 1, '{"mieter":{"wert":1,"begruendung":"Senkt oder begrenzt die Miete unmittelbar."},"eigentuemer":{"wert":-1,"begruendung":"Begrenzt oder senkt Mieteinnahmen."}}'::jsonb, 'Begrenzt Mieten direkt, auch bei Neuvermietung, schafft aber keine neuen Wohnungen; in Berlin sanken 2020/21 die regulierten Mieten, zugleich wurden weniger Wohnungen angeboten. Ob ein bundesweiter Deckel mit Absenkung verfassungsgemäß wäre, ist offen.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=28', null, 'gemischt', '2026-09-28', false, true, null),
  (2063, 2, 17, null, 'Mieten in Regionen mit knappem bezahlbarem Wohnraum bis Ende des Jahrzehnts einfrieren; Sanierungskosten tragen die Vermieter', '{204}', 6639, 2, 2, '{"mieter":{"wert":1,"begruendung":"Verhindert Mieterhöhungen im laufenden Mietverhältnis."},"eigentuemer":{"wert":-1,"begruendung":"Schließt Mieterhöhungen im Bestand zeitweise aus."}}'::jsonb, 'Stoppt Erhöhungen in laufenden Mietverträgen in angespannten Märkten; schafft keine neuen Wohnungen und kann Instandhaltung und Modernisierung bremsen. Ein Mietenstopp wirft verfassungsrechtliche Fragen auf.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=28', null, 'gemischt', '2026-09-28', false, true, null),
  (2064, 2, 17, null, 'Bauvorhaben beschleunigen: serielles Bauen vereinfachen, vereinfachtes Genehmigungsverfahren für sozialen Wohnungsbau, überzogene Bauvorschriften prüfen', '{201,203}', null, 2, 2, null, 'Setzt an Verfahrensdauer und Vorschriften an; wie stark die Kosten sinken, hängt von der Umsetzung in den Ländern ab.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=28', null, 'gemischt', '2026-09-28', false, true, null),
  (4001, 4, 11, null, 'Entwicklungsstand aller Drei- bis Vierjährigen nach einheitlichen Standards erfassen', '{404}', null, 1, 2, null, 'Eine frühe Diagnose ist Voraussetzung für Förderung, bewirkt allein aber noch keine. Einheitliche Standards brauchen die Zustimmung der Länder.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=65', null, 'gemischt', '2026-09-28', false, true, null),
  (4002, 4, 11, null, 'Kinder mit Sprachförderbedarf zu einem Vorschulprogramm verpflichten; Bundesprogramm Sprach-Kitas neu starten', '{404}', null, 2, 2, null, 'Verbindliche Förderung vor der Einschulung setzt direkt am Sprachförderbedarf an; Studien zu Sprachförderprogrammen zeigen unterschiedlich starke Effekte. Die Pflicht müssen die Länder regeln, das Bundesprogramm ist finanzierbar.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=65', null, 'gemischt', '2026-09-28', false, true, null),
  (4003, 4, 11, null, 'Verbindliche Vergleichsarbeiten und Lernstandserhebungen; bundesweit vergleichbares Abitur', '{403}', null, 1, 1, null, 'Lernstandserhebungen machen Rückstände sichtbar, beheben sie aber nicht selbst; die Forschung zu Wirkungen von Leistungsvergleichen ist uneinheitlich. Das regeln allein die Länder.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=65', null, 'gemischt', '2026-09-28', false, true, null),
  (4004, 4, 11, null, 'Ganztagsangebote für Grundschulkinder ausbauen, mit Schwerpunkt auf Lesen, Schreiben und Rechnen', '{403,405}', null, 1, 3, null, 'Ganztag kann Kinder aus benachteiligten Familien unterstützen, Effekte auf Leistungen hängen laut Studien stark von der Qualität ab. Der Bund fördert den Ausbau bereits.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=65', null, 'gemischt', '2026-09-28', false, true, null),
  (4011, 4, 12, null, 'Fachkräfteoffensive für Kitas und Schulen mit allen Ländern: mehr Ausbildungsplätze, Quereinstieg, multiprofessionelle Teams', '{401}', null, 2, 2, null, 'Mehr Ausbildungskapazität und Quereinstieg setzen am Lehrkräftemangel an, wirken aber erst mittelfristig; die Qualität des Quereinstiegs ist umstritten. Braucht eine Vereinbarung mit allen Ländern.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=15', null, 'gemischt', '2026-09-28', false, true, null),
  (4012, 4, 12, null, 'Entwicklungsstand aller Kinder mit vier Jahren und bei der Einschulung feststellen, bei Bedarf verbindliche Förderung', '{404}', null, 2, 2, null, 'Frühe Feststellung mit verbindlichem Förderangebot setzt direkt am Sprachförderbedarf an; Studien zeigen unterschiedlich starke Effekte. Umsetzung liegt bei den Ländern.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=15', null, 'gemischt', '2026-09-28', false, true, null),
  (4013, 4, 12, null, 'Startchancenprogramm an Schulen schrittweise ausbauen und eines für Kitas in benachteiligten Lagen schaffen', '{405,403}', null, 2, 2, null, 'Geld gezielt nach sozialer Lage zu verteilen setzt an der Kopplung von Herkunft und Schulerfolg an; die Evaluation des Programms läuft noch, internationale Erfahrungen sind gemischt. Ausbau braucht zusätzliche Mittel von Bund und Ländern.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=15', null, 'gemischt', '2026-09-28', false, true, null),
  (4014, 4, 12, null, 'Schuldenregel reformieren, damit Investitionen etwa in Schulgebäude möglich werden; auch Länder sollen Kredite aufnehmen dürfen', '{402}', null, 2, 1, null, 'Mehr Investitionsspielraum kann den Sanierungsstau abbauen, wenn das Geld bei Ländern und Kommunen ankommt. Die Reform erfordert eine Grundgesetzänderung mit Zweidrittelmehrheit.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=17', null, 'belegt', '2026-09-28', false, true, null),
  (4015, 4, 12, null, 'Gesundes, kostenloses Mittagessen für alle Kita-Kinder und Schülerinnen und Schüler, gemeinsam mit den Ländern', '{405}', 6067, 1, 2, null, 'Kostenfreies Essen entlastet benachteiligte Familien; Studien finden teils positive, meist kleine Effekte auf Lernen. Finanzierung mit den Ländern ist aufwendig.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=27', null, 'gemischt', '2026-09-28', false, true, null),
  (4021, 4, 13, null, '„Zukunftsinvestitionsprogramm Bildung“ mit Ländern und Kommunen, unter anderem für moderne, sanierte Schulgebäude', '{402}', 6068, 2, 2, null, 'Investitionsmittel setzen direkt am Sanierungsstau an; der Umfang ist nicht beziffert. Der Bund kann Schulbau nur über Finanzhilfen mitfinanzieren.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=77', null, 'belegt', '2026-09-28', false, true, null),
  (4022, 4, 13, null, 'Mehr Stellen für Schulsozialarbeit, Schulpsychologie und Inklusion; Schwerpunkt auf Basiskompetenzen', '{403}', null, 2, 1, null, 'Ein Fokus auf Basiskompetenzen und Unterstützung durch Fachpersonal setzt an Lernrückständen an; die Wirkung multiprofessioneller Teams ist unterschiedlich belegt. Stellen schaffen die Länder, und Fachpersonal ist knapp.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=77', null, 'gemischt', '2026-09-28', false, true, null),
  (4023, 4, 13, null, 'Länder bei der Lehrkräftegewinnung unterstützen: duale Studiengänge, Ein-Fach-Lehrkräfte, Wege für Quer- und Seiteneinstieg', '{401}', null, 2, 2, null, 'Neue Zugangswege erhöhen das Angebot an Lehrkräften, wirken aber erst mittelfristig; die Qualität des Quereinstiegs ist umstritten. Umsetzung liegt bei den Ländern, der Bund kann unterstützen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=77', null, 'gemischt', '2026-09-28', false, true, null),
  (4024, 4, 13, null, 'Bildungsmittel nach tatsächlichem Bedarf statt nach Königsteiner Schlüssel verteilen; Bildungsoffensive für mehr Schulen', '{405}', null, 2, 2, null, 'Bedarfsorientierte Verteilung lenkt Mittel zu Schulen mit vielen benachteiligten Kindern; internationale Erfahrungen damit sind gemischt. Braucht Einigung mit den Ländern.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=77', null, 'gemischt', '2026-09-28', false, true, null),
  (4025, 4, 13, null, 'Sprachförderung als durchgängiger Prozess von der Kita bis in die Ausbildung', '{404}', null, 1, 2, null, 'Durchgängige Sprachbildung setzt am Förderbedarf an, das Programm nennt aber kein konkretes Instrument wie Tests oder verbindliche Förderung. Umsetzung liegt bei den Ländern.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=78', null, 'gemischt', '2026-09-28', false, true, null),
  (4031, 4, 14, null, 'Bundesweit verpflichtende Sprachtests im Vorschulalter; bei Förderbedarf verpflichtende Sprachförderung zwei Jahre vor der Schule', '{404}', null, 2, 2, null, 'Verbindliche Tests mit verpflichtender Förderung setzen direkt am Sprachförderbedarf an; Studien zeigen unterschiedlich starke Effekte, ein späterer Schuleintritt ist umstritten. Umsetzung liegt bei den Ländern.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=7', null, 'gemischt', '2026-09-28', false, true, null),
  (4032, 4, 14, null, 'Startchancen-Programm für Kitas mit vielen sozial benachteiligten Kindern', '{405}', null, 2, 2, null, 'Gezielte Mittel für Kitas in benachteiligten Lagen setzen früh an der Kopplung von Herkunft und Bildungserfolg an; die Evidenz zu solchen Programmen ist gemischt. Braucht Mittel und Einigung mit den Ländern.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=7', null, 'gemischt', '2026-09-28', false, true, null),
  (4033, 4, 14, null, 'Sanierung der Schulgebäude; Digitalpakt 2.0 von Bund und Ländern', '{402}', null, 2, 1, null, 'Die Forderung setzt am Sanierungsstau an, nennt aber weder Umfang noch Finanzierung. Schulbau ist Aufgabe von Ländern und Kommunen.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=8', null, 'belegt', '2026-09-28', false, true, null),
  (4034, 4, 14, null, 'Lehrberuf attraktiver machen: bessere Arbeitsbedingungen, leistungsorientierte Bezahlung, duales Lehramtsstudium, Mobilitätsgarantie', '{401}', null, 2, 2, null, 'Attraktivere Bedingungen und ein praxisnäheres Studium können mehr Menschen für den Beruf gewinnen, wirken aber erst mittelfristig; die Mobilitätsgarantie verteilt vorhandene Lehrkräfte nur um. Umsetzung liegt bei den Ländern.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=9', null, 'gemischt', '2026-09-28', false, true, null),
  (4035, 4, 14, null, 'Bundesweit einheitliche Qualitätsstandards von der Kita bis zum Abschluss, Deutschland-Abitur und Notenpflicht ab Klasse 3', '{403}', null, 1, 1, null, 'Einheitliche Standards und Prüfungen machen Leistungen vergleichbar, beheben Rückstände aber nicht selbst; die Wirkung ist in der Forschung umstritten. Braucht eine Reform des Bildungsföderalismus.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=8', null, 'gemischt', '2026-09-28', false, true, null),
  (4036, 4, 14, null, 'Mehr Eigenständigkeit für Schulen mit frei einsetzbarem Chancenbudget', '{403}', null, 1, 2, null, 'Mehr Autonomie kann Schulen helfen, auf Rückstände zu reagieren; Studien zeigen positive Effekte vor allem zusammen mit Leistungsvergleichen. Das Budget ist nicht nach sozialer Lage gezielt.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=9', null, 'gemischt', '2026-09-28', false, true, null),
  (4041, 4, 15, null, 'Bedarfsorientierte Vorschule, damit alle Kinder dem Unterricht folgen können', '{404}', null, 2, 2, null, 'Eine Vorschule für Kinder mit Rückständen setzt direkt am Sprachförderbedarf an; Studien zu Vorschulprogrammen zeigen unterschiedlich starke Effekte. Umsetzung liegt bei den Ländern.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=160', null, 'gemischt', '2026-09-28', false, true, null),
  (4042, 4, 15, null, 'Verpflichtender Deutschunterricht für Kinder, die nicht genug Deutsch für den Regelunterricht sprechen', '{404}', null, 2, 2, null, 'Gezielter Deutschunterricht setzt am Sprachförderbedarf an; ob getrennter oder integrierter Unterricht besser wirkt, ist in der Forschung umstritten. Umsetzung liegt bei den Ländern.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=162', null, 'gemischt', '2026-09-28', false, true, null),
  (4043, 4, 15, null, 'Klassenstärken an allen Schulformen verringern', '{403}', null, 1, 1, null, 'Kleinere Klassen helfen laut Studien vor allem in den ersten Schuljahren, sonst sind die Effekte gering. Sie brauchen deutlich mehr Lehrkräfte, die schon jetzt fehlen.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=159', null, 'gemischt', '2026-09-28', false, true, null),
  (4044, 4, 15, null, 'Bildungsstandards aller Schulformen anheben statt Leistungsanforderungen zu senken', '{403}', null, 1, 1, null, 'Höhere Standards benennen ein Ziel, sagen aber nicht, wie Rückstände aufgeholt werden. Die Standards legen allein die Länder in der Kultusministerkonferenz fest.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=159', null, 'offen', '2026-09-28', false, true, null),
  (4051, 4, 16, null, 'Vertretungsreserve von zehn Prozent; Anerkennung zugewanderter Lehrkräfte und Ausbildung von Quer- und Seiteneinsteigern', '{401}', null, 2, 2, null, 'Anerkennung und Quereinstieg erhöhen das Angebot an Lehrkräften; eine Vertretungsreserve setzt voraus, dass zusätzliche Lehrkräfte gefunden werden. Umsetzung liegt bei den Ländern.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=38', null, 'gemischt', '2026-09-28', false, true, null),
  (4052, 4, 16, null, '100-Milliarden-Euro-Sondervermögen des Bundes für Sanierung und Modernisierung von Bildungseinrichtungen, später Vermögensteuer', '{402}', null, 2, 1, null, 'Ein großes Investitionsprogramm setzt direkt am Sanierungsstau an. Ein kreditfinanziertes Sondervermögen und die Vermögensteuer sind rechtlich und politisch mit großen Hürden verbunden.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=38', null, 'belegt', '2026-09-28', false, true, null),
  (4053, 4, 16, null, 'Kostenlose Lernmittel, Verpflegung und Schülerbeförderung', '{405}', null, 1, 2, null, 'Kostenfreiheit entlastet benachteiligte Familien; Wirkungen auf den Schulerfolg sind meist klein. Braucht Mittel von Bund, Ländern und Kommunen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=38', null, 'gemischt', '2026-09-28', false, true, null),
  (4054, 4, 16, null, 'Hausaufgaben abschaffen, Üben findet in der Schule statt', '{405}', null, 1, 1, null, 'Üben in der Schule kann Unterschiede durch häusliche Unterstützung verringern; Hausaufgaben haben laut Studien in höheren Klassen aber positive Effekte. Regelungen dazu treffen die Länder.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=38', null, 'gemischt', '2026-09-28', false, true, null),
  (4055, 4, 16, null, 'Eine ganztägige Gemeinschaftsschule für alle statt des gegliederten Schulsystems', '{405}', null, 2, 1, null, 'Längeres gemeinsames Lernen soll die Kopplung von Herkunft und Schulerfolg verringern; internationale Studien stützen das teilweise, deutsche Vergleiche sind uneinheitlich. Die Schulstruktur bestimmen die Länder.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=39', null, 'gemischt', '2026-09-28', false, true, null),
  (4056, 4, 16, null, 'Mehr Pädagoginnen und Pädagogen pro Klasse; Schulpsychologie und Sozialarbeit an jeder Schule', '{403}', null, 2, 1, null, 'Mehr Personal pro Klasse ermöglicht individuelle Förderung; die Wirkung ist unterschiedlich belegt. Es braucht zusätzliches Personal, das schon jetzt fehlt.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=39', null, 'gemischt', '2026-09-28', false, true, null),
  (4057, 4, 16, null, 'Bundesprogramm für Lehrkräfte in Deutsch als Zweitsprache und Sprachkurse auch für Eltern und Geschwister', '{404}', null, 2, 2, null, 'Mehr qualifizierte Sprachförderung in Schulen und für Familien setzt am Förderbedarf an; Studien zeigen unterschiedlich starke Effekte. Ein Bundesprogramm ist mit den Ländern umsetzbar.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=39', null, 'gemischt', '2026-09-28', false, true, null),
  (4061, 4, 17, null, 'Länder bei der Ausbildung von mehr Lehrkräften unterstützen; duale Lehrerausbildung; bessere Bedingungen für Seiteneinsteiger; Entlastung durch Unterstützungsteams', '{401}', null, 2, 2, null, 'Mehr Ausbildung und Seiteneinstieg setzen am Lehrkräftemangel an, wirken aber erst mittelfristig; die Qualität des Seiteneinstiegs ist umstritten. Umsetzung liegt bei den Ländern, der Bund kann unterstützen.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=25', null, 'gemischt', '2026-09-29', false, true, null),
  (4062, 4, 17, null, 'Investitionen unter anderem in Schulen aus der Schuldenbremse ausklammern', '{402}', null, 2, 1, null, 'Mehr Investitionsspielraum kann den Sanierungsstau abbauen, wenn das Geld bei Ländern und Kommunen ankommt. Die Änderung der Schuldenbremse erfordert eine Grundgesetzänderung mit Zweidrittelmehrheit.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=15', null, 'belegt', '2026-09-29', false, true, null),
  (4063, 4, 17, null, 'Investitionsprogramm „Kinder und Bildung“ für marode Bildungs- und Betreuungseinrichtungen in Städten und Gemeinden', '{402}', 6068, 2, 2, null, 'Investitionsmittel setzen direkt am Sanierungsstau an; der Umfang ist nicht beziffert. Der Bund kann Schulbau nur über Finanzhilfen mitfinanzieren.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=32', null, 'belegt', '2026-09-29', false, true, null),
  (4064, 4, 17, null, 'Verpflichtender Deutschtest ab drei Jahren; bei Defiziten verpflichtender, beitragsfreier Kita-Besuch mit Sprachbildung', '{404}', null, 2, 2, null, 'Frühe verbindliche Tests mit verpflichtender Förderung setzen direkt am Sprachförderbedarf an; Studien zeigen unterschiedlich starke Effekte. Umsetzung liegt bei den Ländern.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=24', null, 'gemischt', '2026-09-29', false, true, null),
  (4065, 4, 17, null, 'Ganztagsschulen sowie Hort- und Hausaufgabenbetreuung ausbauen, damit Kinder weniger von der Unterstützung der Eltern abhängen', '{405}', null, 1, 2, null, 'Ganztag kann Kinder aus benachteiligten Familien unterstützen, Effekte auf Leistungen hängen laut Studien stark von der Qualität ab. Der Bund fördert bisher nur den Ganztag an Grundschulen.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=24', null, 'gemischt', '2026-09-29', false, true, null),
  (4066, 4, 17, null, 'Längeres gemeinsames Lernen und ein durchlässiges Schulsystem statt früher Aufteilung nach Klasse 4', '{405}', null, 2, 1, null, 'Später aufzuteilen soll die Kopplung von Herkunft und Schulerfolg verringern; internationale Studien stützen das teilweise, deutsche Vergleiche sind uneinheitlich. Die Schulstruktur bestimmen allein die Länder.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=24', null, 'gemischt', '2026-09-29', false, true, null),
  (4067, 4, 17, null, 'Grundschule auf Lesen, Schreiben und Rechnen konzentrieren; Handys und Tablets bis Ende der Grundschule aus dem Unterricht', '{403}', null, 1, 1, null, 'Ein Fokus auf Basiskompetenzen setzt an Lernrückständen an; zur Wirkung von Geräteverboten ist die Forschung uneinheitlich. Das regeln allein die Länder.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=24', null, 'gemischt', '2026-09-29', false, true, null),
  (4068, 4, 17, null, 'Kostenloses, gesundes Mittagessen in Kitas und Schulen', '{405}', 6067, 1, 2, null, 'Kostenfreies Essen entlastet benachteiligte Familien; Studien finden teils positive, meist kleine Effekte auf Lernen. Finanzierung mit den Ländern ist aufwendig.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=31', null, 'gemischt', '2026-09-29', false, true, null),
  (4101, 4, 11, 'ST', 'Verbindliche Sprachstandsfeststellung im vierten Lebensjahr; letztes Kita-Jahr als Vorschuljahr mit Förderung', '{404}', 6069, 2, 3, null, 'Eine verbindliche Sprachstandsfeststellung mit anschließender Förderpflicht setzt direkt am Sprachförderbedarf an; Studien zu Sprachförderprogrammen zeigen unterschiedlich starke Effekte. Das Land ist zuständig und kann das per Gesetz regeln.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=48', null, 'gemischt', '2026-09-29', false, true, null),
  (4102, 4, 11, 'ST', 'Unterricht in Mathematik und Deutsch an Grundschulen ausbauen', '{403}', 6070, 2, 2, null, 'Mehr Unterrichtszeit für Lesen, Schreiben und Rechnen kann Basiskompetenzen stärken; Studien finden Effekte vor allem bei gezielter, gut angeleiteter Übung. Braucht zusätzliche Lehrkräftestunden, die knapp sind.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=21', null, 'gemischt', '2026-09-29', false, true, null),
  (4103, 4, 11, 'ST', 'Schulen in sozial herausfordernden Lagen mit zusätzlichem Personal, Förderangeboten und Ausstattung unterstützen', '{405}', 6071, 2, 2, null, 'Zusätzliche Mittel und Personal für Schulen in schwieriger Lage setzen an der Kopplung von Herkunft und Schulerfolg an; die Evaluation des Startchancen-Programms läuft noch, internationale Erfahrungen sind gemischt. Das Land kann Mittel umverteilen, zusätzliches Personal ist knapp.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=22', null, 'gemischt', '2026-09-29', false, true, null),
  (4104, 4, 11, 'ST', 'Schulen dürfen Vertretungspersonal und Unterstützungskräfte einstellen; Unterstützung in Unterricht und Verwaltung ausbauen', '{401}', 6072, 2, 2, null, 'Verwaltungs- und Unterstützungskräfte nehmen Lehrkräften Aufgaben ab und schaffen Zeit für Unterricht; Studien zu solchen Assistenzkräften zeigen positive, aber unterschiedlich große Effekte. Das Land kann die Stellen schaffen, Finanzierung und Bewerberlage sind die Hürden.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=20', null, 'gemischt', '2026-09-29', false, true, null),
  (4105, 4, 11, 'ST', 'Duales Lehramtsstudium verstetigen und zum Standard ausbauen; Hochschulen an Absolventenzahlen messen', '{401}', 6073, 2, 2, null, 'Mehr und praxisnähere Lehramtsausbildung setzt am Lehrkräftemangel an, wirkt aber erst nach Jahren; wie viele zusätzliche Lehrkräfte im Land ankommen, ist offen. Das Land kann seine Hochschulen selbst steuern.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=24', null, 'gemischt', '2026-09-29', false, true, null),
  (4106, 4, 11, 'ST', 'Zulage für Referendare außerhalb der Oberzentren; Stipendium für Lehramtsstudierende; Wege für Seiteneinsteiger', '{401}', 6074, 1, 2, null, 'Zulagen, Stipendien oder Verpflichtungen können Lehrkräfte in unterversorgte Regionen oder Schulen lenken; die Gesamtzahl der Lehrkräfte steigt dadurch kaum. Für das Land finanzierbar, aber mit dauerhaften Kosten.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=24', null, 'gemischt', '2026-09-29', false, true, null),
  (4107, 4, 11, 'ST', 'Klare Aus- und Fortbildungswege für Seiteneinsteigerinnen und Seiteneinsteiger', '{401}', 6075, 2, 3, null, 'Seiten- und Quereinstieg mit Qualifizierung gewinnt kurzfristig zusätzliche Lehrkräfte; wie gut das gelingt, hängt stark von der Nachqualifizierung ab. Das Land ist zuständig und praktiziert das bereits.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=24', null, 'gemischt', '2026-09-29', false, true, null),
  (4111, 4, 12, 'ST', 'Landesschulbauprogramm', '{402}', 6076, 2, 2, null, 'Ein Schulbauprogramm setzt direkt am Sanierungsstau an; wie weit es reicht, hängt von Umfang, Baukapazitäten und Kommunen ab. Das Programm nennt keinen Betrag, die Finanzierung muss das Land im Haushalt sichern.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=18', null, 'belegt', '2026-09-29', false, true, null),
  (4112, 4, 12, 'ST', 'Mehr Zeit im Stundenplan für Rechnen, Lesen, Vorlesen, Üben und Wiederholen', '{403}', 6070, 2, 2, null, 'Mehr Unterrichtszeit für Lesen, Schreiben und Rechnen kann Basiskompetenzen stärken; Studien finden Effekte vor allem bei gezielter, gut angeleiteter Übung. Braucht zusätzliche Lehrkräftestunden, die knapp sind.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=18', null, 'gemischt', '2026-09-29', false, true, null),
  (4113, 4, 12, 'ST', 'Duales Studium und Praxisanteile in der Lehramtsausbildung ausbauen; 1.200 Studienplätze halten', '{401}', 6073, 2, 2, null, 'Mehr und praxisnähere Lehramtsausbildung setzt am Lehrkräftemangel an, wirkt aber erst nach Jahren; wie viele zusätzliche Lehrkräfte im Land ankommen, ist offen. Das Land kann seine Hochschulen selbst steuern.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=18', null, 'gemischt', '2026-09-29', false, true, null),
  (4114, 4, 12, 'ST', 'Seiteneinsteigende qualifiziert begleiten und fair bezahlen', '{401}', 6075, 2, 3, null, 'Seiten- und Quereinstieg mit Qualifizierung gewinnt kurzfristig zusätzliche Lehrkräfte; wie gut das gelingt, hängt stark von der Nachqualifizierung ab. Das Land ist zuständig und praktiziert das bereits.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=18', null, 'gemischt', '2026-09-29', false, true, null),
  (4115, 4, 12, 'ST', 'Multiprofessionelle Teams mit Fachkräften für Verwaltung und digitale Ausstattung', '{401}', 6072, 2, 2, null, 'Verwaltungs- und Unterstützungskräfte nehmen Lehrkräften Aufgaben ab und schaffen Zeit für Unterricht; Studien zu solchen Assistenzkräften zeigen positive, aber unterschiedlich große Effekte. Das Land kann die Stellen schaffen, Finanzierung und Bewerberlage sind die Hürden.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=18', null, 'gemischt', '2026-09-29', false, true, null),
  (4116, 4, 12, 'ST', 'Frühere Schuleingangsuntersuchungen und stärkere Sprachförderung', '{404}', 6077, 1, 3, null, 'Mehr Sprachförderung in Kitas setzt am Sprachförderbedarf an; ohne verbindliche Feststellung und Förderpflicht erreicht sie nicht sicher alle Kinder mit Bedarf. Das Land ist zuständig.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=17', null, 'gemischt', '2026-09-29', false, true, null),
  (4117, 4, 12, 'ST', 'Gezielte sachliche und personelle Unterstützung für Schulen mit besonderen sozialen Herausforderungen', '{405}', 6071, 2, 2, null, 'Zusätzliche Mittel und Personal für Schulen in schwieriger Lage setzen an der Kopplung von Herkunft und Schulerfolg an; die Evaluation des Startchancen-Programms läuft noch, internationale Erfahrungen sind gemischt. Das Land kann Mittel umverteilen, zusätzliches Personal ist knapp.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=19', null, 'gemischt', '2026-09-29', false, true, null),
  (4118, 4, 12, 'ST', 'Schulsozialarbeit dauerhaft aus Landesmitteln finanzieren und ausbauen', '{405}', 6078, 1, 3, null, 'Schulsozialarbeit unterstützt Kinder in schwierigen Lagen; Wirkungen auf Leistungen sind kaum belegt. Das Land kann die Finanzierung übernehmen.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=18', null, 'gemischt', '2026-09-29', false, true, null),
  (4119, 4, 12, 'ST', 'Mittelfristig zwei weiterführende Schulformen: Gymnasium und Gemeinschaftsschule', '{405}', 6079, 1, 2, null, 'Längeres gemeinsames Lernen soll den Einfluss der Herkunft verringern; ob die Schulstruktur den Schulerfolg beeinflusst, ist in der Forschung nicht entschieden. Eine Strukturreform braucht Jahre.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=18', null, 'offen', '2026-09-29', false, true, null),
  (4121, 4, 13, 'ST', 'Umfassendes Schulbauprogramm für Sanierungen; Sofortprogramm für Schultoiletten', '{402}', 6076, 2, 2, null, 'Ein Schulbauprogramm setzt direkt am Sanierungsstau an; wie weit es reicht, hängt von Umfang, Baukapazitäten und Kommunen ab. Das Programm nennt keinen Betrag, die Finanzierung muss das Land im Haushalt sichern.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=62', null, 'belegt', '2026-09-29', false, true, null),
  (4122, 4, 13, 'ST', 'Landesspezifischer Schulsozialindex für die gezielte Verteilung zusätzlicher Mittel', '{405}', 6071, 2, 2, null, 'Zusätzliche Mittel und Personal für Schulen in schwieriger Lage setzen an der Kopplung von Herkunft und Schulerfolg an; die Evaluation des Startchancen-Programms läuft noch, internationale Erfahrungen sind gemischt. Das Land kann Mittel umverteilen, zusätzliches Personal ist knapp.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=62', null, 'gemischt', '2026-09-29', false, true, null),
  (4123, 4, 13, 'ST', 'Landesweit verbindliche Sprachstandsfeststellung in Kitas', '{404}', 6069, 2, 3, null, 'Eine verbindliche Sprachstandsfeststellung mit anschließender Förderpflicht setzt direkt am Sprachförderbedarf an; Studien zu Sprachförderprogrammen zeigen unterschiedlich starke Effekte. Das Land ist zuständig und kann das per Gesetz regeln.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=57', null, 'gemischt', '2026-09-29', false, true, null),
  (4124, 4, 13, 'ST', 'Seiteneinsteiger berufsbegleitend qualifizieren; Ein-Fach-Lehrkräfte zulassen', '{401}', 6075, 2, 3, null, 'Seiten- und Quereinstieg mit Qualifizierung gewinnt kurzfristig zusätzliche Lehrkräfte; wie gut das gelingt, hängt stark von der Nachqualifizierung ab. Das Land ist zuständig und praktiziert das bereits.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=61', null, 'gemischt', '2026-09-29', false, true, null),
  (4125, 4, 13, 'ST', 'Lehramtsstudiengänge dauerhaft ausbauen; duales Lehramtsstudium an beiden Universitäten', '{401}', 6073, 2, 2, null, 'Mehr und praxisnähere Lehramtsausbildung setzt am Lehrkräftemangel an, wirkt aber erst nach Jahren; wie viele zusätzliche Lehrkräfte im Land ankommen, ist offen. Das Land kann seine Hochschulen selbst steuern.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=61', null, 'gemischt', '2026-09-29', false, true, null),
  (4126, 4, 13, 'ST', 'Gehaltszuschläge für Lehrkräfte in strukturschwachen Regionen, belasteten Schulformen und Mangelfächern', '{401}', 6074, 1, 2, null, 'Zulagen, Stipendien oder Verpflichtungen können Lehrkräfte in unterversorgte Regionen oder Schulen lenken; die Gesamtzahl der Lehrkräfte steigt dadurch kaum. Für das Land finanzierbar, aber mit dauerhaften Kosten.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=61', null, 'gemischt', '2026-09-29', false, true, null),
  (4127, 4, 13, 'ST', 'Multiprofessionelle Teams und flächendeckend wieder Schulsekretariate', '{401}', 6072, 2, 2, null, 'Verwaltungs- und Unterstützungskräfte nehmen Lehrkräften Aufgaben ab und schaffen Zeit für Unterricht; Studien zu solchen Assistenzkräften zeigen positive, aber unterschiedlich große Effekte. Das Land kann die Stellen schaffen, Finanzierung und Bewerberlage sind die Hürden.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=60', null, 'gemischt', '2026-09-29', false, true, null),
  (4128, 4, 13, 'ST', 'Gemeinsame Grundschulzeit bis Klasse 6; Gemeinschaftsschulen statt Sekundarschulen', '{405}', 6079, 1, 2, null, 'Längeres gemeinsames Lernen soll den Einfluss der Herkunft verringern; ob die Schulstruktur den Schulerfolg beeinflusst, ist in der Forschung nicht entschieden. Eine Strukturreform braucht Jahre.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=59', null, 'offen', '2026-09-29', false, true, null),
  (4129, 4, 13, 'ST', 'Alle allgemeinbildenden Schulen zu Ganztagsschulen; kostenfreie Lernmittel und Mittagessen', '{405}', 6080, 1, 2, null, 'Ganztag kann Kinder aus benachteiligten Familien unterstützen, Effekte auf Leistungen hängen laut Studien stark von der Qualität ab. Der Ausbau braucht Personal und Räume.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=59', null, 'gemischt', '2026-09-29', false, true, null),
  (4130, 4, 13, 'ST', 'An jeder Schule mindestens eine fest angestellte Schulsozialarbeiterin oder ein Schulsozialarbeiter', '{405}', 6078, 1, 3, null, 'Schulsozialarbeit unterstützt Kinder in schwierigen Lagen; Wirkungen auf Leistungen sind kaum belegt. Das Land kann die Finanzierung übernehmen.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=62', null, 'gemischt', '2026-09-29', false, true, null),
  (4131, 4, 14, 'ST', 'Verbindliche Sprachstandsfeststellung mit drei Jahren; Defizite bis Schulbeginn aufholen', '{404}', 6069, 2, 3, null, 'Eine verbindliche Sprachstandsfeststellung mit anschließender Förderpflicht setzt direkt am Sprachförderbedarf an; Studien zu Sprachförderprogrammen zeigen unterschiedlich starke Effekte. Das Land ist zuständig und kann das per Gesetz regeln.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=24', null, 'gemischt', '2026-09-29', false, true, null),
  (4132, 4, 14, 'ST', 'Verbindliches 1,5-jähriges Qualifizierungsprogramm für Seiteneinsteiger', '{401}', 6075, 2, 3, null, 'Seiten- und Quereinstieg mit Qualifizierung gewinnt kurzfristig zusätzliche Lehrkräfte; wie gut das gelingt, hängt stark von der Nachqualifizierung ab. Das Land ist zuständig und praktiziert das bereits.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=30', null, 'gemischt', '2026-09-29', false, true, null),
  (4133, 4, 14, 'ST', 'Zugang zum Lehramtsstudium erweitern, etwa mit Fachhochschulreife; Bewerber mit Berufserfahrung zulassen', '{401}', 6073, 2, 2, null, 'Mehr und praxisnähere Lehramtsausbildung setzt am Lehrkräftemangel an, wirkt aber erst nach Jahren; wie viele zusätzliche Lehrkräfte im Land ankommen, ist offen. Das Land kann seine Hochschulen selbst steuern.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=30', null, 'gemischt', '2026-09-29', false, true, null),
  (4134, 4, 14, 'ST', 'Weiterhin Unterstützungskräfte einstellen, um Lehrkräfte zu entlasten', '{401}', 6072, 2, 2, null, 'Verwaltungs- und Unterstützungskräfte nehmen Lehrkräften Aufgaben ab und schaffen Zeit für Unterricht; Studien zu solchen Assistenzkräften zeigen positive, aber unterschiedlich große Effekte. Das Land kann die Stellen schaffen, Finanzierung und Bewerberlage sind die Hürden.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=30', null, 'gemischt', '2026-09-29', false, true, null),
  (4135, 4, 14, 'ST', 'Public-Private-Partnership-Modelle für Bau und Sanierung von Schulen', '{402}', null, 1, 2, null, 'Private Partner können Bau und Sanierung beschleunigen; Rechnungshöfe fanden solche Projekte aber oft teurer als konventionelle. Das Land kann Kommunen dabei unterstützen, zusätzliches Geld nennt das Programm nicht.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=29', null, 'gemischt', '2026-09-29', false, true, null),
  (4136, 4, 14, 'ST', 'Datengestützte Förderung: Lern- und Entwicklungsstände früh erkennen und in Förderung übersetzen', '{403}', null, 1, 3, null, 'Regelmäßige Lernstandserhebungen machen Rückstände sichtbar; ob sie wirken, hängt von der Förderung danach ab, die Forschung ist uneinheitlich. Das Land kann das selbst einführen.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=26', null, 'gemischt', '2026-09-29', false, true, null),
  (4137, 4, 14, 'ST', 'Landeseinheitlicher Schülerkostensatz, der auch einen Sozialindex berücksichtigt', '{405}', null, 1, 2, null, 'Ein einheitlicher Kostensatz je Schüler mit Sozialindex kann Mittel gerechter verteilen; wie stark er Schulen in schwieriger Lage besserstellt, lässt das Programm offen. Das Land kann das regeln, Mehrkosten sind möglich.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=28', null, 'offen', '2026-09-29', false, true, null),
  (4141, 4, 15, 'ST', 'Pensionierte und bald pensionierte Lehrkräfte ansprechen, damit sie weiter unterrichten', '{401}', 6081, 1, 3, null, 'Pensionierte Lehrkräfte zurückzugewinnen hilft kurzfristig; erfahrungsgemäß kehren nur wenige zurück, eine dauerhafte Lösung ist es nicht. Für das Land leicht umsetzbar.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=83', null, 'gemischt', '2026-09-29', false, true, null),
  (4142, 4, 15, 'ST', 'Bundesweite Anwerbekampagne für Lehrkräfte; Schulbetrieb entbürokratisieren', '{401}', null, 1, 2, null, 'Eine Anwerbekampagne kann Lehrkräfte aus anderen Ländern gewinnen; sie konkurrieren aber alle um dieselben knappen Lehrkräfte, die Gesamtzahl steigt nicht. Für das Land umsetzbar.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=83', null, 'gemischt', '2026-09-29', false, true, null),
  (4143, 4, 15, 'ST', 'Pädagogische Hochschule für die Ausbildung aller Grund- und Sekundarschullehrkräfte', '{401}', null, 1, 2, null, 'Eine Pädagogische Hochschule bündelt die Ausbildung, schafft aber für sich genommen keine zusätzlichen Studienplätze; ob sie mehr Absolventen bringt, ist offen. Die Gründung braucht mehrere Jahre.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=84', null, 'offen', '2026-09-29', false, true, null),
  (4144, 4, 15, 'ST', 'Verbindliche Schullaufbahnempfehlung nach Klasse 4 auf Basis zentraler Klassenarbeiten', '{403}', 6082, 1, 3, null, 'Leistungsabhängige Übergänge ins Gymnasium sollen passgenauer fördern; ob die Schulstruktur die Leistungen verbessert, ist in der Forschung nicht entschieden. Das Land kann es im Schulgesetz regeln.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=73', null, 'offen', '2026-09-29', false, true, null),
  (4145, 4, 15, 'ST', 'Smartphone-Nutzung bis einschließlich Klasse 10 untersagen', '{403}', 6083, 1, 3, null, 'Ein Handyverbot kann Ablenkung im Unterricht verringern; Studien zu Wirkungen auf Leistungen sind gemischt. Das Land kann es per Erlass oder Gesetz regeln.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=79', null, 'gemischt', '2026-09-29', false, true, null),
  (4146, 4, 15, 'ST', 'Mehr Vorlesen in der vorschulischen Bildung', '{404}', null, 1, 3, null, 'Vorlesen fördert die Sprachentwicklung; ohne Feststellung des Förderbedarfs erreicht es Kinder mit Sprachförderbedarf aber nicht gezielt. Das Land kann das in den Bildungsplan aufnehmen.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=20', null, 'offen', '2026-09-29', false, true, null),
  (4151, 4, 16, 'ST', 'Lehramtsausbildung in Magdeburg um 200 Erstsemesterplätze erweitern, auch dual mit Bindung ans Land', '{401}', 6073, 2, 2, null, 'Mehr und praxisnähere Lehramtsausbildung setzt am Lehrkräftemangel an, wirkt aber erst nach Jahren; wie viele zusätzliche Lehrkräfte im Land ankommen, ist offen. Das Land kann seine Hochschulen selbst steuern.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=34', null, 'gemischt', '2026-09-29', false, true, null),
  (4152, 4, 16, 'ST', 'Seiteneinstieg unterstützen: Entlastung im ersten Jahr, mehr Fortbildung, Vorbereitungsdienst auch mit einem Fach', '{401}', 6075, 2, 3, null, 'Seiten- und Quereinstieg mit Qualifizierung gewinnt kurzfristig zusätzliche Lehrkräfte; wie gut das gelingt, hängt stark von der Nachqualifizierung ab. Das Land ist zuständig und praktiziert das bereits.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=34', null, 'gemischt', '2026-09-29', false, true, null),
  (4153, 4, 16, 'ST', 'Schulverwaltungs- und Digitalassistenzen bedarfsdeckend einsetzen', '{401}', 6072, 2, 2, null, 'Verwaltungs- und Unterstützungskräfte nehmen Lehrkräften Aufgaben ab und schaffen Zeit für Unterricht; Studien zu solchen Assistenzkräften zeigen positive, aber unterschiedlich große Effekte. Das Land kann die Stellen schaffen, Finanzierung und Bewerberlage sind die Hürden.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=34', null, 'gemischt', '2026-09-29', false, true, null),
  (4154, 4, 16, 'ST', 'Seminare für den Vorbereitungsdienst in der Fläche; Anwärtersonderbezüge', '{401}', 6074, 1, 2, null, 'Zulagen, Stipendien oder Verpflichtungen können Lehrkräfte in unterversorgte Regionen oder Schulen lenken; die Gesamtzahl der Lehrkräfte steigt dadurch kaum. Für das Land finanzierbar, aber mit dauerhaften Kosten.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=34', null, 'gemischt', '2026-09-29', false, true, null),
  (4155, 4, 16, 'ST', 'Schulbauprogramm des Landes und deutlich höhere Finanzzuweisungen an Kommunen für Bau und Sanierung', '{402}', 6076, 2, 2, null, 'Ein Schulbauprogramm setzt direkt am Sanierungsstau an; wie weit es reicht, hängt von Umfang, Baukapazitäten und Kommunen ab. Das Programm nennt keinen Betrag, die Finanzierung muss das Land im Haushalt sichern.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=33', null, 'belegt', '2026-09-29', false, true, null),
  (4156, 4, 16, 'ST', 'Sprachförderung ab der Kita', '{404}', 6077, 1, 3, null, 'Mehr Sprachförderung in Kitas setzt am Sprachförderbedarf an; ohne verbindliche Feststellung und Förderpflicht erreicht sie nicht sicher alle Kinder mit Bedarf. Das Land ist zuständig.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=99', null, 'gemischt', '2026-09-29', false, true, null),
  (4157, 4, 16, 'ST', 'Schulsozialarbeit gesetzlich verankern: eine Stelle je 150 Schüler, rund 1.200 Vollzeitstellen', '{405}', 6078, 1, 3, null, 'Schulsozialarbeit unterstützt Kinder in schwierigen Lagen; Wirkungen auf Leistungen sind kaum belegt. Das Land kann die Finanzierung übernehmen.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=28', null, 'gemischt', '2026-09-29', false, true, null),
  (4158, 4, 16, 'ST', 'Mittelfristig ein Schulsystem aus Gemeinschaftsschulen und Gymnasien', '{405}', 6079, 1, 2, null, 'Längeres gemeinsames Lernen soll den Einfluss der Herkunft verringern; ob die Schulstruktur den Schulerfolg beeinflusst, ist in der Forschung nicht entschieden. Eine Strukturreform braucht Jahre.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=31', null, 'offen', '2026-09-29', false, true, null),
  (4159, 4, 16, 'ST', 'Ganztagsangebote an allen weiterführenden Schulen ausbauen', '{405}', 6080, 1, 2, null, 'Ganztag kann Kinder aus benachteiligten Familien unterstützen, Effekte auf Leistungen hängen laut Studien stark von der Qualität ab. Der Ausbau braucht Personal und Räume.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=32', null, 'gemischt', '2026-09-29', false, true, null),
  (4161, 4, 17, 'ST', 'Mehr Lehramtsstudienplätze; Praxisbezug und duales Lehramtsstudium ausbauen', '{401}', 6073, 2, 2, null, 'Mehr und praxisnähere Lehramtsausbildung setzt am Lehrkräftemangel an, wirkt aber erst nach Jahren; wie viele zusätzliche Lehrkräfte im Land ankommen, ist offen. Das Land kann seine Hochschulen selbst steuern.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=52', null, 'gemischt', '2026-09-29', false, true, null),
  (4162, 4, 17, 'ST', 'Allen Lehramtsabsolventen ein Stellenangebot im Schuldienst machen', '{401}', null, 1, 3, null, 'Ein sicheres Stellenangebot kann Absolventen im Land halten; die Zahl der Absolventen steigt dadurch nicht. Für das Land umsetzbar.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=52', null, 'gemischt', '2026-09-29', false, true, null),
  (4163, 4, 17, 'ST', 'Multiprofessionelle Teams mit Verwaltungspersonal, IT-Unterstützung und Lehrerassistenzen als Standard', '{401}', 6072, 2, 2, null, 'Verwaltungs- und Unterstützungskräfte nehmen Lehrkräften Aufgaben ab und schaffen Zeit für Unterricht; Studien zu solchen Assistenzkräften zeigen positive, aber unterschiedlich große Effekte. Das Land kann die Stellen schaffen, Finanzierung und Bewerberlage sind die Hürden.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=48', null, 'gemischt', '2026-09-29', false, true, null),
  (4164, 4, 17, 'ST', 'Verbindliche Sprachstandserhebungen vor Schuleintritt; frühzeitige Sprachförderung ausbauen', '{404}', 6069, 2, 3, null, 'Eine verbindliche Sprachstandsfeststellung mit anschließender Förderpflicht setzt direkt am Sprachförderbedarf an; Studien zu Sprachförderprogrammen zeigen unterschiedlich starke Effekte. Das Land ist zuständig und kann das per Gesetz regeln.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=46', null, 'gemischt', '2026-09-29', false, true, null),
  (4165, 4, 17, 'ST', 'Verbindliches Smartphone-Verbot im Schulalltag', '{403}', 6083, 1, 3, null, 'Ein Handyverbot kann Ablenkung im Unterricht verringern; Studien zu Wirkungen auf Leistungen sind gemischt. Das Land kann es per Erlass oder Gesetz regeln.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=45', null, 'gemischt', '2026-09-29', false, true, null),
  (4166, 4, 17, 'ST', 'Längeres gemeinsames Lernen bis Klasse 6, perspektivisch bis Klasse 8', '{405}', 6079, 1, 2, null, 'Längeres gemeinsames Lernen soll den Einfluss der Herkunft verringern; ob die Schulstruktur den Schulerfolg beeinflusst, ist in der Forschung nicht entschieden. Eine Strukturreform braucht Jahre.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=45', null, 'offen', '2026-09-29', false, true, null),
  (4167, 4, 17, 'ST', 'Mindestens eine Schulsozialarbeiterstelle an jeder Schule', '{405}', 6078, 1, 3, null, 'Schulsozialarbeit unterstützt Kinder in schwierigen Lagen; Wirkungen auf Leistungen sind kaum belegt. Das Land kann die Finanzierung übernehmen.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=47', null, 'gemischt', '2026-09-29', false, true, null),
  (4168, 4, 17, 'ST', 'Landeseigenes Ganztagsförderprogramm und Qualitätsoffensive „Ganztag 2030“', '{405}', 6080, 1, 2, null, 'Ganztag kann Kinder aus benachteiligten Familien unterstützen, Effekte auf Leistungen hängen laut Studien stark von der Qualität ab. Der Ausbau braucht Personal und Räume.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=48', null, 'gemischt', '2026-09-29', false, true, null),
  (4169, 4, 17, 'ST', 'Kostenfreie, gesunde Verpflegung in Kitas und Schulen', '{405}', 6084, 1, 2, null, 'Kostenfreies Essen und Lernmittel entlasten benachteiligte Familien; Studien finden teils positive, meist kleine Effekte auf das Lernen. Dauerhafte Kosten für das Land.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=49', null, 'gemischt', '2026-09-29', false, true, null),
  (4201, 4, 11, 'MV', 'Verpflichtende Sprachstandsfeststellung mit vier bis fünf Jahren; bei Bedarf verpflichtende Förderung in Kita oder Vorschulklasse', '{404}', 6069, 2, 3, null, 'Eine verbindliche Sprachstandsfeststellung mit anschließender Förderpflicht setzt direkt am Sprachförderbedarf an; Studien zu Sprachförderprogrammen zeigen unterschiedlich starke Effekte. Das Land ist zuständig und kann das per Gesetz regeln.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=46', null, 'gemischt', '2026-09-29', false, true, null),
  (4202, 4, 11, 'MV', 'Ressourcen an Grundschulen nach Problemlagen zuweisen, Schulen in benachteiligten Gebieten stärken', '{405}', 6071, 2, 2, null, 'Zusätzliche Mittel und Personal für Schulen in schwieriger Lage setzen an der Kopplung von Herkunft und Schulerfolg an; die Evaluation des Startchancen-Programms läuft noch, internationale Erfahrungen sind gemischt. Das Land kann Mittel umverteilen, zusätzliches Personal ist knapp.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=47', null, 'gemischt', '2026-09-29', false, true, null),
  (4203, 4, 11, 'MV', 'Lehrkräfte im Ruhestand für den Wiedereinstieg motivieren', '{401}', 6081, 1, 3, null, 'Pensionierte Lehrkräfte zurückzugewinnen hilft kurzfristig; erfahrungsgemäß kehren nur wenige zurück, eine dauerhafte Lösung ist es nicht. Für das Land leicht umsetzbar.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=47', null, 'gemischt', '2026-09-29', false, true, null),
  (4204, 4, 11, 'MV', 'Pädagogische Fachkräfte und multiprofessionelle Teams ausbauen; Schulverwaltungsassistenzen', '{401}', 6072, 2, 2, null, 'Verwaltungs- und Unterstützungskräfte nehmen Lehrkräften Aufgaben ab und schaffen Zeit für Unterricht; Studien zu solchen Assistenzkräften zeigen positive, aber unterschiedlich große Effekte. Das Land kann die Stellen schaffen, Finanzierung und Bewerberlage sind die Hürden.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=47', null, 'gemischt', '2026-09-29', false, true, null),
  (4205, 4, 11, 'MV', 'Modellstudiengang „Duales Lehramt“; mehr Praxisphasen ab dem ersten Semester', '{401}', 6073, 2, 2, null, 'Mehr und praxisnähere Lehramtsausbildung setzt am Lehrkräftemangel an, wirkt aber erst nach Jahren; wie viele zusätzliche Lehrkräfte im Land ankommen, ist offen. Das Land kann seine Hochschulen selbst steuern.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=55', null, 'gemischt', '2026-09-29', false, true, null),
  (4206, 4, 11, 'MV', 'Seiten- und Quereinstieg erleichtern, verpflichtende Qualifizierung beibehalten', '{401}', 6075, 2, 3, null, 'Seiten- und Quereinstieg mit Qualifizierung gewinnt kurzfristig zusätzliche Lehrkräfte; wie gut das gelingt, hängt stark von der Nachqualifizierung ab. Das Land ist zuständig und praktiziert das bereits.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=56', null, 'gemischt', '2026-09-29', false, true, null),
  (4207, 4, 11, 'MV', 'Private Smartphone-Nutzung bis Klasse zehn auf dem gesamten Schulgelände untersagen', '{403}', 6083, 1, 3, null, 'Ein Handyverbot kann Ablenkung im Unterricht verringern; Studien zu Wirkungen auf Leistungen sind gemischt. Das Land kann es per Erlass oder Gesetz regeln.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=53', null, 'gemischt', '2026-09-29', false, true, null),
  (4208, 4, 11, 'MV', 'Schulsozialarbeit verstetigen und an sozialen Brennpunkten ausbauen', '{405}', 6078, 1, 3, null, 'Schulsozialarbeit unterstützt Kinder in schwierigen Lagen; Wirkungen auf Leistungen sind kaum belegt. Das Land kann die Finanzierung übernehmen.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=50', null, 'gemischt', '2026-09-29', false, true, null),
  (4209, 4, 11, 'MV', 'Zugang zum Gymnasium nur mit mindestens befriedigenden Leistungen oder Potenzialtest', '{403}', 6082, 1, 3, null, 'Leistungsabhängige Übergänge ins Gymnasium sollen passgenauer fördern; ob die Schulstruktur die Leistungen verbessert, ist in der Forschung nicht entschieden. Das Land kann es im Schulgesetz regeln.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=48', null, 'offen', '2026-09-29', false, true, null),
  (4210, 4, 11, 'MV', 'Zusätzliche Landesmittel für Schulsanierung neben den laufenden Programmen', '{402}', 6085, 1, 2, null, 'Mehr Tempo bei Schulsanierungen setzt am Sanierungsstau an; das Programm nennt aber weder Umfang noch Finanzierung.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=59', null, 'gemischt', '2026-09-29', false, true, null),
  (4211, 4, 12, 'MV', 'Schulbauprogramm (400 Mio. Euro) ausbauen, 600 Mio. Euro aus dem Sondervermögen; bis 2035 möglichst alle Schulen saniert', '{402}', null, 3, 3, null, 'Ein Schulbauprogramm mit benannter Finanzierung setzt direkt am Sanierungsstau an; ob bis 2035 wirklich alle Schulen saniert sind, hängt von Baukapazitäten und Kommunen ab. Die Mittel aus Landesprogramm und Sondervermögen des Bundes sind eingeplant.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=65', null, 'belegt', '2026-09-29', false, true, null),
  (4212, 4, 12, 'MV', 'Landeseigener Sozialindex: Personal und Geld dorthin, wo Schüler mehr Unterstützung brauchen', '{405}', 6071, 2, 2, null, 'Zusätzliche Mittel und Personal für Schulen in schwieriger Lage setzen an der Kopplung von Herkunft und Schulerfolg an; die Evaluation des Startchancen-Programms läuft noch, internationale Erfahrungen sind gemischt. Das Land kann Mittel umverteilen, zusätzliches Personal ist knapp.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=68', null, 'gemischt', '2026-09-29', false, true, null),
  (4213, 4, 12, 'MV', 'Quer- und Seiteneinstieg in Kooperation mit den Hochschulen ausbauen', '{401}', 6075, 2, 3, null, 'Seiten- und Quereinstieg mit Qualifizierung gewinnt kurzfristig zusätzliche Lehrkräfte; wie gut das gelingt, hängt stark von der Nachqualifizierung ab. Das Land ist zuständig und praktiziert das bereits.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=68', null, 'gemischt', '2026-09-29', false, true, null),
  (4214, 4, 12, 'MV', 'Schulleitungen und Pädagogen durch zusätzliches Verwaltungsfachpersonal entlasten', '{401}', 6072, 2, 2, null, 'Verwaltungs- und Unterstützungskräfte nehmen Lehrkräften Aufgaben ab und schaffen Zeit für Unterricht; Studien zu solchen Assistenzkräften zeigen positive, aber unterschiedlich große Effekte. Das Land kann die Stellen schaffen, Finanzierung und Bewerberlage sind die Hürden.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=68', null, 'gemischt', '2026-09-29', false, true, null),
  (4215, 4, 12, 'MV', 'Zusätzliche Stunden für Deutsch und Mathematik und das Leseband fortsetzen und ausbauen', '{403}', 6070, 2, 2, null, 'Mehr Unterrichtszeit für Lesen, Schreiben und Rechnen kann Basiskompetenzen stärken; Studien finden Effekte vor allem bei gezielter, gut angeleiteter Übung. Braucht zusätzliche Lehrkräftestunden, die knapp sind.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=69', null, 'gemischt', '2026-09-29', false, true, null),
  (4216, 4, 12, 'MV', 'Sprachliche Bildung in Kitas stärken, Sprach-Kitas erhalten und ausbauen', '{404}', 6077, 1, 3, null, 'Mehr Sprachförderung in Kitas setzt am Sprachförderbedarf an; ohne verbindliche Feststellung und Förderpflicht erreicht sie nicht sicher alle Kinder mit Bedarf. Das Land ist zuständig.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=65', null, 'gemischt', '2026-09-29', false, true, null),
  (4217, 4, 12, 'MV', 'Schulen in Gebieten mit besonderen Herausforderungen vorrangig zu gebundenen Ganztagsschulen', '{405}', 6080, 1, 2, null, 'Ganztag kann Kinder aus benachteiligten Familien unterstützen, Effekte auf Leistungen hängen laut Studien stark von der Qualität ab. Der Ausbau braucht Personal und Räume.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=69', null, 'gemischt', '2026-09-29', false, true, null),
  (4221, 4, 13, 'MV', 'Multiprofessionelle Teams an allen Schulen, auch mit Assistenz für Verwaltungsarbeiten', '{401}', 6072, 2, 2, null, 'Verwaltungs- und Unterstützungskräfte nehmen Lehrkräften Aufgaben ab und schaffen Zeit für Unterricht; Studien zu solchen Assistenzkräften zeigen positive, aber unterschiedlich große Effekte. Das Land kann die Stellen schaffen, Finanzierung und Bewerberlage sind die Hürden.', 'https://gruene-mv.de/?wpdmdl=33772#page=40', null, 'gemischt', '2026-09-29', false, true, null),
  (4222, 4, 13, 'MV', 'Mehr Lehramtsabsolventen: Studium praxisnäher, bessere Betreuung im Vorbereitungsdienst', '{401}', 6073, 2, 2, null, 'Mehr und praxisnähere Lehramtsausbildung setzt am Lehrkräftemangel an, wirkt aber erst nach Jahren; wie viele zusätzliche Lehrkräfte im Land ankommen, ist offen. Das Land kann seine Hochschulen selbst steuern.', 'https://gruene-mv.de/?wpdmdl=33772#page=42', null, 'gemischt', '2026-09-29', false, true, null),
  (4223, 4, 13, 'MV', 'Stipendienprogramm für Lehramtsstudierende in Mangelfächern', '{401}', 6074, 1, 2, null, 'Zulagen, Stipendien oder Verpflichtungen können Lehrkräfte in unterversorgte Regionen oder Schulen lenken; die Gesamtzahl der Lehrkräfte steigt dadurch kaum. Für das Land finanzierbar, aber mit dauerhaften Kosten.', 'https://gruene-mv.de/?wpdmdl=33772#page=42', null, 'gemischt', '2026-09-29', false, true, null),
  (4224, 4, 13, 'MV', 'Längeres gemeinsames Lernen bis Klasse 6, möglichst an einem Standort', '{405}', 6079, 1, 2, null, 'Längeres gemeinsames Lernen soll den Einfluss der Herkunft verringern; ob die Schulstruktur den Schulerfolg beeinflusst, ist in der Forschung nicht entschieden. Eine Strukturreform braucht Jahre.', 'https://gruene-mv.de/?wpdmdl=33772#page=43', null, 'offen', '2026-09-29', false, true, null),
  (4225, 4, 13, 'MV', 'Land beteiligt sich an den Kosten einer hochwertigen Kita- und Schulverpflegung', '{405}', 6084, 1, 2, null, 'Kostenfreies Essen und Lernmittel entlasten benachteiligte Familien; Studien finden teils positive, meist kleine Effekte auf das Lernen. Dauerhafte Kosten für das Land.', 'https://gruene-mv.de/?wpdmdl=33772#page=44', null, 'gemischt', '2026-09-29', false, true, null),
  (4231, 4, 14, 'MV', 'Lehramtsstudium für alle MINT-Fächer an der Universität Greifswald', '{401}', 6073, 2, 2, null, 'Mehr und praxisnähere Lehramtsausbildung setzt am Lehrkräftemangel an, wirkt aber erst nach Jahren; wie viele zusätzliche Lehrkräfte im Land ankommen, ist offen. Das Land kann seine Hochschulen selbst steuern.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=88', null, 'gemischt', '2026-09-29', false, true, null),
  (4232, 4, 14, 'MV', 'Schulsanierungen nach landesweiter Priorisierung; kommunale Investitionen beschleunigen', '{402}', null, 1, 3, null, 'Eine Priorisierung und schnellere Verfahren setzen das vorhandene Geld gezielter ein; zusätzliches Geld für den Sanierungsstau sieht das Programm nicht vor. Für das Land umsetzbar.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=85', null, 'gemischt', '2026-09-29', false, true, null),
  (4233, 4, 14, 'MV', 'Frühzeitige Sprachförderung für alle Kinder mit Sprachdefiziten, mehr Vorlesen in Kitas', '{404}', 6077, 1, 3, null, 'Mehr Sprachförderung in Kitas setzt am Sprachförderbedarf an; ohne verbindliche Feststellung und Förderpflicht erreicht sie nicht sicher alle Kinder mit Bedarf. Das Land ist zuständig.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=82', null, 'gemischt', '2026-09-29', false, true, null),
  (4234, 4, 14, 'MV', 'Ressourcen auf Brennpunktschulen, Eingangsklassen und Sprachlernphasen konzentrieren', '{405}', 6071, 2, 2, null, 'Zusätzliche Mittel und Personal für Schulen in schwieriger Lage setzen an der Kopplung von Herkunft und Schulerfolg an; die Evaluation des Startchancen-Programms läuft noch, internationale Erfahrungen sind gemischt. Das Land kann Mittel umverteilen, zusätzliches Personal ist knapp.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=97', null, 'gemischt', '2026-09-29', false, true, null),
  (4235, 4, 14, 'MV', 'An jeder Schule eine Kraft für Schulsozialarbeit', '{405}', 6078, 1, 3, null, 'Schulsozialarbeit unterstützt Kinder in schwierigen Lagen; Wirkungen auf Leistungen sind kaum belegt. Das Land kann die Finanzierung übernehmen.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=97', null, 'gemischt', '2026-09-29', false, true, null),
  (4236, 4, 14, 'MV', 'Haupt- und Realschulen wieder einführen statt Regionaler Schule', '{403}', null, 1, 2, null, 'Ein stärker gegliedertes Schulangebot soll passgenauer fördern; ob die Schulstruktur die Leistungen verbessert, ist in der Forschung nicht entschieden. Eine Strukturreform braucht Jahre.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=86', null, 'offen', '2026-09-29', false, true, null),
  (4241, 4, 15, 'MV', 'Rund 400 abgeordnete Lehrerstellen aus Ministerium, Schulämtern und Institut zurück an die Schulen', '{401}', null, 2, 2, null, 'Abgeordnete Lehrkräfte zurück in den Unterricht zu holen, erhöht das Angebot sofort spürbar; ihre bisherigen Aufgaben in Verwaltung und Fortbildung müssten dann andere übernehmen. Für das Land umsetzbar.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=24', null, 'gemischt', '2026-09-29', false, true, null),
  (4242, 4, 15, 'MV', 'Schulverwaltungsassistenten gegen Verwaltungslast', '{401}', 6072, 2, 2, null, 'Verwaltungs- und Unterstützungskräfte nehmen Lehrkräften Aufgaben ab und schaffen Zeit für Unterricht; Studien zu solchen Assistenzkräften zeigen positive, aber unterschiedlich große Effekte. Das Land kann die Stellen schaffen, Finanzierung und Bewerberlage sind die Hürden.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=24', null, 'gemischt', '2026-09-29', false, true, null),
  (4243, 4, 15, 'MV', 'Kurzfristig geeignete Seiteneinsteiger einsetzen', '{401}', 6075, 2, 3, null, 'Seiten- und Quereinstieg mit Qualifizierung gewinnt kurzfristig zusätzliche Lehrkräfte; wie gut das gelingt, hängt stark von der Nachqualifizierung ab. Das Land ist zuständig und praktiziert das bereits.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=25', null, 'gemischt', '2026-09-29', false, true, null),
  (4244, 4, 15, 'MV', 'Pädagogische Hochschule mit vergüteter Ausbildung und Übernahmeperspektive', '{401}', 6073, 2, 2, null, 'Mehr und praxisnähere Lehramtsausbildung setzt am Lehrkräftemangel an, wirkt aber erst nach Jahren; wie viele zusätzliche Lehrkräfte im Land ankommen, ist offen. Das Land kann seine Hochschulen selbst steuern.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=25', null, 'gemischt', '2026-09-29', false, true, null),
  (4245, 4, 15, 'MV', 'Vorschule mit verbindlichem Lehrplan im letzten Kindergartenjahr', '{404}', 6086, 2, 2, null, 'Ein verbindliches Vorschuljahr kann Sprachrückstände vor der Einschulung verringern; ohne Feststellung des Förderbedarfs ist die Förderung weniger gezielt. Braucht Fachkräfte in Kitas oder Grundschulen.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=27', null, 'gemischt', '2026-09-29', false, true, null),
  (4246, 4, 15, 'MV', 'Vorschaltklassen für Kinder ohne ausreichende Deutschkenntnisse', '{404}', 6087, 1, 2, null, 'Getrennte Sprachklassen vor dem Regelunterricht können gezielt Deutsch vermitteln; Studien zu getrenntem und gemeinsamem Unterricht sind gemischt. Braucht zusätzliche Lehrkräfte.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=26', null, 'gemischt', '2026-09-29', false, true, null),
  (4247, 4, 15, 'MV', 'Aufnahme ins Gymnasium bei Noten schlechter als 2,5 nur über einen Eignungstest', '{403}', 6082, 1, 3, null, 'Leistungsabhängige Übergänge ins Gymnasium sollen passgenauer fördern; ob die Schulstruktur die Leistungen verbessert, ist in der Forschung nicht entschieden. Das Land kann es im Schulgesetz regeln.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=27', null, 'offen', '2026-09-29', false, true, null),
  (4248, 4, 15, 'MV', 'Private Handynutzung bis Klasse 7 per Verordnung unterbinden', '{403}', 6083, 1, 3, null, 'Ein Handyverbot kann Ablenkung im Unterricht verringern; Studien zu Wirkungen auf Leistungen sind gemischt. Das Land kann es per Erlass oder Gesetz regeln.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=31', null, 'gemischt', '2026-09-29', false, true, null),
  (4249, 4, 15, 'MV', 'Schulsozialarbeit als Landesaufgabe; mehr Schulpsychologen', '{405}', 6078, 1, 3, null, 'Schulsozialarbeit unterstützt Kinder in schwierigen Lagen; Wirkungen auf Leistungen sind kaum belegt. Das Land kann die Finanzierung übernehmen.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=25', null, 'gemischt', '2026-09-29', false, true, null),
  (4251, 4, 16, 'MV', '500 Alltagshilfen, 100 Verwaltungsfachkräfte, 100 Psychologen und 300 pädagogische Fachkräfte zusätzlich an Schulen', '{401}', 6072, 2, 2, null, 'Verwaltungs- und Unterstützungskräfte nehmen Lehrkräften Aufgaben ab und schaffen Zeit für Unterricht; Studien zu solchen Assistenzkräften zeigen positive, aber unterschiedlich große Effekte. Das Land kann die Stellen schaffen, Finanzierung und Bewerberlage sind die Hürden.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=5', null, 'gemischt', '2026-09-29', false, true, null),
  (4252, 4, 16, 'MV', 'Flächendeckende Sprachstandsfeststellung mit viereinhalb Jahren, zusätzliche Sprachfachkräfte, verbindliches Vorschuljahr', '{404}', 6069, 2, 3, null, 'Eine verbindliche Sprachstandsfeststellung mit anschließender Förderpflicht setzt direkt am Sprachförderbedarf an; Studien zu Sprachförderprogrammen zeigen unterschiedlich starke Effekte. Das Land ist zuständig und kann das per Gesetz regeln.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=5', null, 'gemischt', '2026-09-29', false, true, null),
  (4253, 4, 16, 'MV', 'Schulsozialarbeit an jeder Schule', '{405}', 6078, 1, 3, null, 'Schulsozialarbeit unterstützt Kinder in schwierigen Lagen; Wirkungen auf Leistungen sind kaum belegt. Das Land kann die Finanzierung übernehmen.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=5', null, 'gemischt', '2026-09-29', false, true, null),
  (4254, 4, 16, 'MV', '300-Millionen-Euro-Bildungspaket für Personal und individuelle Förderung', '{403}', null, 1, 2, null, 'Zusätzliches Geld für Personal und individuelle Förderung kann Rückstände verringern; wofür genau es eingesetzt wird, lässt das Programm offen. Die Finanzierung muss das Land im Haushalt sichern.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=5', null, 'gemischt', '2026-09-29', false, true, null),
  (4271, 4, 17, 'MV', 'Verbindliche Sprachstandsfeststellung ab vier Jahren mit gezielter Förderung; verpflichtendes Vorschuljahr', '{404}', 6069, 2, 3, null, 'Eine verbindliche Sprachstandsfeststellung mit anschließender Förderpflicht setzt direkt am Sprachförderbedarf an; Studien zu Sprachförderprogrammen zeigen unterschiedlich starke Effekte. Das Land ist zuständig und kann das per Gesetz regeln.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=46', null, 'gemischt', '2026-09-29', false, true, null),
  (4272, 4, 17, 'MV', 'Praxisnäheres Lehramtsstudium in Richtung duales Studium, Entlastung im Referendariat, Hilfe bei der Wohnungssuche', '{401}', 6073, 2, 2, null, 'Mehr und praxisnähere Lehramtsausbildung setzt am Lehrkräftemangel an, wirkt aber erst nach Jahren; wie viele zusätzliche Lehrkräfte im Land ankommen, ist offen. Das Land kann seine Hochschulen selbst steuern.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=47', null, 'gemischt', '2026-09-29', false, true, null),
  (4273, 4, 17, 'MV', 'Multiprofessionelle Teams mit Sozialarbeit, Schulpsychologie und IT-Support', '{401}', 6072, 2, 2, null, 'Verwaltungs- und Unterstützungskräfte nehmen Lehrkräften Aufgaben ab und schaffen Zeit für Unterricht; Studien zu solchen Assistenzkräften zeigen positive, aber unterschiedlich große Effekte. Das Land kann die Stellen schaffen, Finanzierung und Bewerberlage sind die Hürden.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=46', null, 'gemischt', '2026-09-29', false, true, null),
  (4274, 4, 17, 'MV', 'Handys und Tablets aus den Klassenzimmern der Grundschulen verbannen', '{403}', 6083, 1, 3, null, 'Ein Handyverbot kann Ablenkung im Unterricht verringern; Studien zu Wirkungen auf Leistungen sind gemischt. Das Land kann es per Erlass oder Gesetz regeln.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=47', null, 'gemischt', '2026-09-29', false, true, null),
  (4275, 4, 17, 'MV', 'Kleinere Klassen mit höchstens 24 Schülerinnen und Schülern', '{403}', null, 1, 2, null, 'Kleinere Klassen können das Lernen verbessern; Studien finden eher kleine Effekte, größere vor allem in den ersten Schuljahren. Braucht zusätzliche Lehrkräfte, sinkende Schülerzahlen helfen.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=48', null, 'gemischt', '2026-09-29', false, true, null),
  (4276, 4, 17, 'MV', 'Förderunterricht und Kursangebote für Kinder aus benachteiligten Milieus ausbauen', '{405}', null, 1, 2, null, 'Zusätzlicher Förderunterricht für benachteiligte Kinder kann Rückstände verringern; Studien zu gezielter Förderung in kleinen Gruppen zeigen positive Effekte, das Programm nennt aber keinen Umfang. Braucht zusätzliche Lehrkräftestunden.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=48', null, 'gemischt', '2026-09-29', false, true, null),
  (4277, 4, 17, 'MV', 'Zugang zum Gymnasium über bindende Laufbahnempfehlung oder Aufnahmeprüfung', '{403}', 6082, 1, 3, null, 'Leistungsabhängige Übergänge ins Gymnasium sollen passgenauer fördern; ob die Schulstruktur die Leistungen verbessert, ist in der Forschung nicht entschieden. Das Land kann es im Schulgesetz regeln.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=49', null, 'offen', '2026-09-29', false, true, null),
  (4301, 4, 11, 'BE', 'Schulbauoffensive fortführen; Programm für kleinteilige Sanierungen', '{402}', 6076, 2, 2, null, 'Ein Schulbauprogramm setzt direkt am Sanierungsstau an; wie weit es reicht, hängt von Umfang, Baukapazitäten und Kommunen ab. Das Programm nennt keinen Betrag, die Finanzierung muss das Land im Haushalt sichern.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=59', null, 'belegt', '2026-09-29', false, true, null),
  (4302, 4, 11, 'BE', 'Berufsbegleitende Qualifizierung von Quereinsteigern; Ein-Fach-Lehrkraft, Tandemlehrer, Flex-Master', '{401}', 6075, 2, 3, null, 'Seiten- und Quereinstieg mit Qualifizierung gewinnt kurzfristig zusätzliche Lehrkräfte; wie gut das gelingt, hängt stark von der Nachqualifizierung ab. Das Land ist zuständig und praktiziert das bereits.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=58', null, 'gemischt', '2026-09-29', false, true, null),
  (4303, 4, 11, 'BE', 'Lehrkräfte verbeamten', '{401}', null, 1, 2, null, 'Verbeamtung macht den Lehrerberuf im Wettbewerb der Länder attraktiver; die Gesamtzahl der Lehrkräfte steigt dadurch nicht, und die Pensionslasten sind hoch.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=58', null, 'gemischt', '2026-09-29', false, true, null),
  (4304, 4, 11, 'BE', 'Freiwillige Ferienschulen zum Aufholen von Rückständen in Lesen, Schreiben und Rechnen', '{403}', null, 2, 3, null, 'Ferienschulen können Lernrückstände gezielt aufholen; Studien zu Lernferien finden positive Effekte, freiwillige Angebote erreichen aber nicht alle Kinder mit Bedarf. Das Land kann sie selbst organisieren.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=55', null, 'gemischt', '2026-09-29', false, true, null),
  (4305, 4, 11, 'BE', 'Vorschule (Kita-Chancenjahr) mit Schwerpunkt Sprachförderung', '{404}', 6086, 2, 2, null, 'Ein verbindliches Vorschuljahr kann Sprachrückstände vor der Einschulung verringern; ohne Feststellung des Förderbedarfs ist die Förderung weniger gezielt. Braucht Fachkräfte in Kitas oder Grundschulen.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=56', null, 'gemischt', '2026-09-29', false, true, null),
  (4306, 4, 11, 'BE', 'Landesprogramm Schulsozialarbeit stärken', '{405}', 6078, 1, 3, null, 'Schulsozialarbeit unterstützt Kinder in schwierigen Lagen; Wirkungen auf Leistungen sind kaum belegt. Das Land kann die Finanzierung übernehmen.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=58', null, 'gemischt', '2026-09-29', false, true, null),
  (4311, 4, 12, 'BE', 'Verpflichtende Sprachstandsfeststellungen, gezielte Förderung vor der Einschulung', '{404}', 6069, 2, 3, null, 'Eine verbindliche Sprachstandsfeststellung mit anschließender Förderpflicht setzt direkt am Sprachförderbedarf an; Studien zu Sprachförderprogrammen zeigen unterschiedlich starke Effekte. Das Land ist zuständig und kann das per Gesetz regeln.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=38', null, 'gemischt', '2026-09-29', false, true, null),
  (4312, 4, 12, 'BE', 'Personalzuschlag für Schülerinnen und Schüler nicht deutscher Herkunftssprache wieder einführen', '{405}', 6071, 2, 2, null, 'Zusätzliche Mittel und Personal für Schulen in schwieriger Lage setzen an der Kopplung von Herkunft und Schulerfolg an; die Evaluation des Startchancen-Programms läuft noch, internationale Erfahrungen sind gemischt. Das Land kann Mittel umverteilen, zusätzliches Personal ist knapp.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=37', null, 'gemischt', '2026-09-29', false, true, null),
  (4313, 4, 12, 'BE', 'Schulbauoffensive fortsetzen, Schwerpunkt auf Sanierung der Bestandsgebäude', '{402}', 6076, 2, 2, null, 'Ein Schulbauprogramm setzt direkt am Sanierungsstau an; wie weit es reicht, hängt von Umfang, Baukapazitäten und Kommunen ab. Das Programm nennt keinen Betrag, die Finanzierung muss das Land im Haushalt sichern.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=42', null, 'belegt', '2026-09-29', false, true, null),
  (4314, 4, 12, 'BE', 'Nichtpädagogisches Personal ausbauen: Verwaltungsleitungen, IT-Personal, Hausmeister', '{401}', 6072, 2, 2, null, 'Verwaltungs- und Unterstützungskräfte nehmen Lehrkräften Aufgaben ab und schaffen Zeit für Unterricht; Studien zu solchen Assistenzkräften zeigen positive, aber unterschiedlich große Effekte. Das Land kann die Stellen schaffen, Finanzierung und Bewerberlage sind die Hürden.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=42', null, 'gemischt', '2026-09-29', false, true, null),
  (4315, 4, 12, 'BE', 'Anerkennung von Lehrkräften mit internationalen Qualifikationen erleichtern', '{401}', 6088, 2, 3, null, 'Leichtere Anerkennung ausländischer Lehrkräfte (etwa mit nur einem Fach) erschließt kurzfristig zusätzliche Bewerberinnen und Bewerber; ihre Zahl ist begrenzt, das Sprachniveau bleibt eine Hürde. Das Land ist zuständig.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=42', null, 'gemischt', '2026-09-29', false, true, null),
  (4316, 4, 12, 'BE', 'Handyverbot an allen Grundschulen', '{403}', 6083, 1, 3, null, 'Ein Handyverbot kann Ablenkung im Unterricht verringern; Studien zu Wirkungen auf Leistungen sind gemischt. Das Land kann es per Erlass oder Gesetz regeln.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=41', null, 'gemischt', '2026-09-29', false, true, null),
  (4317, 4, 12, 'BE', 'Zahl der Gemeinschaftsschulen verdoppeln', '{405}', 6079, 1, 2, null, 'Längeres gemeinsames Lernen soll den Einfluss der Herkunft verringern; ob die Schulstruktur den Schulerfolg beeinflusst, ist in der Forschung nicht entschieden. Eine Strukturreform braucht Jahre.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=39', null, 'offen', '2026-09-29', false, true, null),
  (4318, 4, 12, 'BE', 'Landesprogramm Schulstationen; mindestens eine Schulsozialarbeiterstelle je Schule', '{405}', 6078, 1, 3, null, 'Schulsozialarbeit unterstützt Kinder in schwierigen Lagen; Wirkungen auf Leistungen sind kaum belegt. Das Land kann die Finanzierung übernehmen.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=42', null, 'gemischt', '2026-09-29', false, true, null),
  (4319, 4, 12, 'BE', 'Flex-Ganztag an Grundschulen bis Klasse 6 ausbauen', '{405}', 6080, 1, 2, null, 'Ganztag kann Kinder aus benachteiligten Familien unterstützen, Effekte auf Leistungen hängen laut Studien stark von der Qualität ab. Der Ausbau braucht Personal und Räume.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=40', null, 'gemischt', '2026-09-29', false, true, null),
  (4321, 4, 13, 'BE', 'Nach Hamburger Vorbild verbindliche Förderung nach der Sprachstandserhebung bei Vierjährigen', '{404}', 6069, 2, 3, null, 'Eine verbindliche Sprachstandsfeststellung mit anschließender Förderpflicht setzt direkt am Sprachförderbedarf an; Studien zu Sprachförderprogrammen zeigen unterschiedlich starke Effekte. Das Land ist zuständig und kann das per Gesetz regeln.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=183', null, 'gemischt', '2026-09-29', false, true, null),
  (4322, 4, 13, 'BE', 'Lehrkräften mit internationalen Abschlüssen den Zugang erleichtern: Ein-Fach-Lehrkraft, einfachere Anerkennung, kostenlose Deutschkurse', '{401}', 6088, 2, 3, null, 'Leichtere Anerkennung ausländischer Lehrkräfte (etwa mit nur einem Fach) erschließt kurzfristig zusätzliche Bewerberinnen und Bewerber; ihre Zahl ist begrenzt, das Sprachniveau bleibt eine Hürde. Das Land ist zuständig.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=194', null, 'gemischt', '2026-09-29', false, true, null),
  (4323, 4, 13, 'BE', 'Stipendium für Lehramtsstudierende, die fünf Jahre an unterversorgten Schulen arbeiten', '{401}', 6074, 1, 2, null, 'Zulagen, Stipendien oder Verpflichtungen können Lehrkräfte in unterversorgte Regionen oder Schulen lenken; die Gesamtzahl der Lehrkräfte steigt dadurch kaum. Für das Land finanzierbar, aber mit dauerhaften Kosten.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=194', null, 'gemischt', '2026-09-29', false, true, null),
  (4324, 4, 13, 'BE', 'Teams aus verschiedenen Professionen an allen Schulen', '{401}', 6072, 2, 2, null, 'Verwaltungs- und Unterstützungskräfte nehmen Lehrkräften Aufgaben ab und schaffen Zeit für Unterricht; Studien zu solchen Assistenzkräften zeigen positive, aber unterschiedlich große Effekte. Das Land kann die Stellen schaffen, Finanzierung und Bewerberlage sind die Hürden.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=193', null, 'gemischt', '2026-09-29', false, true, null),
  (4325, 4, 13, 'BE', 'Einstellungskontingente und Mindestausstattung mit qualifizierten Lehrkräften für Schulen in herausfordernden Lagen', '{405}', 6071, 2, 2, null, 'Zusätzliche Mittel und Personal für Schulen in schwieriger Lage setzen an der Kopplung von Herkunft und Schulerfolg an; die Evaluation des Startchancen-Programms läuft noch, internationale Erfahrungen sind gemischt. Das Land kann Mittel umverteilen, zusätzliches Personal ist knapp.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=194', null, 'gemischt', '2026-09-29', false, true, null),
  (4326, 4, 13, 'BE', 'Sanierung alter Schulgebäude vorantreiben', '{402}', 6085, 1, 2, null, 'Mehr Tempo bei Schulsanierungen setzt am Sanierungsstau an; das Programm nennt aber weder Umfang noch Finanzierung.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=192', null, 'gemischt', '2026-09-29', false, true, null),
  (4327, 4, 13, 'BE', 'Zahl der Gemeinschaftsschulen verdoppeln', '{405}', 6079, 1, 2, null, 'Längeres gemeinsames Lernen soll den Einfluss der Herkunft verringern; ob die Schulstruktur den Schulerfolg beeinflusst, ist in der Forschung nicht entschieden. Eine Strukturreform braucht Jahre.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=187', null, 'offen', '2026-09-29', false, true, null),
  (4328, 4, 13, 'BE', 'Mehr Schulsozialarbeiterinnen und Schulsozialarbeiter', '{405}', 6078, 1, 3, null, 'Schulsozialarbeit unterstützt Kinder in schwierigen Lagen; Wirkungen auf Leistungen sind kaum belegt. Das Land kann die Finanzierung übernehmen.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=189', null, 'gemischt', '2026-09-29', false, true, null),
  (4331, 4, 14, 'BE', 'Schulpflichtiges Vorschuljahr in der Kita; verbindliche Sprachstandstests mit drei bis vier Jahren', '{404}', 6069, 2, 3, null, 'Eine verbindliche Sprachstandsfeststellung mit anschließender Förderpflicht setzt direkt am Sprachförderbedarf an; Studien zu Sprachförderprogrammen zeigen unterschiedlich starke Effekte. Das Land ist zuständig und kann das per Gesetz regeln.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=6', null, 'gemischt', '2026-09-29', false, true, null),
  (4332, 4, 14, 'BE', 'Personal für die Schulverwaltung verbessern, um Lehrkräfte zu entlasten', '{401}', 6072, 2, 2, null, 'Verwaltungs- und Unterstützungskräfte nehmen Lehrkräften Aufgaben ab und schaffen Zeit für Unterricht; Studien zu solchen Assistenzkräften zeigen positive, aber unterschiedlich große Effekte. Das Land kann die Stellen schaffen, Finanzierung und Bewerberlage sind die Hürden.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=8', null, 'gemischt', '2026-09-29', false, true, null),
  (4333, 4, 14, 'BE', 'Fester Schultag im Lehramtsstudium; langfristig alle Lehramtsstudiengänge dual', '{401}', 6073, 2, 2, null, 'Mehr und praxisnähere Lehramtsausbildung setzt am Lehrkräftemangel an, wirkt aber erst nach Jahren; wie viele zusätzliche Lehrkräfte im Land ankommen, ist offen. Das Land kann seine Hochschulen selbst steuern.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=10', null, 'gemischt', '2026-09-29', false, true, null),
  (4334, 4, 14, 'BE', 'Anreize wie Aufstiegsmöglichkeiten für ausgebildete Lehrkräfte an Brennpunktschulen', '{405}', null, 1, 3, null, 'Anreize für voll ausgebildete Lehrkräfte an Brennpunktschulen setzen an der ungleichen Verteilung an; wie viele Lehrkräfte sich dadurch umentscheiden, ist offen. Für das Land umsetzbar.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=10', null, 'gemischt', '2026-09-29', false, true, null),
  (4341, 4, 15, 'BE', 'Pflicht zur Sprachstandsfeststellung und Sprachförderung im Kita-Alter konsequenter umsetzen', '{404}', 6069, 2, 3, null, 'Eine verbindliche Sprachstandsfeststellung mit anschließender Förderpflicht setzt direkt am Sprachförderbedarf an; Studien zu Sprachförderprogrammen zeigen unterschiedlich starke Effekte. Das Land ist zuständig und kann das per Gesetz regeln.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=28', null, 'gemischt', '2026-09-29', false, true, null),
  (4342, 4, 15, 'BE', 'Spezialklassen für Kinder mit Sprachförderbedarf („Deutsch-Garantie-Klassen“) ausweiten', '{404}', 6087, 1, 2, null, 'Getrennte Sprachklassen vor dem Regelunterricht können gezielt Deutsch vermitteln; Studien zu getrenntem und gemeinsamem Unterricht sind gemischt. Braucht zusätzliche Lehrkräfte.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=29', null, 'gemischt', '2026-09-29', false, true, null),
  (4343, 4, 15, 'BE', 'Keine weitere Verschiebung geplanter Schulsanierungen und Schulneubauten', '{402}', 6085, 1, 2, null, 'Mehr Tempo bei Schulsanierungen setzt am Sanierungsstau an; das Programm nennt aber weder Umfang noch Finanzierung.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=29', null, 'gemischt', '2026-09-29', false, true, null),
  (4344, 4, 15, 'BE', 'Grundschule bildschirmfrei, Smartphone-Verbot', '{403}', 6083, 1, 3, null, 'Ein Handyverbot kann Ablenkung im Unterricht verringern; Studien zu Wirkungen auf Leistungen sind gemischt. Das Land kann es per Erlass oder Gesetz regeln.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=30', null, 'gemischt', '2026-09-29', false, true, null),
  (4345, 4, 15, 'BE', 'Stipendien für Lehramtsstudienanfänger in Mangelfächern mit Verpflichtung für Berlin', '{401}', 6074, 1, 2, null, 'Zulagen, Stipendien oder Verpflichtungen können Lehrkräfte in unterversorgte Regionen oder Schulen lenken; die Gesamtzahl der Lehrkräfte steigt dadurch kaum. Für das Land finanzierbar, aber mit dauerhaften Kosten.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=38', null, 'gemischt', '2026-09-29', false, true, null),
  (4346, 4, 15, 'BE', 'Einphasige Lehrerausbildung als duales Studium', '{401}', 6073, 2, 2, null, 'Mehr und praxisnähere Lehramtsausbildung setzt am Lehrkräftemangel an, wirkt aber erst nach Jahren; wie viele zusätzliche Lehrkräfte im Land ankommen, ist offen. Das Land kann seine Hochschulen selbst steuern.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=39', null, 'gemischt', '2026-09-29', false, true, null),
  (4347, 4, 15, 'BE', 'Vollständige Lernmittelfreiheit, kostenloses Schulmittagessen beibehalten', '{405}', 6084, 1, 2, null, 'Kostenfreies Essen und Lernmittel entlasten benachteiligte Familien; Studien finden teils positive, meist kleine Effekte auf das Lernen. Dauerhafte Kosten für das Land.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=29', null, 'gemischt', '2026-09-29', false, true, null),
  (4351, 4, 16, 'BE', 'Zusätzliche Mittel für die Lehrkräftebildung, Ziel 3.000 Absolventen im Jahr; Kapazitäten gesetzlich am Bedarf ausrichten', '{401}', 6073, 2, 2, null, 'Mehr und praxisnähere Lehramtsausbildung setzt am Lehrkräftemangel an, wirkt aber erst nach Jahren; wie viele zusätzliche Lehrkräfte im Land ankommen, ist offen. Das Land kann seine Hochschulen selbst steuern.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=225', null, 'gemischt', '2026-09-29', false, true, null),
  (4352, 4, 16, 'BE', 'Quereinstieg öffnen, auch mit nur einem Fach', '{401}', 6075, 2, 3, null, 'Seiten- und Quereinstieg mit Qualifizierung gewinnt kurzfristig zusätzliche Lehrkräfte; wie gut das gelingt, hängt stark von der Nachqualifizierung ab. Das Land ist zuständig und praktiziert das bereits.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=228', null, 'gemischt', '2026-09-29', false, true, null),
  (4353, 4, 16, 'BE', 'Ausländische Lehramtsabschlüsse leichter anerkennen, Einstellung mit einem Fach, Sprachanforderung C1', '{401}', 6088, 2, 3, null, 'Leichtere Anerkennung ausländischer Lehrkräfte (etwa mit nur einem Fach) erschließt kurzfristig zusätzliche Bewerberinnen und Bewerber; ihre Zahl ist begrenzt, das Sprachniveau bleibt eine Hürde. Das Land ist zuständig.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=155', null, 'gemischt', '2026-09-29', false, true, null),
  (4354, 4, 16, 'BE', 'Je Schule eine volle Stelle für Verwaltungsleitung und IT-Administration; mehr Unterrichtshilfen und Schulassistenz', '{401}', 6072, 2, 2, null, 'Verwaltungs- und Unterstützungskräfte nehmen Lehrkräften Aufgaben ab und schaffen Zeit für Unterricht; Studien zu solchen Assistenzkräften zeigen positive, aber unterschiedlich große Effekte. Das Land kann die Stellen schaffen, Finanzierung und Bewerberlage sind die Hürden.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=155', null, 'gemischt', '2026-09-29', false, true, null),
  (4355, 4, 16, 'BE', 'Schulbauoffensive fortsetzen und beschleunigen', '{402}', 6076, 2, 2, null, 'Ein Schulbauprogramm setzt direkt am Sanierungsstau an; wie weit es reicht, hängt von Umfang, Baukapazitäten und Kommunen ab. Das Programm nennt keinen Betrag, die Finanzierung muss das Land im Haushalt sichern.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=169', null, 'belegt', '2026-09-29', false, true, null),
  (4356, 4, 16, 'BE', 'Handyfreier Schultag bis Klasse 9 als Grundsatz', '{403}', 6083, 1, 3, null, 'Ein Handyverbot kann Ablenkung im Unterricht verringern; Studien zu Wirkungen auf Leistungen sind gemischt. Das Land kann es per Erlass oder Gesetz regeln.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=167', null, 'gemischt', '2026-09-29', false, true, null),
  (4357, 4, 16, 'BE', 'Allen Kindern mindestens 24 Monate Kita vor der Einschulung ermöglichen', '{404}', null, 1, 2, null, 'Ein längerer Kitabesuch verbessert nachweislich die Sprachkenntnisse bei der Einschulung; ohne Pflicht und gezielte Förderung erreicht er aber nicht sicher alle Kinder mit Bedarf. Braucht zusätzliche Kitaplätze und Fachkräfte.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=188', null, 'gemischt', '2026-09-29', false, true, null),
  (4358, 4, 16, 'BE', 'Ergänzungsbudget für Schulen in schwieriger Lage fortsetzen, Startchancen-Mittel zielgenau einsetzen', '{405}', 6071, 2, 2, null, 'Zusätzliche Mittel und Personal für Schulen in schwieriger Lage setzen an der Kopplung von Herkunft und Schulerfolg an; die Evaluation des Startchancen-Programms läuft noch, internationale Erfahrungen sind gemischt. Das Land kann Mittel umverteilen, zusätzliches Personal ist knapp.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=157', null, 'gemischt', '2026-09-29', false, true, null),
  (4359, 4, 16, 'BE', 'Gemeinschaftsschulen deutlich ausbauen, mindestens zwei neue je Bezirk bis 2031', '{405}', 6079, 1, 2, null, 'Längeres gemeinsames Lernen soll den Einfluss der Herkunft verringern; ob die Schulstruktur den Schulerfolg beeinflusst, ist in der Forschung nicht entschieden. Eine Strukturreform braucht Jahre.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=153', null, 'offen', '2026-09-29', false, true, null),
  (4360, 4, 16, 'BE', 'Lernmittelfreiheit und kostenloses Mittagessen auf Mittel- und Oberstufe ausweiten', '{405}', 6084, 1, 2, null, 'Kostenfreies Essen und Lernmittel entlasten benachteiligte Familien; Studien finden teils positive, meist kleine Effekte auf das Lernen. Dauerhafte Kosten für das Land.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=153', null, 'gemischt', '2026-09-29', false, true, null),
  (4361, 4, 17, 'BE', 'Verbindliche Vorschulphase mit Sprachbildung', '{404}', 6086, 2, 2, null, 'Ein verbindliches Vorschuljahr kann Sprachrückstände vor der Einschulung verringern; ohne Feststellung des Förderbedarfs ist die Förderung weniger gezielt. Braucht Fachkräfte in Kitas oder Grundschulen.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=14', null, 'gemischt', '2026-09-29', false, true, null),
  (4362, 4, 17, 'BE', 'Mehrjähriges Förderprogramm für Schulen in Brennpunktlagen mit Mitteln und voll ausgebildetem Personal', '{405}', 6071, 2, 2, null, 'Zusätzliche Mittel und Personal für Schulen in schwieriger Lage setzen an der Kopplung von Herkunft und Schulerfolg an; die Evaluation des Startchancen-Programms läuft noch, internationale Erfahrungen sind gemischt. Das Land kann Mittel umverteilen, zusätzliches Personal ist knapp.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=14', null, 'gemischt', '2026-09-29', false, true, null),
  (4363, 4, 17, 'BE', 'Breites Angebot an Gemeinschaftsschulen', '{405}', 6079, 1, 2, null, 'Längeres gemeinsames Lernen soll den Einfluss der Herkunft verringern; ob die Schulstruktur den Schulerfolg beeinflusst, ist in der Forschung nicht entschieden. Eine Strukturreform braucht Jahre.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=15', null, 'offen', '2026-09-29', false, true, null),
  (4364, 4, 17, 'BE', 'Multiprofessionelle Teams mit Fachkräften für IT und Verwaltung', '{401}', 6072, 2, 2, null, 'Verwaltungs- und Unterstützungskräfte nehmen Lehrkräften Aufgaben ab und schaffen Zeit für Unterricht; Studien zu solchen Assistenzkräften zeigen positive, aber unterschiedlich große Effekte. Das Land kann die Stellen schaffen, Finanzierung und Bewerberlage sind die Hürden.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=16', null, 'gemischt', '2026-09-29', false, true, null),
  (4365, 4, 17, 'BE', 'Smartphones im Unterricht grundsätzlich nicht nutzen und wegschließen', '{403}', 6083, 1, 3, null, 'Ein Handyverbot kann Ablenkung im Unterricht verringern; Studien zu Wirkungen auf Leistungen sind gemischt. Das Land kann es per Erlass oder Gesetz regeln.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=16', null, 'gemischt', '2026-09-29', false, true, null),
  (4366, 4, 17, 'BE', 'Sanierungen in klaren Fristen, Hausmeisterwesen für die Wartung', '{402}', 6085, 1, 2, null, 'Mehr Tempo bei Schulsanierungen setzt am Sanierungsstau an; das Programm nennt aber weder Umfang noch Finanzierung.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=17', null, 'gemischt', '2026-09-29', false, true, null),
  (5001, 5, 11, null, 'Stromsteuer für alle senken und Netzentgelte reduzieren', '{501}', 6089, 2, 2, null, 'Niedrigere Stromsteuer und Netzentgelte senken direkt die Energiekosten, die der Sachverständigenrat als Grund der Industrieschwäche nennt; allein gleichen sie den Kostenabstand aber nicht aus. Die Gegenfinanzierung ist offen.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=22', null, 'belegt', '2026-09-29', false, true, null),
  (5002, 5, 11, null, 'Unternehmensbesteuerung schrittweise auf höchstens 25 Prozent auf einbehaltene Gewinne senken', '{501}', 6090, 1, 2, null, 'Niedrigere Unternehmenssteuern können Investitionen anregen, setzen aber nicht an den vom Sachverständigenrat genannten Gründen (Energiepreise, Lohnstückkosten) an; Studien zur Wirkung sind gemischt. Die Gegenfinanzierung ist offen.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=16', null, 'gemischt', '2026-09-29', false, true, null),
  (5003, 5, 11, null, 'Menschen in Helfertätigkeiten auf dem Weg zur Fachkraft fördern; Anreize für berufliche Qualifikation', '{502}', null, 1, 2, null, 'Qualifizierung von Geringqualifizierten verbessert ihre Chancen im Strukturwandel; das Programm nennt aber kein konkretes Instrument. Umsetzbar über die Arbeitsförderung.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=15', null, 'gemischt', '2026-09-29', false, true, null),
  (5004, 5, 11, null, 'Jährliche Gesetze zum Bürokratieabbau, Bürokratiebremse „One in, two out“, Lieferkettengesetz abschaffen', '{505}', 6091, 2, 2, null, 'Systematischer Abbau von Pflichten setzt an den Bürokratiekosten an; bisherige Programme haben die Kosten laut Normenkontrollrat nur langsam gesenkt. Umsetzbar im nationalen Recht.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=17', null, 'gemischt', '2026-09-29', false, true, null),
  (5005, 5, 11, null, 'Hinzuverdienstgrenzen und Transferentzugsraten reformieren, damit sich Arbeit mehr lohnt', '{506}', 6092, 2, 2, null, 'Geringere Anrechnung von Hinzuverdienst setzt direkt an der Ursache an; das ifo/ZEW-Gutachten für das Arbeitsministerium erwartet mehr Beschäftigung. Die Reform ist Bundesrecht, Kosten und Ausgestaltung sind offen.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=31', null, 'belegt', '2026-09-29', false, true, null),
  (5011, 5, 12, null, 'Übertragungsnetzentgelte auf 3 Cent pro Kilowattstunde deckeln; abgesenkte Stromsteuer entfristen', '{501}', 6089, 2, 2, null, 'Niedrigere Stromsteuer und Netzentgelte senken direkt die Energiekosten, die der Sachverständigenrat als Grund der Industrieschwäche nennt; allein gleichen sie den Kostenabstand aber nicht aus. Die Gegenfinanzierung ist offen.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=7', null, 'belegt', '2026-09-29', false, true, null),
  (5012, 5, 12, null, '„Made in Germany“-Investitionsprämie für bestehende Unternehmen und Neuansiedlungen', '{501}', 6093, 1, 2, null, 'Eine Investitionsprämie kann Investitionen vorziehen, setzt aber nicht an den vom Sachverständigenrat genannten Gründen an; Studien finden teils Mitnahmeeffekte. Umsetzbar per Bundesgesetz, Finanzierung offen.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=8', null, 'gemischt', '2026-09-29', false, true, null),
  (5013, 5, 12, null, 'Echte Mitbestimmung der Betriebsräte bei Personalplanung und betrieblicher Weiterbildung', '{502}', null, 1, 3, null, 'Mehr Mitsprache bei Weiterbildung kann Qualifizierung im Betrieb voranbringen, schafft aber selbst keine Weiterbildungsangebote. Per Bundesgesetz umsetzbar.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=13', null, 'gemischt', '2026-09-29', false, true, null),
  (5014, 5, 12, null, 'Mindestlohn spätestens ab 2026 auf 15 Euro; Tarifbindung besonders in Ostdeutschland stärken', '{503}', 6094, 2, 3, null, 'Ein höherer Mindestlohn hebt die unteren Löhne, von denen im Osten mehr Menschen betroffen sind; Studien zur Erhöhung auf 12 Euro fanden kaum Beschäftigungsverluste. Den Abstand oberhalb des Mindestlohns schließt er nicht. Per Bundesgesetz umsetzbar.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=23', null, 'belegt', '2026-09-29', false, true, null),
  (5015, 5, 12, null, 'Deutschlandfonds mit anfangs 100 Milliarden Euro für öffentliche und private Investitionen, im Rahmen der Schuldenregel', '{504}', null, 2, 2, null, 'Ein Investitionsfonds setzt an der Investitionslücke an; wie viel privates Kapital er tatsächlich mobilisiert, ist offen. Über finanzielle Transaktionen ohne Grundgesetzänderung umsetzbar.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=8', null, 'gemischt', '2026-09-29', false, true, null),
  (5016, 5, 12, null, 'Dokumentations- und Berichtspflichten zusammenführen, vereinfachen und digitalisieren; Praxischeck für neue Gesetze', '{505}', 6091, 2, 2, null, 'Systematischer Abbau von Pflichten setzt an den Bürokratiekosten an; bisherige Programme haben die Kosten laut Normenkontrollrat nur langsam gesenkt. Umsetzbar im nationalen Recht.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=9', null, 'gemischt', '2026-09-29', false, true, null),
  (5017, 5, 12, null, 'Bundestariftreuegesetz; Allgemeinverbindlicherklärung erleichtern; Verbandsklagerecht für Gewerkschaften', '{507}', 6095, 2, 3, null, 'Eine erleichterte Allgemeinverbindlicherklärung kann die Tarifbindung ganzer Branchen erhöhen, Tariftreue wirkt nur bei öffentlichen Aufträgen; die Wirkung auf die Tarifquote ist in Studien begrenzt belegt. Per Bundesgesetz umsetzbar.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=23', null, 'gemischt', '2026-09-29', false, true, null),
  (5021, 5, 13, null, 'Netzentgelte für überregionale Stromleitungen aus dem Deutschlandfonds zahlen; Stromsteuer auf EU-Minimum senken', '{501}', 6089, 2, 2, null, 'Niedrigere Stromsteuer und Netzentgelte senken direkt die Energiekosten, die der Sachverständigenrat als Grund der Industrieschwäche nennt; allein gleichen sie den Kostenabstand aber nicht aus. Die Gegenfinanzierung ist offen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=17', null, 'belegt', '2026-09-29', false, true, null),
  (5022, 5, 13, null, 'Befristete Investitionsprämie von 10 Prozent für alle Unternehmen', '{501}', 6093, 1, 2, null, 'Eine Investitionsprämie kann Investitionen vorziehen, setzt aber nicht an den vom Sachverständigenrat genannten Gründen an; Studien finden teils Mitnahmeeffekte. Umsetzbar per Bundesgesetz, Finanzierung offen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=18', null, 'gemischt', '2026-09-29', false, true, null),
  (5023, 5, 13, null, 'Qualifizierungsgeld weiterentwickeln; selbst gewählte berufliche Weiterbildung sozial absichern', '{502}', 6096, 2, 2, null, 'Geförderte Weiterbildung hilft Beschäftigten beim Wechsel in neue Branchen; Studien zeigen positive, aber je nach Maßnahme sehr unterschiedliche Effekte. Umsetzbar über die Arbeitsförderung, Finanzierung offen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=19', null, 'gemischt', '2026-09-29', false, true, null),
  (5024, 5, 13, null, 'Mindestlohn schrittweise erhöhen, zunächst 15 Euro, auch für unter 18-Jährige', '{503}', 6094, 2, 3, null, 'Ein höherer Mindestlohn hebt die unteren Löhne, von denen im Osten mehr Menschen betroffen sind; Studien zur Erhöhung auf 12 Euro fanden kaum Beschäftigungsverluste. Den Abstand oberhalb des Mindestlohns schließt er nicht. Per Bundesgesetz umsetzbar.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=67', null, 'belegt', '2026-09-29', false, true, null),
  (5025, 5, 13, null, 'Deutschlandfonds für Investitionen von Bund, Ländern und Kommunen; Reform der Schuldenbremse', '{504}', null, 2, 2, null, 'Ein Investitionsfonds setzt an der Investitionslücke an; Umfang und Mobilisierung privaten Kapitals sind offen. Der Fonds ist ohne Grundgesetzänderung möglich, die Reform der Schuldenbremse nicht.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=10', null, 'gemischt', '2026-09-29', false, true, null),
  (5026, 5, 13, null, 'Praxischeck ausweiten; Verwaltungsleistungen für Unternehmen bündeln, Daten nur einmal einreichen (Once-Only)', '{505}', 6091, 2, 2, null, 'Systematischer Abbau von Pflichten setzt an den Bürokratiekosten an; bisherige Programme haben die Kosten laut Normenkontrollrat nur langsam gesenkt. Umsetzbar im nationalen Recht.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=18', null, 'gemischt', '2026-09-29', false, true, null),
  (5027, 5, 13, null, 'Steuergutschriften für niedrige Einkommen, auch für Menschen, die mit Bürgergeld aufstocken', '{506}', null, 1, 2, null, 'Steuergutschriften auf Arbeitseinkommen können Arbeit lohnender machen; wie sie mit der Anrechnung im Bürgergeld zusammenspielen, lässt das Programm offen. Umsetzbar per Bundesgesetz, Finanzierung offen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=74', null, 'gemischt', '2026-09-29', false, true, null),
  (5028, 5, 13, null, 'Allgemeinverbindlicherklärung von Tarifverträgen erleichtern', '{507}', 6095, 2, 3, null, 'Eine erleichterte Allgemeinverbindlicherklärung kann die Tarifbindung ganzer Branchen erhöhen, Tariftreue wirkt nur bei öffentlichen Aufträgen; die Wirkung auf die Tarifquote ist in Studien begrenzt belegt. Per Bundesgesetz umsetzbar.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=67', null, 'gemischt', '2026-09-29', false, true, null),
  (5031, 5, 14, null, 'Stromsteuer auf EU-Mindestmaß senken; Netzentgelte umfassend reformieren', '{501}', 6089, 2, 2, null, 'Niedrigere Stromsteuer und Netzentgelte senken direkt die Energiekosten, die der Sachverständigenrat als Grund der Industrieschwäche nennt; allein gleichen sie den Kostenabstand aber nicht aus. Die Gegenfinanzierung ist offen.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=17', null, 'belegt', '2026-09-29', false, true, null),
  (5032, 5, 14, null, 'Unternehmenssteuerbelastung unter 25 Prozent: Solidaritätszuschlag abschaffen, Körperschaftsteuer senken', '{501}', 6090, 1, 2, null, 'Niedrigere Unternehmenssteuern können Investitionen anregen, setzen aber nicht an den vom Sachverständigenrat genannten Gründen (Energiepreise, Lohnstückkosten) an; Studien zur Wirkung sind gemischt. Die Gegenfinanzierung ist offen.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=15', null, 'gemischt', '2026-09-29', false, true, null),
  (5033, 5, 14, null, '„Lebenschancen-BAföG“ für Kursgebühren und bildungsbedingte Auszeiten; Freiraumkonto für Weiterbildung', '{502}', 6096, 2, 2, null, 'Geförderte Weiterbildung hilft Beschäftigten beim Wechsel in neue Branchen; Studien zeigen positive, aber je nach Maßnahme sehr unterschiedliche Effekte. Umsetzbar über die Arbeitsförderung, Finanzierung offen.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=10', null, 'gemischt', '2026-09-29', false, true, null),
  (5034, 5, 14, null, 'Steuersenkungen, Bürokratieabbau, Reallabore und Wirtschaftsförderung für kleine und mittlere Unternehmen in Ostdeutschland', '{503}', null, 1, 2, null, 'Stärkere Unternehmen im Osten können langfristig höhere Löhne ermöglichen; ob allgemeine Entlastungen die Lohnlücke verringern, ist offen. Umsetzbar, Finanzierung offen.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=12', null, 'gemischt', '2026-09-29', false, true, null),
  (5035, 5, 14, null, 'Infrastruktur im Rahmen der Schuldenbremse finanzieren, etwa über einen Finanzierungskreislauf Straße', '{504}', null, 1, 2, null, 'Das Programm erkennt den Investitionsbedarf an, nennt aber weder Umfang noch ein Instrument jenseits der Straße. Im Rahmen der Schuldenbremse umsetzbar.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=42', null, 'gemischt', '2026-09-29', false, true, null),
  (5036, 5, 14, null, 'Dreijähriges Bürokratie-Moratorium; ein bürokratiefreies Jahr ohne Berichtspflichten für Betriebe', '{505}', 6091, 2, 2, null, 'Systematischer Abbau von Pflichten setzt an den Bürokratiekosten an; bisherige Programme haben die Kosten laut Normenkontrollrat nur langsam gesenkt. Umsetzbar im nationalen Recht.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=12', null, 'gemischt', '2026-09-29', false, true, null),
  (5037, 5, 14, null, 'Hinzuverdienstregeln in Grundsicherung und Wohngeld so reformieren, dass sich Arbeit spürbar mehr lohnt', '{506}', 6092, 2, 2, null, 'Geringere Anrechnung von Hinzuverdienst setzt direkt an der Ursache an; das ifo/ZEW-Gutachten für das Arbeitsministerium erwartet mehr Beschäftigung. Die Reform ist Bundesrecht, Kosten und Ausgestaltung sind offen.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=20', null, 'belegt', '2026-09-29', false, true, null),
  (5041, 5, 15, null, 'CO₂-Abgabe abschaffen, Energiesteuer reduzieren, Stromsteuer auf das Minimum senken', '{501}', null, 2, 2, null, 'Niedrigere Steuern und Abgaben senken die Energiekosten; die Industrie zahlt ihren CO₂-Preis aber vor allem im EU-Emissionshandel, den Deutschland nicht allein abschaffen kann. Die Gegenfinanzierung ist offen.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=14', null, 'gemischt', '2026-09-29', false, true, null),
  (5042, 5, 15, null, 'Kohlekraftwerke länger laufen lassen, Wiedereinstieg in die Kernenergie, Nord-Stream-Pipelines reparieren und nutzen', '{501}', null, 2, 1, null, 'Mehr Angebot und günstigeres Gas könnten Energiekosten senken; neue Kernkraftwerke wirken erst nach vielen Jahren. EU-Sanktionen, die EU-Regeln zum Ausstieg aus russischem Gas und lange Bauzeiten stehen entgegen.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=14', null, 'gemischt', '2026-09-29', false, true, null),
  (5043, 5, 15, null, 'Unternehmenssteuern auf ein international konkurrenzfähiges Niveau senken', '{501}', 6090, 1, 2, null, 'Niedrigere Unternehmenssteuern können Investitionen anregen, setzen aber nicht an den vom Sachverständigenrat genannten Gründen (Energiepreise, Lohnstückkosten) an; Studien zur Wirkung sind gemischt. Die Gegenfinanzierung ist offen.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=15', null, 'gemischt', '2026-09-29', false, true, null),
  (5044, 5, 15, null, 'Intensive Beratung, Weiterbildung und Vermittlung schon während des Arbeitslosengeldbezugs', '{502}', null, 1, 2, null, 'Frühe Beratung und Weiterbildung verbessern die Chancen nach einem Stellenverlust; das Programm nennt aber kein neues Instrument. Umsetzbar über die Arbeitsförderung.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=22', null, 'gemischt', '2026-09-29', false, true, null),
  (5045, 5, 15, null, 'Straßen, Schienen und Brücken planvoll sanieren; Planungs- und Genehmigungsverfahren vereinfachen', '{504}', null, 1, 2, null, 'Schnellere Verfahren und Sanierung setzen an der Investitionslücke an; das Programm nennt aber keinen Umfang und keine Finanzierung. Umsetzbar per Bundesgesetz.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=15', null, 'gemischt', '2026-09-29', false, true, null),
  (5046, 5, 15, null, 'Lieferkettengesetz, EU-Lieferkettenrichtlinie und Verpackungsgesetz abschaffen, Nachhaltigkeitsberichte abbauen, Pflichten drastisch reduzieren', '{505}', 6097, 2, 1, null, 'Wegfall von Berichtspflichten setzt an den Bürokratiekosten an; bisherige Programme haben die Kosten laut Normenkontrollrat nur langsam gesenkt. Ein Teil der genannten Pflichten beruht auf EU-Recht, das Deutschland nicht allein ändern kann.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=14', null, 'gemischt', '2026-09-29', false, true, null),
  (5047, 5, 15, null, 'Bürgergeldempfänger nach sechs Monaten zu gemeinnütziger Arbeit heranziehen („Aktivierende Grundsicherung“)', '{506}', null, 1, 2, null, 'Arbeitspflichten erhöhen den Druck, machen zusätzliche Arbeit aber nicht lohnender; Studien zu Arbeitsgelegenheiten finden kaum Effekte auf reguläre Beschäftigung. Umsetzbar per Bundesgesetz.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=26', null, 'gemischt', '2026-09-29', false, true, null),
  (5051, 5, 16, null, 'Neue Netzentgeltstruktur; Stromsteuer auf europäischen Mindeststeuersatz senken', '{501}', 6089, 2, 2, null, 'Niedrigere Stromsteuer und Netzentgelte senken direkt die Energiekosten, die der Sachverständigenrat als Grund der Industrieschwäche nennt; allein gleichen sie den Kostenabstand aber nicht aus. Die Gegenfinanzierung ist offen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=32', null, 'belegt', '2026-09-29', false, true, null),
  (5052, 5, 16, null, 'Industriestrompreis für energieintensive Betriebe aus einem auf 65 Milliarden Euro jährlich ausgebauten Klima- und Transformationsfonds', '{501}', null, 2, 2, null, 'Ein Industriestrompreis senkt die Energiekosten energieintensiver Betriebe direkt; Ökonominnen und Ökonomen streiten über Kosten und Fehlanreize. Braucht eine beihilferechtliche Genehmigung der EU.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=30', null, 'gemischt', '2026-09-29', false, true, null),
  (5053, 5, 16, null, 'Weiterqualifizierungsgeld von 90 Prozent des letzten Gehalts beim Wechsel von Beruf oder Branche', '{502}', 6096, 2, 2, null, 'Geförderte Weiterbildung hilft Beschäftigten beim Wechsel in neue Branchen; Studien zeigen positive, aber je nach Maßnahme sehr unterschiedliche Effekte. Umsetzbar über die Arbeitsförderung, Finanzierung offen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=31', null, 'gemischt', '2026-09-29', false, true, null),
  (5054, 5, 16, null, 'Mindestlohn auf mindestens 15 Euro, spätestens 2026 auf 16 Euro; Tarifbindung stärken – gleicher Lohn in Ost und West', '{503}', 6094, 2, 3, null, 'Ein höherer Mindestlohn hebt die unteren Löhne, von denen im Osten mehr Menschen betroffen sind; Studien zur Erhöhung auf 12 Euro fanden kaum Beschäftigungsverluste. Den Abstand oberhalb des Mindestlohns schließt er nicht. Per Bundesgesetz umsetzbar.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=45', null, 'belegt', '2026-09-29', false, true, null),
  (5055, 5, 16, null, 'Schuldenbremse abschaffen, um in Bildung, Brücken, Bus und Bahn und die Wirtschaft zu investieren', '{504}', 6098, 2, 1, null, 'Mehr Spielraum für öffentliche Investitionen setzt direkt an der Investitionslücke an. Eine Änderung der Schuldenbremse erfordert eine Grundgesetzänderung mit Zweidrittelmehrheit.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=4', null, 'belegt', '2026-09-29', false, true, null),
  (5056, 5, 16, null, 'Aktionsplan für Tarifbindung, Bundestariftreuegesetz, Allgemeinverbindlicherklärung auch ohne Zustimmung der Arbeitgeberseite', '{507}', null, 2, 2, null, 'Eine erleichterte Allgemeinverbindlicherklärung kann die Tarifbindung ganzer Branchen erhöhen; die Wirkung ist in Studien begrenzt belegt. Eine Erklärung gegen den Willen der Arbeitgeberseite ist verfassungsrechtlich umstritten (Tarifautonomie).', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=26', null, 'gemischt', '2026-09-29', false, true, null),
  (5061, 5, 17, null, 'Mit Russland über günstiges Erdgas durch den verbliebenen Nord-Stream-Strang verhandeln', '{501}', null, 2, 1, null, 'Günstigeres Pipelinegas aus Russland würde Energiekosten senken; die Versorgung wäre aber von einem einzelnen Lieferanten abhängig. EU-Sanktionen, die EU-Regeln zum Ausstieg aus russischem Gas und die fehlende Zertifizierung der Leitung stehen entgegen.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=10', null, 'gemischt', '2026-09-29', false, true, null),
  (5062, 5, 17, null, 'CO₂-Preis abschaffen', '{501}', null, 1, 1, null, 'Die Industrie zahlt ihren CO₂-Preis vor allem im EU-Emissionshandel, den Deutschland nicht allein abschaffen kann; die Wirkung auf die Industriekosten ist deshalb gering.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=10', null, 'gemischt', '2026-09-29', false, true, null),
  (5063, 5, 17, null, 'Instandhaltung und Ausbau der Energienetze aus öffentlichen Mitteln statt über den Strompreis finanzieren', '{501}', null, 2, 1, null, 'Netzentgelte aus dem Strompreis zu nehmen senkt die Energiekosten direkt und deutlich. Die Netzkosten liegen bei vielen Milliarden Euro im Jahr; die Finanzierung ist offen.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=11', null, 'belegt', '2026-09-29', false, true, null),
  (5064, 5, 17, null, 'Gesetzlichen Mindestlohn unverzüglich auf 15 Euro anheben', '{503}', 6094, 2, 3, null, 'Ein höherer Mindestlohn hebt die unteren Löhne, von denen im Osten mehr Menschen betroffen sind; Studien zur Erhöhung auf 12 Euro fanden kaum Beschäftigungsverluste. Den Abstand oberhalb des Mindestlohns schließt er nicht. Per Bundesgesetz umsetzbar.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=21', null, 'belegt', '2026-09-29', false, true, null),
  (5065, 5, 17, null, 'Investitionen in Infrastruktur aus der Schuldenbremse ausklammern; großes Investitionsprogramm', '{504}', 6098, 2, 1, null, 'Mehr Spielraum für öffentliche Investitionen setzt direkt an der Investitionslücke an. Eine Änderung der Schuldenbremse erfordert eine Grundgesetzänderung mit Zweidrittelmehrheit.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=15', null, 'belegt', '2026-09-29', false, true, null),
  (5066, 5, 17, null, 'Nachhaltigkeitsberichterstattung aussetzen, Lieferkettengesetz reformieren, kleine und mittlere Unternehmen von Berichtspflichten befreien', '{505}', 6097, 2, 1, null, 'Wegfall von Berichtspflichten setzt an den Bürokratiekosten an; bisherige Programme haben die Kosten laut Normenkontrollrat nur langsam gesenkt. Ein Teil der genannten Pflichten beruht auf EU-Recht, das Deutschland nicht allein ändern kann.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=18', null, 'gemischt', '2026-09-29', false, true, null),
  (5067, 5, 17, null, 'Öffentliche Aufträge und Subventionen nur an Unternehmen mit Tariflohn; Allgemeinverbindlicherklärung erleichtern', '{507}', 6095, 2, 3, null, 'Eine erleichterte Allgemeinverbindlicherklärung kann die Tarifbindung ganzer Branchen erhöhen, Tariftreue wirkt nur bei öffentlichen Aufträgen; die Wirkung auf die Tarifquote ist in Studien begrenzt belegt. Per Bundesgesetz umsetzbar.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=21', null, 'gemischt', '2026-09-29', false, true, null),
  (6001, 6, 11, null, 'Asylsuchende an den deutschen Grenzen zurückweisen, wenn sie aus einem EU- oder Schengen-Staat einreisen', '{601,605}', 6099, 1, 1, null, 'Zurückweisungen an den Binnengrenzen können einzelne Einreisen verhindern; seit Mai 2025 betrafen sie nur einige hundert Asylsuchende, eine Wirkung auf die Zugangszahlen ist nicht belegt. Die Vereinbarkeit mit der Dublin-Verordnung ist umstritten (VG Berlin, Juni 2025: im Einzelfall rechtswidrig).', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=42', null, 'gemischt', '2026-09-29', false, true, null),
  (6002, 6, 11, null, 'Familiennachzug zu subsidiär Schutzberechtigten aussetzen, freiwillige Aufnahmeprogramme beenden', '{601}', 6100, 1, 3, null, 'Das Aussetzen des Familiennachzugs zu subsidiär Schutzberechtigten senkt die Zahl der Neuankommenden etwas (vorher bis zu 1.000 Visa im Monat), im Verhältnis zu allen Zuzügen aber wenig; an den Kapazitäten vor Ort ändert es nichts. Per Bundesgesetz umsetzbar, 2025 für zwei Jahre beschlossen.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=43', null, 'gemischt', '2026-09-29', false, true, null),
  (6003, 6, 11, null, 'Berufsanerkennung vereinfachen, Deutschlernen „on the job“ stärken', '{603}', 6101, 2, 2, null, 'Einfachere und schnellere Anerkennungsverfahren setzen an einer Hürde an, die das IAB nennt; wie viel schneller es wird, hängt von der Ausgestaltung ab. Für viele reglementierte Berufe sind die Länder zuständig.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=43', null, 'gemischt', '2026-09-29', false, true, null),
  (6004, 6, 11, null, 'Arbeitsvermittlung nicht wegen laufender Sprach- oder Integrationskurse aufschieben; Spracherwerb berufsbegleitend', '{603}', 6102, 2, 3, null, 'Arbeit parallel zum Sprachkurs kann den Einstieg beschleunigen; Studien zeigen, dass frühe Beschäftigung die Integration fördert, die Wirkung des Job-Turbos von 2023 ist aber noch nicht abschließend untersucht. Umsetzbar über die Bundesagentur für Arbeit.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=31', null, 'gemischt', '2026-09-29', false, true, null),
  (6005, 6, 11, null, 'Weitere Länder als sichere Herkunftsstaaten einstufen', '{602}', 6103, 1, 2, null, 'Mehr sichere Herkunftsstaaten beschleunigen die Verfahren für Antragsteller aus diesen Ländern; die Hauptherkunftsländer (Syrien, Afghanistan, Türkei) kommen dafür aber kaum in Frage. Einstufung per Gesetz, beim Asylgrundrecht mit Zustimmung des Bundesrats.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=43', null, 'gemischt', '2026-09-29', false, true, null),
  (6006, 6, 11, null, 'Mehr Rücknahmeabkommen mit den Hauptherkunftsländern', '{604,606}', 6104, 2, 2, null, 'Abkommen mit Herkunftsstaaten setzen an den Haupthindernissen an (fehlende Papiere, fehlende Mitwirkung), die Abschiebungen verhindern und Duldungen verlängern; die Erfahrungen sind je nach Partnerland gemischt. Umsetzbar nur mit Zustimmung der Partnerstaaten.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=43', null, 'gemischt', '2026-09-29', false, true, null),
  (6007, 6, 11, null, 'Unterstützung des Bundes für die Länder bei Reisepapieren und Rückführungen ausbauen', '{604,606}', null, 2, 3, null, 'Fehlende Reisepapiere sind ein Haupthindernis für Abschiebungen und ein häufiger Grund für lange Duldungen. Der Bund hilft den Ländern dabei schon heute und kann das ausbauen; ob die Herkunftsstaaten Papiere ausstellen, bleibt aber offen.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=43', null, 'gemischt', '2026-09-29', false, true, null),
  (6008, 6, 11, null, 'Zentrale Asylverfahren für beschleunigte Verfahren und Bundesausreisezentren', '{602,604}', null, 1, 2, null, 'Zentrale Einrichtungen können Verfahren und Rückführungen bündeln; ob sie schneller sind, ist nicht untersucht, und an fehlenden Papieren ändern sie nichts. Der Bund müsste die Einrichtungen mit den Ländern aufbauen.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=43', null, 'offen', '2026-09-29', false, true, null),
  (6009, 6, 11, null, 'Bundespolizei darf Ausreisepflichtige in Haft oder Ausreisegewahrsam nehmen', '{604}', 6105, 1, 2, null, 'Mehr Haft und Gewahrsam kann verhindern, dass Ausreisepflichtige vor dem Termin untertauchen; die meisten Abschiebungen scheitern aber an fehlenden Papieren oder am Herkunftsstaat. Haft ist verfassungsrechtlich eng begrenzt, Haftplätze stellen überwiegend die Länder.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=43', null, 'gemischt', '2026-09-29', false, true, null),
  (6010, 6, 11, null, 'Asylverfahren in sicheren Drittstaaten außerhalb Europas', '{601,605}', 6106, 1, 1, null, 'Asylverfahren außerhalb der EU sollen die Weiterreise nach Europa unattraktiv machen; belegt ist das nicht, bisherige Modelle (Großbritannien–Ruanda, Italien–Albanien) kamen kaum in Gang. Umsetzbar nur mit EU-Regeln und aufnahmebereiten Drittstaaten.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=44', null, 'offen', '2026-09-29', false, true, null),
  (6011, 6, 12, null, 'Asylverfahren beim Bundesamt und an den Verwaltungsgerichten durch Digitalisierung beschleunigen, Entscheidung in sechs Monaten', '{602}', null, 2, 2, null, 'Digitalisierung und Verwaltungsmodernisierung setzen an der Verfahrensdauer an; wie viel sie bringen, hängt von der Umsetzung ab. Das Bundesamt steuert der Bund, die Verwaltungsgerichte die Länder.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=55', null, 'gemischt', '2026-09-29', false, true, null),
  (6012, 6, 12, null, 'Ausländerbehörden stärken, Datenaustausch verbessern, Verfahren aus einer Hand', '{601}', null, 1, 2, null, 'Setzt an der Überlastung der Ausländerbehörden an, nennt aber weder Umfang noch Finanzierung. Die Behörden gehören zu Ländern und Kommunen, der Bund kann Datenaustausch und Digitalisierung beisteuern.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=55', null, 'gemischt', '2026-09-29', false, true, null),
  (6013, 6, 12, null, 'Integrationskurse ausbauen und ausreichend finanzieren', '{603}', 6107, 2, 3, null, 'Mehr und früher zugängliche Sprach- und Integrationskurse verkürzen Wartezeiten; Studien des IAB zeigen, dass Integrationskurse Sprachkenntnisse und Beschäftigung verbessern. Anerkennung und Arbeitsmarktzugang bleiben davon unberührt. Der Bund finanziert die Kurse bereits.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=54', null, 'belegt', '2026-09-29', false, true, null),
  (6014, 6, 12, null, 'Spurwechsel in die Fachkräfteeinwanderung für integrierte, straffreie Menschen ohne Schutzstatus', '{606}', 6108, 2, 3, null, 'Ein Bleiberecht für gut integrierte Geduldete beendet die Kettenduldung direkt; mit dem Chancen-Aufenthaltsrecht von 2022 haben viele Geduldete einen Aufenthaltstitel bekommen. Wer die Bedingungen nicht erfüllt, bleibt geduldet. Per Bundesgesetz umsetzbar.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=54', null, 'belegt', '2026-09-29', false, true, null),
  (6015, 6, 12, null, 'Migrationsabkommen mit festen Vereinbarungen zur Rückführung Ausreisepflichtiger', '{604,606}', 6104, 2, 2, null, 'Abkommen mit Herkunftsstaaten setzen an den Haupthindernissen an (fehlende Papiere, fehlende Mitwirkung), die Abschiebungen verhindern und Duldungen verlängern; die Erfahrungen sind je nach Partnerland gemischt. Umsetzbar nur mit Zustimmung der Partnerstaaten.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=56', null, 'gemischt', '2026-09-29', false, true, null),
  (6016, 6, 12, null, 'Solidarische Verteilung von Schutzsuchenden unter allen EU-Staaten', '{605}', 6109, 1, 1, null, 'Eine verbindliche Verteilung in der EU würde die Zuständigkeitsfrage anders lösen; ob Asylsuchende dann im zugewiesenen Staat bleiben, ist offen. Umsetzbar nur mit einer Mehrheit der EU-Staaten, die bisher nicht in Sicht ist.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=55', null, 'offen', '2026-09-29', false, true, null),
  (6021, 6, 13, null, 'Kommunen mit einer Integrationsoffensive stärker und verlässlicher finanziell unterstützen', '{601}', null, 1, 2, null, 'Mehr Geld für die Kommunen setzt an der Kapazitätsseite an; das Programm nennt aber weder Umfang noch Weg der Finanzierung. Der Bund beteiligt sich bereits an den Kosten und kann mehr beisteuern.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=128', null, 'gemischt', '2026-09-29', false, true, null),
  (6022, 6, 13, null, 'Ausfinanzierte Integrations- und Sprachkurse direkt nach der Ankunft', '{603}', 6107, 2, 3, null, 'Mehr und früher zugängliche Sprach- und Integrationskurse verkürzen Wartezeiten; Studien des IAB zeigen, dass Integrationskurse Sprachkenntnisse und Beschäftigung verbessern. Anerkennung und Arbeitsmarktzugang bleiben davon unberührt. Der Bund finanziert die Kurse bereits.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=128', null, 'belegt', '2026-09-29', false, true, null),
  (6023, 6, 13, null, 'Arbeitsverbote abschaffen; arbeitsbezogene Genehmigungen gelten nach kurzer Frist als erteilt', '{603}', 6110, 2, 3, null, 'Ein früher Zugang zum Arbeitsmarkt setzt direkt an; Studien zeigen, dass Beschäftigungsverbote die Integration in Arbeit noch Jahre später verzögern. Sprachkurse und Anerkennung bleiben davon unberührt. Per Bundesgesetz umsetzbar.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=128', null, 'belegt', '2026-09-29', false, true, null),
  (6024, 6, 13, null, 'Spurwechsel ausgestalten; auf das Chancen-Aufenthaltsrecht weitere Reformen folgen lassen', '{606}', 6108, 2, 3, null, 'Ein Bleiberecht für gut integrierte Geduldete beendet die Kettenduldung direkt; mit dem Chancen-Aufenthaltsrecht von 2022 haben viele Geduldete einen Aufenthaltstitel bekommen. Wer die Bedingungen nicht erfüllt, bleibt geduldet. Per Bundesgesetz umsetzbar.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=127', null, 'belegt', '2026-09-29', false, true, null),
  (6025, 6, 13, null, 'Migrationsabkommen: geregelte Migrationswege, dafür nehmen Partnerländer Ausreisepflichtige zurück', '{604,606}', 6104, 2, 2, null, 'Abkommen mit Herkunftsstaaten setzen an den Haupthindernissen an (fehlende Papiere, fehlende Mitwirkung), die Abschiebungen verhindern und Duldungen verlängern; die Erfahrungen sind je nach Partnerland gemischt. Umsetzbar nur mit Zustimmung der Partnerstaaten.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=131', null, 'gemischt', '2026-09-29', false, true, null),
  (6026, 6, 13, null, 'Ausreisepflichtige nach schweren Straftaten vorrangig zurückführen', '{604}', 6111, 1, 2, null, 'Vorrang für Straftäter setzt Schwerpunkte beim Vollzug, beseitigt aber nicht die Hindernisse (fehlende Papiere, Herkunftsstaaten), an denen Abschiebungen meist scheitern. Den Vollzug steuern die Ausländerbehörden der Länder.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=130', null, 'gemischt', '2026-09-29', false, true, null),
  (6027, 6, 13, null, 'Faire, verbindliche und solidarische Verteilung von Schutzsuchenden in Europa', '{605}', 6109, 1, 1, null, 'Eine verbindliche Verteilung in der EU würde die Zuständigkeitsfrage anders lösen; ob Asylsuchende dann im zugewiesenen Staat bleiben, ist offen. Umsetzbar nur mit einer Mehrheit der EU-Staaten, die bisher nicht in Sicht ist.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=130', null, 'offen', '2026-09-29', false, true, null),
  (6031, 6, 14, null, 'Zuständigkeit für Abschiebungen beim Bund zentralisieren', '{604}', null, 1, 1, null, 'Setzt an Vollzugsproblemen in den Ländern an; die Haupthindernisse (fehlende Papiere, Herkunftsstaaten) bleiben. Eine Bundeszuständigkeit für den Vollzug müsste neu geschaffen werden, mit Zustimmung des Bundesrats und je nach Ausgestaltung einer Grundgesetzänderung.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=28', null, 'offen', '2026-09-29', false, true, null),
  (6032, 6, 14, null, 'Asylverfahren auch in Drittstaaten', '{601,605}', 6106, 1, 1, null, 'Asylverfahren außerhalb der EU sollen die Weiterreise nach Europa unattraktiv machen; belegt ist das nicht, bisherige Modelle (Großbritannien–Ruanda, Italien–Albanien) kamen kaum in Gang. Umsetzbar nur mit EU-Regeln und aufnahmebereiten Drittstaaten.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=28', null, 'offen', '2026-09-29', false, true, null),
  (6033, 6, 14, null, 'Geordnetes Verfahren, um mehr sichere Herkunftsstaaten festzustellen', '{602}', 6103, 1, 2, null, 'Mehr sichere Herkunftsstaaten beschleunigen die Verfahren für Antragsteller aus diesen Ländern; die Hauptherkunftsländer (Syrien, Afghanistan, Türkei) kommen dafür aber kaum in Frage. Einstufung per Gesetz, beim Asylgrundrecht mit Zustimmung des Bundesrats.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=28', null, 'gemischt', '2026-09-29', false, true, null),
  (6034, 6, 14, null, 'Familiennachzug zu subsidiär Schutzberechtigten aussetzen, Aufnahmeprogramme pausieren', '{601}', 6100, 1, 3, null, 'Das Aussetzen des Familiennachzugs zu subsidiär Schutzberechtigten senkt die Zahl der Neuankommenden etwas (vorher bis zu 1.000 Visa im Monat), im Verhältnis zu allen Zuzügen aber wenig; an den Kapazitäten vor Ort ändert es nichts. Per Bundesgesetz umsetzbar, 2025 für zwei Jahre beschlossen.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=28', null, 'gemischt', '2026-09-29', false, true, null),
  (6035, 6, 14, null, 'Zurückweisungen an den deutschen Grenzen modellhaft erproben', '{601,605}', 6099, 1, 1, null, 'Zurückweisungen an den Binnengrenzen können einzelne Einreisen verhindern; seit Mai 2025 betrafen sie nur einige hundert Asylsuchende, eine Wirkung auf die Zugangszahlen ist nicht belegt. Die Vereinbarkeit mit der Dublin-Verordnung ist umstritten (VG Berlin, Juni 2025: im Einzelfall rechtswidrig).', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=28', null, 'gemischt', '2026-09-29', false, true, null),
  (6036, 6, 14, null, 'EU-Migrationsabkommen für mehr Rücknahmebereitschaft; bilaterale Migrationspartnerschaften', '{604,606}', null, 2, 1, null, 'Abkommen mit Herkunftsstaaten setzen an den Haupthindernissen an (fehlende Papiere, fehlende Mitwirkung), die Abschiebungen verhindern und Duldungen verlängern; die Erfahrungen sind gemischt. Der Schwerpunkt liegt auf EU-Abkommen, die Deutschland nicht allein schließen kann.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=28', null, 'gemischt', '2026-09-29', false, true, null),
  (6037, 6, 14, null, 'Spurwechsel für gut integrierte Schutzsuchende, die ohne Transferleistungen leben können', '{606}', null, 1, 3, null, 'Ein Spurwechsel beendet die Duldung für die, die ihn schaffen; die Bedingung, dass die ganze Familie ohne Transferleistungen lebt, erfüllen aber nur wenige Geduldete. Per Bundesgesetz umsetzbar.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=28', null, 'gemischt', '2026-09-29', false, true, null),
  (6038, 6, 14, null, 'Anerkennung ausländischer Abschlüsse beschleunigen und durchgehend digitalisieren', '{603}', 6101, 2, 2, null, 'Einfachere und schnellere Anerkennungsverfahren setzen an einer Hürde an, die das IAB nennt; wie viel schneller es wird, hängt von der Ausgestaltung ab. Für viele reglementierte Berufe sind die Länder zuständig.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=9', null, 'gemischt', '2026-09-29', false, true, null),
  (6039, 6, 14, null, 'Sprach- und Integrationskurse trennen; Sprachkurse modular und leistungsdifferenziert', '{603}', null, 1, 3, null, 'Modulare, berufsbegleitende Kurse können den Einstieg in Arbeit erleichtern; dass eine Trennung von Sprach- und Integrationskurs schneller zum Ziel führt, ist nicht untersucht. Die Kurse regelt der Bund.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=29', null, 'offen', '2026-09-29', false, true, null),
  (6040, 6, 14, null, 'Wohnsitzauflage stärker nutzen', '{601}', null, 1, 3, null, 'Die Wohnsitzauflage verteilt Geflüchtete gleichmäßiger auf die Kommunen und kann Ballungsräume entlasten; Studien finden aber, dass sie die Aufnahme von Arbeit verzögern kann. Per Bundesgesetz umsetzbar.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=28', null, 'gemischt', '2026-09-29', false, true, null),
  (6041, 6, 15, null, 'Grenzen selbst kontrollieren, illegal Einreisende an der Grenze zurückweisen', '{601,605}', 6099, 1, 1, null, 'Zurückweisungen an den Binnengrenzen können einzelne Einreisen verhindern; seit Mai 2025 betrafen sie nur einige hundert Asylsuchende, eine Wirkung auf die Zugangszahlen ist nicht belegt. Die Vereinbarkeit mit der Dublin-Verordnung ist umstritten (VG Berlin, Juni 2025: im Einzelfall rechtswidrig).', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=104', null, 'gemischt', '2026-09-29', false, true, null),
  (6042, 6, 15, null, 'Asylanträge künftig außerhalb Deutschlands stellen und bearbeiten', '{601,605}', 6106, 1, 1, null, 'Asylverfahren außerhalb der EU sollen die Weiterreise nach Europa unattraktiv machen; belegt ist das nicht, bisherige Modelle (Großbritannien–Ruanda, Italien–Albanien) kamen kaum in Gang. Umsetzbar nur mit EU-Regeln und aufnahmebereiten Drittstaaten.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=104', null, 'offen', '2026-09-29', false, true, null),
  (6043, 6, 15, null, 'Zahl der sicheren Herkunftsstaaten deutlich ausweiten', '{602}', 6103, 1, 2, null, 'Mehr sichere Herkunftsstaaten beschleunigen die Verfahren für Antragsteller aus diesen Ländern; die Hauptherkunftsländer (Syrien, Afghanistan, Türkei) kommen dafür aber kaum in Frage. Einstufung per Gesetz, beim Asylgrundrecht mit Zustimmung des Bundesrats.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=105', null, 'gemischt', '2026-09-29', false, true, null),
  (6044, 6, 15, null, 'Asylverfahren vor den Verwaltungsgerichten straffen, mehr Personal zum Abbau von Altfällen', '{602}', 6112, 2, 2, null, 'Mehr Personal und gestraffte Verfahren setzen direkt an der Verfahrensdauer an; beim Bundesamt hat Personalaufbau Rückstände schon abgebaut. Das Bundesamt und das Asylprozessrecht regelt der Bund, das Personal der Verwaltungsgerichte stellen die Länder.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=106', null, 'gemischt', '2026-09-29', false, true, null),
  (6045, 6, 15, null, 'Druck auf nicht rücknahmebereite Herkunftsländer über Wirtschaftssanktionen, Entwicklungshilfe und Visa', '{604,606}', null, 2, 1, null, 'Druck auf Herkunftsstaaten setzt an deren fehlender Mitwirkung an, einem Haupthindernis für Abschiebungen; die Erfahrungen damit sind gemischt. Wirtschaftssanktionen und der Visahebel liegen bei der EU, nur die Entwicklungshilfe kann Deutschland allein kürzen.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=108', null, 'gemischt', '2026-09-29', false, true, null),
  (6046, 6, 15, null, 'Haft- und Gewahrsamsplätze in Grenznähe und an Flughäfen ausbauen', '{604}', 6105, 1, 2, null, 'Mehr Haft und Gewahrsam kann verhindern, dass Ausreisepflichtige vor dem Termin untertauchen; die meisten Abschiebungen scheitern aber an fehlenden Papieren oder am Herkunftsstaat. Haft ist verfassungsrechtlich eng begrenzt, Haftplätze stellen überwiegend die Länder.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=108', null, 'gemischt', '2026-09-29', false, true, null),
  (6047, 6, 15, null, 'Grundsätzlichen Anspruch auf Familiennachzug zu subsidiär Schutzberechtigten streichen', '{601}', 6100, 1, 3, null, 'Das Aussetzen des Familiennachzugs zu subsidiär Schutzberechtigten senkt die Zahl der Neuankommenden etwas (vorher bis zu 1.000 Visa im Monat), im Verhältnis zu allen Zuzügen aber wenig; an den Kapazitäten vor Ort ändert es nichts. Per Bundesgesetz umsetzbar, 2025 für zwei Jahre beschlossen.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=105', null, 'gemischt', '2026-09-29', false, true, null),
  (6048, 6, 15, null, 'Asylsuchende für die Dauer des Verfahrens in zentralen Aufnahmeeinrichtungen unterbringen', '{601}', null, 1, 2, null, 'Entlastet die Kommunen bei der Unterbringung, verlagert die Last aber auf die Erstaufnahme der Länder; ob die Plätze reichen, ist offen. Die Wohnpflicht regelt der Bund, die Plätze schaffen die Länder.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=106', null, 'offen', '2026-09-29', false, true, null),
  (6049, 6, 15, null, 'Bundesprogramme zur Förderung der freiwilligen Rückkehr ausweiten', '{604,606}', null, 1, 3, null, 'Rückkehrförderung kann Ausreisen erleichtern, auch bei fehlenden Papieren; Studien finden eher begrenzte Effekte. Der Bund finanziert solche Programme bereits.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=109', null, 'gemischt', '2026-09-29', false, true, null),
  (6050, 6, 15, null, 'Pflicht zum Spracherwerb auf B2-Niveau in der Regel binnen zwei Jahren; Kosten abgebrochener Kurse erstatten', '{603}', null, 1, 2, null, 'Pflichten und Rückforderungen können den Abschluss von Kursen fördern, verkürzen aber keine Wartezeiten auf Kursplätze; eine Wirkung ist nicht untersucht. Per Bundesgesetz umsetzbar, Rückforderungen sind verwaltungsaufwendig.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=110', null, 'offen', '2026-09-29', false, true, null),
  (6051, 6, 16, null, 'Fonds für Willkommenskommunen; der Bund erstattet die Unterbringungskosten vollständig pro Person', '{601}', null, 2, 2, null, 'Mehr Bundesgeld setzt an der Kapazitätsseite an, vor allem bei der Unterbringung; Geld allein schafft aber nicht sofort Wohnraum und Personal. Der Bund beteiligt sich bereits mit einer Pauschale, eine volle Erstattung wäre deutlich teurer, die Finanzierung ist offen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=52', null, 'gemischt', '2026-09-29', false, true, null),
  (6052, 6, 16, null, 'Uneingeschränkte Arbeitserlaubnis für alle Geflüchteten ab dem Tag der Ankunft', '{603}', 6110, 2, 3, null, 'Ein früher Zugang zum Arbeitsmarkt setzt direkt an; Studien zeigen, dass Beschäftigungsverbote die Integration in Arbeit noch Jahre später verzögern. Sprachkurse und Anerkennung bleiben davon unberührt. Per Bundesgesetz umsetzbar.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=52', null, 'belegt', '2026-09-29', false, true, null),
  (6053, 6, 16, null, 'Flächendeckend kostenlose Sprachkurse für Geflüchtete', '{603}', 6107, 2, 3, null, 'Mehr und früher zugängliche Sprach- und Integrationskurse verkürzen Wartezeiten; Studien des IAB zeigen, dass Integrationskurse Sprachkenntnisse und Beschäftigung verbessern. Anerkennung und Arbeitsmarktzugang bleiben davon unberührt. Der Bund finanziert die Kurse bereits.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=52', null, 'belegt', '2026-09-29', false, true, null),
  (6054, 6, 16, null, 'Legalisierung für Menschen ohne Aufenthaltsstatus; wirksame Bleiberechtsregelungen bei Kettenduldungen', '{606}', null, 2, 3, null, 'Bleiberechtsregelungen beenden lange Duldungen direkt; das Chancen-Aufenthaltsrecht von 2022 zeigt, dass solche Regelungen genutzt werden. Wer genau ein Bleiberecht bekommen soll, lässt das Programm offen. Per Bundesgesetz umsetzbar.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=53', null, 'belegt', '2026-09-29', false, true, null),
  (6055, 6, 16, null, 'Europäische Fluchtumlage: EU-Geld für aufnahmebereite Länder, Regionen und Städte', '{605}', null, 1, 1, null, 'Geld aus EU-Mitteln für aufnahmebereite Regionen könnte die Verteilung freiwillig verbessern; an den gescheiterten Überstellungen setzt es nur indirekt an. Umsetzbar nur mit einem Beschluss auf EU-Ebene.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=53', null, 'offen', '2026-09-29', false, true, null),
  (6061, 6, 17, null, 'Job-Turbo für Ukrainer und andere Geflüchtete mit Schutzstatus umsetzen', '{603}', 6102, 2, 3, null, 'Arbeit parallel zum Sprachkurs kann den Einstieg beschleunigen; Studien zeigen, dass frühe Beschäftigung die Integration fördert, die Wirkung des Job-Turbos von 2023 ist aber noch nicht abschließend untersucht. Umsetzbar über die Bundesagentur für Arbeit.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=36', null, 'gemischt', '2026-09-29', false, true, null),
  (6062, 6, 17, null, 'Wer aus einem sicheren Drittstaat einreist, bekommt kein Asylverfahren und keinen Aufenthalt', '{601,605}', null, 1, 0, null, 'Würde Einreisen über Nachbarstaaten praktisch ausschließen, wenn diese die Menschen zurücknehmen. Die Dublin-Verordnung und das neue europäische Asylsystem verlangen aber eine Prüfung, welcher Staat zuständig ist; ein genereller Ausschluss ist mit dem EU-Recht nicht vereinbar.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=36', null, 'gemischt', '2026-09-29', false, true, null),
  (6063, 6, 17, null, 'Behörden und Gerichte vorrangig mit Personal ausstatten, Asylverfahren in drei Monaten', '{602}', 6112, 2, 2, null, 'Mehr Personal und gestraffte Verfahren setzen direkt an der Verfahrensdauer an; beim Bundesamt hat Personalaufbau Rückstände schon abgebaut. Das Bundesamt und das Asylprozessrecht regelt der Bund, das Personal der Verwaltungsgerichte stellen die Länder.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=37', null, 'gemischt', '2026-09-29', false, true, null),
  (6064, 6, 17, null, 'Straftäter ausweisen und abschieben, Verfahren dazu vorrangig betreiben', '{604}', 6111, 1, 2, null, 'Vorrang für Straftäter setzt Schwerpunkte beim Vollzug, beseitigt aber nicht die Hindernisse (fehlende Papiere, Herkunftsstaaten), an denen Abschiebungen meist scheitern. Den Vollzug steuern die Ausländerbehörden der Länder.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=37', null, 'gemischt', '2026-09-29', false, true, null),
  (6065, 6, 17, null, 'Erwachsenenbildung zum Nachholen von Schulabschlüssen und Nachqualifikation bei abweichenden Berufsausbildungen', '{603}', null, 2, 2, null, 'Nachqualifizierung setzt an einer Hürde an, die das IAB nennt (Abschlüsse passen nicht zum deutschen System); Studien zeigen positive Effekte. Erwachsenenbildung ist weitgehend Ländersache, der Bund kann über die Arbeitsförderung beitragen.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=37', null, 'gemischt', '2026-09-29', false, true, null),
  (6066, 6, 17, null, 'Asylverfahren möglichst außerhalb der EU in sicheren Drittstaaten', '{601,605}', 6106, 1, 1, null, 'Asylverfahren außerhalb der EU sollen die Weiterreise nach Europa unattraktiv machen; belegt ist das nicht, bisherige Modelle (Großbritannien–Ruanda, Italien–Albanien) kamen kaum in Gang. Umsetzbar nur mit EU-Regeln und aufnahmebereiten Drittstaaten.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=38', null, 'offen', '2026-09-29', false, true, null),
  (6123, 6, 11, 'ST', 'Bezahlkarte für Asylsuchende dauerhaft beibehalten und weiterentwickeln', '{601}', 6113, 1, 3, null, 'Bezahlkarte und Sachleistungen sollen Anreize senken und Auszahlungen vereinfachen; eine Wirkung auf die Zahl der Neuankommenden ist nicht belegt, an Unterkünften und Ausländerbehörden ändert sich nichts. Die Länder können sie im Rahmen des Asylbewerberleistungsgesetzes selbst einführen.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=8', null, 'offen', '2026-09-29', false, true, null),
  (6124, 6, 11, 'ST', 'Zentrale Erstaufnahme dauerhaft absichern', '{601}', 6114, 1, 2, null, 'Zentrale Unterbringung, etwa bis zum Asylbescheid, entlastet die Kommunen, verlagert den Bedarf an Plätzen aber auf das Land; ob Verfahren und Rückführungen dadurch schneller werden, ist kaum untersucht. Das Land schafft die Plätze, die Wohnpflicht regelt der Bund.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=8', null, 'offen', '2026-09-29', false, true, null),
  (6125, 6, 11, 'ST', 'Leistungsfähige Ausländerbehörden absichern und weiterentwickeln', '{601}', 6115, 2, 2, null, 'Setzt direkt an der Überlastung der Ausländerbehörden an; wie viel schneller die Verfahren werden, hängt von Stellen und Digitalisierung ab und ist wenig untersucht. Das Land kann Personal und Digitalisierung mitfinanzieren, braucht dafür aber Geld und Fachkräfte.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=8', null, 'offen', '2026-09-29', false, true, null),
  (6126, 6, 11, 'ST', 'Auf Bundesebene: Asylverfahren an den EU-Außengrenzen, Aufnahmeprogramme beenden, Familiennachzug zu subsidiär Schutzberechtigten weiter aussetzen', '{601}', 6117, 1, 1, null, 'Grenzkontrollen, Zurückweisungen, Familiennachzug oder Asylverfahren an den EU-Außengrenzen kann ein Land nicht selbst regeln, sondern nur über den Bundesrat oder beim Bund darauf hinwirken; die Wirkung solcher Maßnahmen auf die Zugangszahlen ist zudem umstritten.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=8', null, 'gemischt', '2026-09-29', false, true, null),
  (6127, 6, 12, 'ST', 'Kommunen für die Erstintegration ausstatten', '{601}', 6116, 1, 2, null, 'Mehr Landesgeld, etwa als Pauschale je Platz oder Person, setzt an der Kapazitätsseite an; Geld allein schafft aber nicht sofort Unterkünfte, Kitaplätze oder Personal, und die Programme nennen meist keinen Umfang. Umsetzbar über den Landeshaushalt.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=11', null, 'gemischt', '2026-09-29', false, true, null),
  (6128, 6, 13, 'ST', 'Ausländerbehörden besser ausstatten und zu Migrationszentren weiterentwickeln', '{601}', 6115, 2, 2, null, 'Setzt direkt an der Überlastung der Ausländerbehörden an; wie viel schneller die Verfahren werden, hängt von Stellen und Digitalisierung ab und ist wenig untersucht. Das Land kann Personal und Digitalisierung mitfinanzieren, braucht dafür aber Geld und Fachkräfte.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=78', null, 'offen', '2026-09-29', false, true, null),
  (6129, 6, 13, 'ST', 'Geflüchtete zügig in private Wohnungen vermitteln', '{601}', 6118, 1, 2, null, 'Wohnungen statt Sammelunterkünften erleichtern das Ankommen und können günstiger sein; zusätzliche Plätze entstehen aber nur, wo Wohnungen frei sind, in angespannten Wohnungsmärkten konkurriert der Bedarf mit anderen Wohnungssuchenden. Das Land kann es über Aufnahmegesetz und Förderung steuern.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=78', null, 'gemischt', '2026-09-29', false, true, null),
  (6130, 6, 14, 'ST', 'Ausländerbehörden bei der Digitalisierung unterstützen; Arbeitserlaubnis binnen vier Wochen', '{601}', 6115, 2, 2, null, 'Setzt direkt an der Überlastung der Ausländerbehörden an; wie viel schneller die Verfahren werden, hängt von Stellen und Digitalisierung ab und ist wenig untersucht. Das Land kann Personal und Digitalisierung mitfinanzieren, braucht dafür aber Geld und Fachkräfte.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=10', null, 'offen', '2026-09-29', false, true, null),
  (6131, 6, 15, 'ST', 'Über den Bundesrat stärkere Grenzkontrollen und Zurückweisungen durchsetzen', '{601}', 6117, 1, 1, null, 'Grenzkontrollen, Zurückweisungen, Familiennachzug oder Asylverfahren an den EU-Außengrenzen kann ein Land nicht selbst regeln, sondern nur über den Bundesrat oder beim Bund darauf hinwirken; die Wirkung solcher Maßnahmen auf die Zugangszahlen ist zudem umstritten.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=27', null, 'gemischt', '2026-09-29', false, true, null),
  (6132, 6, 15, 'ST', 'Aufnahme von Personen verweigern, die aus einem sicheren Drittstaat eingereist sind', '{601}', 6120, 1, 0, null, 'Ein Aufnahmestopp würde das Land entlasten, den Bedarf aber auf andere Länder verschieben. Die Länder sind nach dem Asylgesetz verpflichtet, die ihnen zugewiesenen Asylsuchenden aufzunehmen; ein einseitiger Stopp ist rechtlich derzeit nicht umsetzbar.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=27', null, 'offen', '2026-09-29', false, true, null),
  (6133, 6, 15, 'ST', 'Aufnahmestopp des Landes als Ultima Ratio', '{601}', 6120, 1, 0, null, 'Ein Aufnahmestopp würde das Land entlasten, den Bedarf aber auf andere Länder verschieben. Die Länder sind nach dem Asylgesetz verpflichtet, die ihnen zugewiesenen Asylsuchenden aufzunehmen; ein einseitiger Stopp ist rechtlich derzeit nicht umsetzbar.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=31', null, 'offen', '2026-09-29', false, true, null),
  (6134, 6, 15, 'ST', 'Zuzugsstopps für überforderte Kommunen verhängen (negative Wohnsitzauflage)', '{601}', 6119, 1, 3, null, 'Verteilung nach Leistungsfähigkeit oder Zuzugssperren für überlastete Orte (§ 12a Aufenthaltsgesetz) entlasten einzelne Kommunen, verschieben den Bedarf aber nur im Land; Wohnsitzauflagen können laut Studien die Arbeitsaufnahme verzögern. Das Land kann es selbst regeln.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=30', null, 'gemischt', '2026-09-29', false, true, null),
  (6135, 6, 15, 'ST', 'Asylbewerber in zentralen Unterkünften unterbringen', '{601}', 6114, 1, 2, null, 'Zentrale Unterbringung, etwa bis zum Asylbescheid, entlastet die Kommunen, verlagert den Bedarf an Plätzen aber auf das Land; ob Verfahren und Rückführungen dadurch schneller werden, ist kaum untersucht. Das Land schafft die Plätze, die Wohnpflicht regelt der Bund.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=33', null, 'offen', '2026-09-29', false, true, null),
  (6136, 6, 15, 'ST', 'Sachleistungsprinzip konsequent anwenden', '{601}', 6113, 1, 3, null, 'Bezahlkarte und Sachleistungen sollen Anreize senken und Auszahlungen vereinfachen; eine Wirkung auf die Zahl der Neuankommenden ist nicht belegt, an Unterkünften und Ausländerbehörden ändert sich nichts. Die Länder können sie im Rahmen des Asylbewerberleistungsgesetzes selbst einführen.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=35', null, 'offen', '2026-09-29', false, true, null),
  (6137, 6, 16, 'ST', 'Aufnahmegesetz reformieren; Integrationsbudget mit Mitteln für die Kommunen', '{601}', 6116, 1, 2, null, 'Mehr Landesgeld, etwa als Pauschale je Platz oder Person, setzt an der Kapazitätsseite an; Geld allein schafft aber nicht sofort Unterkünfte, Kitaplätze oder Personal, und die Programme nennen meist keinen Umfang. Umsetzbar über den Landeshaushalt.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=97', null, 'gemischt', '2026-09-29', false, true, null),
  (6138, 6, 17, 'ST', 'Unterbringungskosten der Kommunen durch den Bund übernehmen lassen', '{601}', 6122, 1, 1, null, 'Eine volle Kostenübernahme durch den Bund würde Länder und Kommunen finanziell entlasten, schafft aber nicht sofort Plätze; ein Land kann sie nur fordern, entscheiden müssen Bundesregierung und Bundestag.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=65', null, 'gemischt', '2026-09-29', false, true, null),
  (6139, 6, 11, 'MV', 'Missbrauch der Bezahlkarte beenden', '{601}', 6113, 1, 3, null, 'Bezahlkarte und Sachleistungen sollen Anreize senken und Auszahlungen vereinfachen; eine Wirkung auf die Zahl der Neuankommenden ist nicht belegt, an Unterkünften und Ausländerbehörden ändert sich nichts. Die Länder können sie im Rahmen des Asylbewerberleistungsgesetzes selbst einführen.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=37', null, 'offen', '2026-09-29', false, true, null),
  (6140, 6, 13, 'MV', 'Gemeinschaftsunterkünfte reduzieren, dezentrales Wohnen stärken', '{601}', 6118, 1, 2, null, 'Wohnungen statt Sammelunterkünften erleichtern das Ankommen und können günstiger sein; zusätzliche Plätze entstehen aber nur, wo Wohnungen frei sind, in angespannten Wohnungsmärkten konkurriert der Bedarf mit anderen Wohnungssuchenden. Das Land kann es über Aufnahmegesetz und Förderung steuern.', 'https://gruene-mv.de/?wpdmdl=33772#page=92', null, 'gemischt', '2026-09-29', false, true, null),
  (6141, 6, 14, 'MV', 'Menschen ohne Bleibeperspektive in den Erstaufnahmeeinrichtungen belassen', '{601}', 6114, 1, 2, null, 'Zentrale Unterbringung, etwa bis zum Asylbescheid, entlastet die Kommunen, verlagert den Bedarf an Plätzen aber auf das Land; ob Verfahren und Rückführungen dadurch schneller werden, ist kaum untersucht. Das Land schafft die Plätze, die Wohnpflicht regelt der Bund.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=144', null, 'offen', '2026-09-29', false, true, null),
  (6142, 6, 14, 'MV', 'Landesweit einheitliche Bezahlkarte umsetzen und beibehalten', '{601}', 6113, 1, 3, null, 'Bezahlkarte und Sachleistungen sollen Anreize senken und Auszahlungen vereinfachen; eine Wirkung auf die Zahl der Neuankommenden ist nicht belegt, an Unterkünften und Ausländerbehörden ändert sich nichts. Die Länder können sie im Rahmen des Asylbewerberleistungsgesetzes selbst einführen.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=143', null, 'offen', '2026-09-29', false, true, null),
  (6143, 6, 14, 'MV', 'Ausländerbehörden personell und organisatorisch stärken', '{601}', 6115, 2, 2, null, 'Setzt direkt an der Überlastung der Ausländerbehörden an; wie viel schneller die Verfahren werden, hängt von Stellen und Digitalisierung ab und ist wenig untersucht. Das Land kann Personal und Digitalisierung mitfinanzieren, braucht dafür aber Geld und Fachkräfte.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=144', null, 'offen', '2026-09-29', false, true, null),
  (6144, 6, 15, 'MV', 'Landesweiten Aufnahmestopp als Option', '{601}', 6120, 1, 0, null, 'Ein Aufnahmestopp würde das Land entlasten, den Bedarf aber auf andere Länder verschieben. Die Länder sind nach dem Asylgesetz verpflichtet, die ihnen zugewiesenen Asylsuchenden aufzunehmen; ein einseitiger Stopp ist rechtlich derzeit nicht umsetzbar.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=48', null, 'offen', '2026-09-29', false, true, null),
  (6145, 6, 15, 'MV', 'Den Bund zu echtem Grenzschutz drängen', '{601}', 6117, 1, 1, null, 'Grenzkontrollen, Zurückweisungen, Familiennachzug oder Asylverfahren an den EU-Außengrenzen kann ein Land nicht selbst regeln, sondern nur über den Bundesrat oder beim Bund darauf hinwirken; die Wirkung solcher Maßnahmen auf die Zugangszahlen ist zudem umstritten.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=48', null, 'gemischt', '2026-09-29', false, true, null),
  (6146, 6, 15, 'MV', 'Asylbewerber in wenigen großen Unterkünften unterbringen', '{601}', 6114, 1, 2, null, 'Zentrale Unterbringung, etwa bis zum Asylbescheid, entlastet die Kommunen, verlagert den Bedarf an Plätzen aber auf das Land; ob Verfahren und Rückführungen dadurch schneller werden, ist kaum untersucht. Das Land schafft die Plätze, die Wohnpflicht regelt der Bund.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=49', null, 'offen', '2026-09-29', false, true, null),
  (6147, 6, 15, 'MV', 'Sachleistungsprinzip maximal ausweiten', '{601}', 6113, 1, 3, null, 'Bezahlkarte und Sachleistungen sollen Anreize senken und Auszahlungen vereinfachen; eine Wirkung auf die Zahl der Neuankommenden ist nicht belegt, an Unterkünften und Ausländerbehörden ändert sich nichts. Die Länder können sie im Rahmen des Asylbewerberleistungsgesetzes selbst einführen.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=52', null, 'offen', '2026-09-29', false, true, null),
  (6148, 6, 16, 'MV', 'Dezentrale Unterbringung priorisieren; Kommunen bei der Wohnraumversorgung Geflüchteter unterstützen', '{601}', 6118, 1, 2, null, 'Wohnungen statt Sammelunterkünften erleichtern das Ankommen und können günstiger sein; zusätzliche Plätze entstehen aber nur, wo Wohnungen frei sind, in angespannten Wohnungsmärkten konkurriert der Bedarf mit anderen Wohnungssuchenden. Das Land kann es über Aufnahmegesetz und Förderung steuern.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=13', null, 'gemischt', '2026-09-29', false, true, null),
  (6149, 6, 17, 'MV', 'Geflüchtete nach der tatsächlichen Leistungsfähigkeit der Kommunen verteilen', '{601}', 6119, 1, 3, null, 'Verteilung nach Leistungsfähigkeit oder Zuzugssperren für überlastete Orte (§ 12a Aufenthaltsgesetz) entlasten einzelne Kommunen, verschieben den Bedarf aber nur im Land; Wohnsitzauflagen können laut Studien die Arbeitsaufnahme verzögern. Das Land kann es selbst regeln.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=74', null, 'gemischt', '2026-09-29', false, true, null),
  (6150, 6, 17, 'MV', 'Unterbringung verlässlich durch Land und Bund finanzieren', '{601}', 6116, 1, 2, null, 'Mehr Landesgeld, etwa als Pauschale je Platz oder Person, setzt an der Kapazitätsseite an; Geld allein schafft aber nicht sofort Unterkünfte, Kitaplätze oder Personal, und die Programme nennen meist keinen Umfang. Umsetzbar über den Landeshaushalt.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=74', null, 'gemischt', '2026-09-29', false, true, null),
  (6151, 6, 17, 'MV', 'Asylverfahren an den EU-Außengrenzen oder in sicheren Drittstaaten unterstützen', '{601}', 6117, 1, 1, null, 'Grenzkontrollen, Zurückweisungen, Familiennachzug oder Asylverfahren an den EU-Außengrenzen kann ein Land nicht selbst regeln, sondern nur über den Bundesrat oder beim Bund darauf hinwirken; die Wirkung solcher Maßnahmen auf die Zugangszahlen ist zudem umstritten.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=73', null, 'gemischt', '2026-09-29', false, true, null),
  (6152, 6, 11, 'BE', 'Asylbewerber vom ersten Tag bis zur Entscheidung über den Asylantrag in zentralen Einrichtungen unterbringen', '{601}', 6114, 1, 2, null, 'Zentrale Unterbringung, etwa bis zum Asylbescheid, entlastet die Kommunen, verlagert den Bedarf an Plätzen aber auf das Land; ob Verfahren und Rückführungen dadurch schneller werden, ist kaum untersucht. Das Land schafft die Plätze, die Wohnpflicht regelt der Bund.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=25', null, 'offen', '2026-09-29', false, true, null),
  (6153, 6, 11, 'BE', 'Bezahlkarte dauerhaft etablieren', '{601}', 6113, 1, 3, null, 'Bezahlkarte und Sachleistungen sollen Anreize senken und Auszahlungen vereinfachen; eine Wirkung auf die Zahl der Neuankommenden ist nicht belegt, an Unterkünften und Ausländerbehörden ändert sich nichts. Die Länder können sie im Rahmen des Asylbewerberleistungsgesetzes selbst einführen.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=25', null, 'offen', '2026-09-29', false, true, null),
  (6154, 6, 12, 'BE', 'Weg von Notunterkünften: dezentrales Wohnen, Geflüchtetenwohnen ausbauen, alle Bezirke beteiligen', '{601}', 6118, 1, 2, null, 'Wohnungen statt Sammelunterkünften erleichtern das Ankommen und können günstiger sein; zusätzliche Plätze entstehen aber nur, wo Wohnungen frei sind, in angespannten Wohnungsmärkten konkurriert der Bedarf mit anderen Wohnungssuchenden. Das Land kann es über Aufnahmegesetz und Förderung steuern.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=52', null, 'gemischt', '2026-09-29', false, true, null),
  (6155, 6, 12, 'BE', 'Gemeinschaftspauschale je Geflüchteten und Bezirk stärken', '{601}', 6116, 1, 2, null, 'Mehr Landesgeld, etwa als Pauschale je Platz oder Person, setzt an der Kapazitätsseite an; Geld allein schafft aber nicht sofort Unterkünfte, Kitaplätze oder Personal, und die Programme nennen meist keinen Umfang. Umsetzbar über den Landeshaushalt.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=52', null, 'gemischt', '2026-09-29', false, true, null),
  (6156, 6, 13, 'BE', 'Unterbringung vorrangig in Wohnungen und kleineren Gemeinschaftsunterkünften in allen Bezirken', '{601}', 6118, 1, 2, null, 'Wohnungen statt Sammelunterkünften erleichtern das Ankommen und können günstiger sein; zusätzliche Plätze entstehen aber nur, wo Wohnungen frei sind, in angespannten Wohnungsmärkten konkurriert der Bedarf mit anderen Wohnungssuchenden. Das Land kann es über Aufnahmegesetz und Förderung steuern.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=145', null, 'gemischt', '2026-09-29', false, true, null),
  (6157, 6, 13, 'BE', 'Jährliche Pauschale je Unterbringungsplatz für die Bezirke', '{601}', 6116, 1, 2, null, 'Mehr Landesgeld, etwa als Pauschale je Platz oder Person, setzt an der Kapazitätsseite an; Geld allein schafft aber nicht sofort Unterkünfte, Kitaplätze oder Personal, und die Programme nennen meist keinen Umfang. Umsetzbar über den Landeshaushalt.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=72', null, 'gemischt', '2026-09-29', false, true, null),
  (6158, 6, 13, 'BE', 'Senatskommission Unterbringung soll neue Standorte zügig festlegen', '{601}', 6121, 2, 2, null, 'Verbindliche Vorgaben für Standorte und die Nutzung leer stehender Gebäude setzen direkt an fehlenden Unterkünften an; Planung und Umbau dauern aber, und gegen einzelne Standorte gibt es oft Widerstand vor Ort. Umsetzbar über Landesrecht und Landeshaushalt.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=146', null, 'gemischt', '2026-09-29', false, true, null),
  (6159, 6, 13, 'BE', 'Landesamt für Einwanderung stärken, digitales Antragssystem für alle Aufenthaltstitel', '{601}', 6115, 2, 2, null, 'Setzt direkt an der Überlastung der Ausländerbehörden an; wie viel schneller die Verfahren werden, hängt von Stellen und Digitalisierung ab und ist wenig untersucht. Das Land kann Personal und Digitalisierung mitfinanzieren, braucht dafür aber Geld und Fachkräfte.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=146', null, 'offen', '2026-09-29', false, true, null),
  (6160, 6, 14, 'BE', 'Bezahlkarte für Geflüchtete sofort einführen', '{601}', 6113, 1, 3, null, 'Bezahlkarte und Sachleistungen sollen Anreize senken und Auszahlungen vereinfachen; eine Wirkung auf die Zahl der Neuankommenden ist nicht belegt, an Unterkünften und Ausländerbehörden ändert sich nichts. Die Länder können sie im Rahmen des Asylbewerberleistungsgesetzes selbst einführen.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=96', null, 'offen', '2026-09-29', false, true, null),
  (6161, 6, 14, 'BE', 'Bei guter Bleibeprognose dezentrale Unterbringung in Wohnungen („Leverkusener Modell“)', '{601}', 6118, 1, 2, null, 'Wohnungen statt Sammelunterkünften erleichtern das Ankommen und können günstiger sein; zusätzliche Plätze entstehen aber nur, wo Wohnungen frei sind, in angespannten Wohnungsmärkten konkurriert der Bedarf mit anderen Wohnungssuchenden. Das Land kann es über Aufnahmegesetz und Förderung steuern.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=96', null, 'gemischt', '2026-09-29', false, true, null),
  (6162, 6, 15, 'BE', 'Sofortiger Aufnahmestopp für Asylbewerber in Berlin', '{601}', 6120, 1, 0, null, 'Ein Aufnahmestopp würde das Land entlasten, den Bedarf aber auf andere Länder verschieben. Die Länder sind nach dem Asylgesetz verpflichtet, die ihnen zugewiesenen Asylsuchenden aufzunehmen; ein einseitiger Stopp ist rechtlich derzeit nicht umsetzbar.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=22', null, 'offen', '2026-09-29', false, true, null),
  (6163, 6, 15, 'BE', 'Umstellung auf reine Sachleistungen', '{601}', 6113, 1, 3, null, 'Bezahlkarte und Sachleistungen sollen Anreize senken und Auszahlungen vereinfachen; eine Wirkung auf die Zahl der Neuankommenden ist nicht belegt, an Unterkünften und Ausländerbehörden ändert sich nichts. Die Länder können sie im Rahmen des Asylbewerberleistungsgesetzes selbst einführen.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=23', null, 'offen', '2026-09-29', false, true, null),
  (6164, 6, 15, 'BE', 'Freie Plätze in bestehenden Unterkünften voll belegen; zentrale Unterbringung von Personen mit geringen Anerkennungschancen', '{601}', 6114, 1, 2, null, 'Zentrale Unterbringung, etwa bis zum Asylbescheid, entlastet die Kommunen, verlagert den Bedarf an Plätzen aber auf das Land; ob Verfahren und Rückführungen dadurch schneller werden, ist kaum untersucht. Das Land schafft die Plätze, die Wohnpflicht regelt der Bund.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=23', null, 'offen', '2026-09-29', false, true, null),
  (6165, 6, 16, 'BE', 'Bezirke verpflichten, Flächen für Gemeinschaftsunterkünfte bereitzustellen; leer stehende Gebäude aktivieren', '{601}', 6121, 2, 2, null, 'Verbindliche Vorgaben für Standorte und die Nutzung leer stehender Gebäude setzen direkt an fehlenden Unterkünften an; Planung und Umbau dauern aber, und gegen einzelne Standorte gibt es oft Widerstand vor Ort. Umsetzbar über Landesrecht und Landeshaushalt.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=283', null, 'gemischt', '2026-09-29', false, true, null),
  (6166, 6, 16, 'BE', 'Mehr Geflüchtete über Kooperationsverträge mit landeseigenen Wohnungsbaugesellschaften in eigenen Wohnraum vermitteln', '{601}', 6118, 1, 2, null, 'Wohnungen statt Sammelunterkünften erleichtern das Ankommen und können günstiger sein; zusätzliche Plätze entstehen aber nur, wo Wohnungen frei sind, in angespannten Wohnungsmärkten konkurriert der Bedarf mit anderen Wohnungssuchenden. Das Land kann es über Aufnahmegesetz und Förderung steuern.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=283', null, 'gemischt', '2026-09-29', false, true, null),
  (6167, 6, 16, 'BE', 'Infrastrukturprämien für die Bezirke je untergebrachter Person', '{601}', 6116, 1, 2, null, 'Mehr Landesgeld, etwa als Pauschale je Platz oder Person, setzt an der Kapazitätsseite an; Geld allein schafft aber nicht sofort Unterkünfte, Kitaplätze oder Personal, und die Programme nennen meist keinen Umfang. Umsetzbar über den Landeshaushalt.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=283', null, 'gemischt', '2026-09-29', false, true, null),
  (6168, 6, 16, 'BE', 'Vom Bund eine Personenpauschale für die Unterbringungskosten fordern', '{601}', 6122, 1, 1, null, 'Eine volle Kostenübernahme durch den Bund würde Länder und Kommunen finanziell entlasten, schafft aber nicht sofort Plätze; ein Land kann sie nur fordern, entscheiden müssen Bundesregierung und Bundestag.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=285', null, 'gemischt', '2026-09-29', false, true, null),
  (6169, 6, 17, 'BE', 'Grenzkontrollen und Zurückweisungen an den deutschen Grenzen unterstützen', '{601}', 6117, 1, 1, null, 'Grenzkontrollen, Zurückweisungen, Familiennachzug oder Asylverfahren an den EU-Außengrenzen kann ein Land nicht selbst regeln, sondern nur über den Bundesrat oder beim Bund darauf hinwirken; die Wirkung solcher Maßnahmen auf die Zugangszahlen ist zudem umstritten.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=35', null, 'gemischt', '2026-09-29', false, true, null),
  (6170, 6, 17, 'BE', 'Asylbewerber stärker auf die umliegenden Bundesländer verteilen', '{601}', null, 1, 1, null, 'Eine andere Verteilung zwischen den Ländern würde Berlin entlasten, verschiebt den Bedarf aber nur; den Verteilschlüssel (Königsteiner Schlüssel) legen Bund und Länder gemeinsam fest, Berlin kann ihn nicht allein ändern.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=35', null, 'offen', '2026-09-29', false, true, null),
  (6171, 6, 17, 'BE', 'Bezirke, die bisher am meisten geleistet haben, bei der Verteilung entlasten', '{601}', 6119, 1, 3, null, 'Verteilung nach Leistungsfähigkeit oder Zuzugssperren für überlastete Orte (§ 12a Aufenthaltsgesetz) entlasten einzelne Kommunen, verschieben den Bedarf aber nur im Land; Wohnsitzauflagen können laut Studien die Arbeitsaufnahme verzögern. Das Land kann es selbst regeln.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=35', null, 'gemischt', '2026-09-29', false, true, null),
  (6172, 6, 17, 'BE', 'Ansiedlung mit einem Infrastrukturzuschuss für den Bezirk verbinden', '{601}', 6116, 1, 2, null, 'Mehr Landesgeld, etwa als Pauschale je Platz oder Person, setzt an der Kapazitätsseite an; Geld allein schafft aber nicht sofort Unterkünfte, Kitaplätze oder Personal, und die Programme nennen meist keinen Umfang. Umsetzbar über den Landeshaushalt.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=35', null, 'gemischt', '2026-09-29', false, true, null),
  (6183, 7, 11, null, 'Aktivrente: Arbeitslohn nach Erreichen der Regelaltersgrenze bis 2.000 Euro im Monat steuerfrei', '{701}', 6174, 1, 3, null, 'Mehr Weiterarbeit im Rentenalter bringt der Rentenversicherung etwas mehr Beiträge und Steuern; Studien erwarten nur kleine Beschäftigungseffekte, Steuerfreiheit kostet Einnahmen. Per Bundesgesetz umsetzbar.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=35', null, 'gemischt', '2026-09-29', false, true, null),
  (6184, 7, 11, null, 'Kleine und mittlere Arbeitgeber beim Abschluss von Betriebsrenten unterstützen', '{703}', 6177, 2, 3, null, 'Setzt direkt an der geringen Verbreitung von Betriebsrenten an; mehr Förderung und weniger Haftungsrisiken haben die Verbreitung bisher aber nur langsam erhöht, vor allem in kleinen Betrieben und bei Geringverdienenden. Per Bundesgesetz umsetzbar.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=35', null, 'gemischt', '2026-09-29', false, true, null),
  (6185, 7, 11, null, 'Frühstart-Rente: 10 Euro im Monat vom 6. bis 18. Lebensjahr in ein kapitalgedecktes Altersvorsorgedepot', '{703}', null, 1, 3, null, '10 Euro im Monat ergeben bis zum Rentenalter nur einen kleinen Zusatzbetrag, und die Wirkung setzt erst in Jahrzehnten ein; das Depot kann aber den Einstieg in eigene Vorsorge erleichtern. Per Bundesgesetz umsetzbar, die Kosten sind überschaubar.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=35', null, 'gemischt', '2026-09-29', false, true, null),
  (6186, 7, 11, null, 'Verbindliche Altersvorsorge für nicht ausreichend abgesicherte Selbstständige', '{702}', 6175, 2, 3, null, 'Viele Solo-Selbstständige sorgen kaum vor und sind im Alter häufiger arm; eine Vorsorgepflicht setzt direkt an dieser Lücke an, wirkt aber erst über Jahrzehnte, und Pflichtbeiträge belasten Selbstständige mit geringem Einkommen. Per Bundesgesetz umsetzbar.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=35', null, 'gemischt', '2026-09-29', false, true, null),
  (6187, 7, 12, null, 'Rentenniveau dauerhaft bei mindestens 48 Prozent sichern', '{701}', 6173, 1, 2, null, 'Eine Haltelinie verhindert, dass die Renten wegen des steigenden Verhältnisses von Rentnern zu Beitragszahlenden hinter den Löhnen zurückfallen; das Missverhältnis bleibt, die Kosten steigen über Beiträge oder Steuerzuschüsse. Per Bundesgesetz umsetzbar, die dauerhafte Finanzierung ist offen.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=25', null, 'gemischt', '2026-09-29', false, true, null),
  (6188, 7, 12, null, 'Weiterarbeit nach Rentenbeginn: Arbeitgeberbeiträge an die Beschäftigten auszahlen', '{701}', 6174, 1, 3, null, 'Mehr Weiterarbeit im Rentenalter bringt der Rentenversicherung etwas mehr Beiträge und Steuern; Studien erwarten nur kleine Beschäftigungseffekte, Steuerfreiheit kostet Einnahmen. Per Bundesgesetz umsetzbar.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=25', null, 'gemischt', '2026-09-29', false, true, null),
  (6189, 7, 12, null, 'Langfristig alle Erwerbstätigen in die gesetzliche Rente einbeziehen', '{701}', 6176, 1, 2, null, 'Mehr Einzahlende verbessern das Verhältnis zu den Rentnern zunächst, später entstehen aus den Beiträgen aber auch Ansprüche; für Beamte kostet der Übergang Bund und Länder anfangs viel Geld. Per Bundesgesetz möglich, mit langen Übergangszeiten.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=25', null, 'gemischt', '2026-09-29', false, true, null),
  (6190, 7, 12, null, 'Zunächst alle Selbstständigen absichern', '{702}', 6175, 2, 3, null, 'Viele Solo-Selbstständige sorgen kaum vor und sind im Alter häufiger arm; eine Vorsorgepflicht setzt direkt an dieser Lücke an, wirkt aber erst über Jahrzehnte, und Pflichtbeiträge belasten Selbstständige mit geringem Einkommen. Per Bundesgesetz umsetzbar.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=25', null, 'gemischt', '2026-09-29', false, true, null),
  (6191, 7, 12, null, 'Steuerliche Förderung der Betriebsrente für Geringverdiener ausbauen', '{703}', 6177, 2, 3, null, 'Setzt direkt an der geringen Verbreitung von Betriebsrenten an; mehr Förderung und weniger Haftungsrisiken haben die Verbreitung bisher aber nur langsam erhöht, vor allem in kleinen Betrieben und bei Geringverdienenden. Per Bundesgesetz umsetzbar.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=25', null, 'gemischt', '2026-09-29', false, true, null),
  (6192, 7, 12, null, 'Förderung privater Vorsorge nur für Produkte mit gedeckelten Kosten, konzentriert auf kleine und mittlere Einkommen', '{703}', 6178, 2, 3, null, 'Kostengünstige, einfache Produkte und eine Förderung für kleine und mittlere Einkommen setzen an der Lücke bei der Zusatzvorsorge an; ob deutlich mehr Menschen vorsorgen, ist offen, solange die Teilnahme freiwillig bleibt. Per Bundesgesetz umsetzbar.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=25', null, 'gemischt', '2026-09-29', false, true, null),
  (6193, 7, 12, null, 'Mindestlohn spätestens 2026 auf 15 Euro', '{702}', 6181, 1, 3, null, 'Ein höherer Mindestlohn erhöht die Rentenansprüche von Geringverdienenden; auch mit 15 Euro liegt die Rente nach Lücken im Erwerbsleben oft nahe der Grundsicherung. Per Bundesgesetz umsetzbar, bisher entscheidet die Mindestlohnkommission.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=23', null, 'gemischt', '2026-09-29', false, true, null),
  (6194, 7, 13, null, 'Rentenniveau bei mindestens 48 Prozent halten', '{701}', 6173, 1, 2, null, 'Eine Haltelinie verhindert, dass die Renten wegen des steigenden Verhältnisses von Rentnern zu Beitragszahlenden hinter den Löhnen zurückfallen; das Missverhältnis bleibt, die Kosten steigen über Beiträge oder Steuerzuschüsse. Per Bundesgesetz umsetzbar, die dauerhafte Finanzierung ist offen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=97', null, 'gemischt', '2026-09-29', false, true, null),
  (6195, 7, 13, null, 'Grundrente zu einer Garantierente nach 30 Versicherungsjahren weiterentwickeln', '{702}', 6180, 2, 2, null, 'Eine stärkere Aufwertung niedriger Ansprüche setzt direkt an niedrigen Renten nach niedrigen Löhnen an; wer große Lücken im Erwerbsleben hat, profitiert oft nicht, die Kosten steigen. Per Bundesgesetz umsetzbar, die Finanzierung ist nicht geklärt.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=97', null, 'gemischt', '2026-09-29', false, true, null),
  (6196, 7, 13, null, 'Mehr Beitragszahlende durch höhere Erwerbstätigkeit von Frauen und qualifizierte Zuwanderung', '{701}', null, 2, 2, null, 'Eine höhere Erwerbstätigkeit, vor allem von Frauen, und Zuwanderung in Arbeit gelten in Studien als wichtigste Hebel gegen das sinkende Verhältnis von Beitragszahlenden zu Rentnern; das Programm nennt aber keine Größenordnung. Kitaausbau und Integration brauchen Länder, Kommunen und Zeit.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=97', null, 'belegt', '2026-09-29', false, true, null),
  (6197, 7, 13, null, 'Mindestlohn erneut anheben, Minijobs abbauen', '{702}', 6181, 1, 3, null, 'Ein höherer Mindestlohn erhöht die Rentenansprüche von Geringverdienenden; auch mit 15 Euro liegt die Rente nach Lücken im Erwerbsleben oft nahe der Grundsicherung. Per Bundesgesetz umsetzbar, bisher entscheidet die Mindestlohnkommission.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=98', null, 'gemischt', '2026-09-29', false, true, null),
  (6198, 7, 13, null, 'Gesetzliche Rente zur Bürgerversicherung: Abgeordnete und perspektivisch Beamte einbeziehen', '{701}', 6176, 1, 2, null, 'Mehr Einzahlende verbessern das Verhältnis zu den Rentnern zunächst, später entstehen aus den Beiträgen aber auch Ansprüche; für Beamte kostet der Übergang Bund und Länder anfangs viel Geld. Per Bundesgesetz möglich, mit langen Übergangszeiten.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=98', null, 'gemischt', '2026-09-29', false, true, null),
  (6199, 7, 13, null, 'Nicht anderweitig abgesicherte Selbstständige einbeziehen', '{702}', 6175, 2, 3, null, 'Viele Solo-Selbstständige sorgen kaum vor und sind im Alter häufiger arm; eine Vorsorgepflicht setzt direkt an dieser Lücke an, wirkt aber erst über Jahrzehnte, und Pflichtbeiträge belasten Selbstständige mit geringem Einkommen. Per Bundesgesetz umsetzbar.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=98', null, 'gemischt', '2026-09-29', false, true, null),
  (6200, 7, 13, null, 'Weiterarbeit neben dem Rentenbezug: Arbeitgeberbeiträge an die Beschäftigten auszahlen', '{701}', 6174, 1, 3, null, 'Mehr Weiterarbeit im Rentenalter bringt der Rentenversicherung etwas mehr Beiträge und Steuern; Studien erwarten nur kleine Beschäftigungseffekte, Steuerfreiheit kostet Einnahmen. Per Bundesgesetz umsetzbar.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=98', null, 'gemischt', '2026-09-29', false, true, null),
  (6201, 7, 13, null, 'Ergänzende Kapitaldeckung in der gesetzlichen Rente aus Bundesmitteln (Bürger*innenfonds)', '{701}', 6179, 1, 2, null, 'Ein Fonds kann den Beitragsanstieg dämpfen, wenn weniger Beitragszahlende auf mehr Rentner kommen; bei den vorgeschlagenen Größenordnungen ist der Effekt klein, die Erträge sind unsicher. Per Bundesgesetz umsetzbar, bei Kreditfinanzierung mit Haushaltsrisiken.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=98', null, 'gemischt', '2026-09-29', false, true, null),
  (6202, 7, 13, null, 'Öffentlich verwalteter Bürger*innenfonds für die private Vorsorge mit Widerspruchslösung', '{703}', null, 2, 2, null, 'Automatische Teilnahme mit Widerspruchsrecht hat in Großbritannien und Neuseeland die Beteiligung an Zusatzvorsorge stark erhöht; wie hoch die Zusatzrente wird, hängt von den Beiträgen ab. Der öffentliche Fonds muss erst aufgebaut werden.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=98', null, 'belegt', '2026-09-29', false, true, null),
  (6203, 7, 13, null, 'Bürger*innenfonds auch für Betriebsrenten öffnen, vor allem für kleine und mittlere Unternehmen', '{703}', 6177, 2, 3, null, 'Setzt direkt an der geringen Verbreitung von Betriebsrenten an; mehr Förderung und weniger Haftungsrisiken haben die Verbreitung bisher aber nur langsam erhöht, vor allem in kleinen Betrieben und bei Geringverdienenden. Per Bundesgesetz umsetzbar.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=99', null, 'gemischt', '2026-09-29', false, true, null),
  (6204, 7, 14, null, 'Flexibler Renteneintritt nach schwedischem Vorbild mit Zu- und Abschlägen', '{701}', null, 1, 3, null, 'Ein flexibler Renteneintritt mit fairen Zu- und Abschlägen kann längeres Arbeiten attraktiver machen; wie viele dadurch später in Rente gehen, ist unsicher, wer früher geht, bekommt weniger. Per Bundesgesetz umsetzbar.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=21', null, 'gemischt', '2026-09-29', false, true, null),
  (6205, 7, 14, null, 'Gesetzliche Aktienrente: kleiner Teil der Rentenbeiträge in einen unabhängig verwalteten Fonds', '{701}', 6179, 1, 2, null, 'Ein Fonds kann den Beitragsanstieg dämpfen, wenn weniger Beitragszahlende auf mehr Rentner kommen; bei den vorgeschlagenen Größenordnungen ist der Effekt klein, die Erträge sind unsicher. Per Bundesgesetz umsetzbar, bei Kreditfinanzierung mit Haushaltsrisiken.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=21', null, 'gemischt', '2026-09-29', false, true, null),
  (6206, 7, 14, null, 'Steuerlich gefördertes Altersvorsorgedepot für die private Vorsorge', '{703}', 6178, 2, 3, null, 'Kostengünstige, einfache Produkte und eine Förderung für kleine und mittlere Einkommen setzen an der Lücke bei der Zusatzvorsorge an; ob deutlich mehr Menschen vorsorgen, ist offen, solange die Teilnahme freiwillig bleibt. Per Bundesgesetz umsetzbar.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=21', null, 'gemischt', '2026-09-29', false, true, null),
  (6207, 7, 14, null, 'Reine Beitragszusage allen Betrieben ermöglichen, vor allem Kleinstbetrieben', '{703}', 6177, 2, 3, null, 'Setzt direkt an der geringen Verbreitung von Betriebsrenten an; mehr Förderung und weniger Haftungsrisiken haben die Verbreitung bisher aber nur langsam erhöht, vor allem in kleinen Betrieben und bei Geringverdienenden. Per Bundesgesetz umsetzbar.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=21', null, 'gemischt', '2026-09-29', false, true, null),
  (6208, 7, 15, null, 'Verbeamtung nur für Hoheitsaufgaben, Politiker in die gesetzliche Rente', '{701}', 6176, 1, 2, null, 'Mehr Einzahlende verbessern das Verhältnis zu den Rentnern zunächst, später entstehen aus den Beiträgen aber auch Ansprüche; für Beamte kostet der Übergang Bund und Länder anfangs viel Geld. Per Bundesgesetz möglich, mit langen Übergangszeiten.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=19', null, 'gemischt', '2026-09-29', false, true, null),
  (6209, 7, 15, null, 'Alle nicht beitragsgedeckten Leistungen aus dem Bundeshaushalt finanzieren', '{701}', 6182, 1, 1, null, 'Verlagert Kosten von den Beitragszahlenden auf die Steuerzahlenden und entlastet die Beiträge; am Verhältnis von Beitragszahlenden zu Rentnern ändert es nichts. Es geht um zweistellige Milliardenbeträge im Jahr, deren Finanzierung offen ist.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=19', null, 'gemischt', '2026-09-29', false, true, null),
  (6210, 7, 15, null, 'Elternschaft in der Rente höher bewerten', '{702}', null, 1, 2, null, 'Höhere Rentenansprüche für Eltern gleichen Lücken im Erwerbsleben durch Kindererziehung teilweise aus; das Programm nennt weder Umfang noch Finanzierung. Per Bundesgesetz umsetzbar, zuletzt bei der Mütterrente mit hohen Kosten.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=20', null, 'gemischt', '2026-09-29', false, true, null),
  (6211, 7, 15, null, 'Private und betriebliche Vorsorge mit Aktien, ETFs und Fonds systematisch steuerlich fördern', '{703}', 6178, 2, 3, null, 'Kostengünstige, einfache Produkte und eine Förderung für kleine und mittlere Einkommen setzen an der Lücke bei der Zusatzvorsorge an; ob deutlich mehr Menschen vorsorgen, ist offen, solange die Teilnahme freiwillig bleibt. Per Bundesgesetz umsetzbar.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=20', null, 'gemischt', '2026-09-29', false, true, null),
  (6212, 7, 15, null, 'Junior-Spardepot: 100 Euro im Monat aus Steuermitteln bis zum 18. Lebensjahr für jedes Kind mit deutscher Staatsangehörigkeit', '{703}', null, 2, 1, null, '100 Euro im Monat über 18 Jahre ergeben einen spürbaren Kapitalstock für das Alter; die Kosten von grob 15 Milliarden Euro im Jahr sind nicht gegenfinanziert, und die Beschränkung auf deutsche Kinder ist verfassungsrechtlich fraglich.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=20', null, 'offen', '2026-09-29', false, true, null),
  (6213, 7, 15, null, 'Zusätzlicher Steuerfreibetrag von 12.000 Euro für arbeitende Rentner', '{701}', 6174, 1, 3, null, 'Mehr Weiterarbeit im Rentenalter bringt der Rentenversicherung etwas mehr Beiträge und Steuern; Studien erwarten nur kleine Beschäftigungseffekte, Steuerfreiheit kostet Einnahmen. Per Bundesgesetz umsetzbar.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=21', null, 'gemischt', '2026-09-29', false, true, null),
  (6214, 7, 15, null, 'Mehr Erwerbsanreize durch niedrigere Einkommensteuern und ein weniger attraktives Bürgergeld', '{701}', null, 1, 2, null, 'Stärkere Arbeitsanreize können die Zahl der Beitragszahlenden etwas erhöhen; wie stark Steuersenkungen und Kürzungen beim Bürgergeld die Beschäftigung steigern, ist in der Forschung umstritten. Steuersenkungen sind nicht gegenfinanziert.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=21', null, 'gemischt', '2026-09-29', false, true, null),
  (6215, 7, 15, null, 'Willkommensprämie von 20.000 Euro für jedes neugeborene Kind', '{701}', null, 1, 1, null, 'Mehr Geburten würden das Verhältnis von Beitragszahlenden zu Rentnern erst nach rund zwei Jahrzehnten verbessern; ob Geldprämien die Geburtenrate dauerhaft erhöhen, ist umstritten. Die Kosten von rund 13 Milliarden Euro im Jahr sind nicht gegenfinanziert.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=21', null, 'gemischt', '2026-09-29', false, true, null),
  (6216, 7, 16, null, 'Solidarische Erwerbstätigenversicherung für alle mit Erwerbseinkommen', '{701}', 6176, 1, 2, null, 'Mehr Einzahlende verbessern das Verhältnis zu den Rentnern zunächst, später entstehen aus den Beiträgen aber auch Ansprüche; für Beamte kostet der Übergang Bund und Länder anfangs viel Geld. Per Bundesgesetz möglich, mit langen Übergangszeiten.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=15', null, 'gemischt', '2026-09-29', false, true, null),
  (6217, 7, 16, null, 'Rentenniveau auf 53 Prozent anheben', '{701}', null, 1, 1, null, 'Ein höheres Rentenniveau erhöht die Renten aller, gleicht aber nur die Folgen des steigenden Verhältnisses von Rentnern zu Beitragszahlenden aus; die Mehrkosten von jährlich deutlich über 30 Milliarden Euro sind nicht geklärt.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=15', null, 'gemischt', '2026-09-29', false, true, null),
  (6218, 7, 16, null, 'Niedrige Rentenansprüche von Geringverdienenden, Erwerbslosen, Erziehenden und Pflegenden aufwerten', '{702}', 6180, 2, 2, null, 'Eine stärkere Aufwertung niedriger Ansprüche setzt direkt an niedrigen Renten nach niedrigen Löhnen an; wer große Lücken im Erwerbsleben hat, profitiert oft nicht, die Kosten steigen. Per Bundesgesetz umsetzbar, die Finanzierung ist nicht geklärt.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=15', null, 'gemischt', '2026-09-29', false, true, null),
  (6219, 7, 16, null, 'Versicherungsfremde Leistungen nicht mehr aus Beiträgen finanzieren', '{701}', 6182, 1, 1, null, 'Verlagert Kosten von den Beitragszahlenden auf die Steuerzahlenden und entlastet die Beiträge; am Verhältnis von Beitragszahlenden zu Rentnern ändert es nichts. Es geht um zweistellige Milliardenbeträge im Jahr, deren Finanzierung offen ist.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=15', null, 'gemischt', '2026-09-29', false, true, null),
  (6220, 7, 16, null, 'Solidarische Mindestrente bis zur Armutsrisikogrenze (rund 1.400 Euro)', '{702}', null, 2, 1, null, 'Ein Zuschlag bis zur Armutsrisikogrenze beseitigt Altersarmut nach niedrigen Löhnen und Lücken direkt, setzt aber nicht an den Löhnen selbst an und kann den Anreiz zu eigener Vorsorge schwächen. Die Kosten wären hoch, die Finanzierung ist offen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=15', null, 'gemischt', '2026-09-29', false, true, null),
  (6221, 7, 16, null, 'Betriebsrenten mindestens zur Hälfte durch die Arbeitgeber finanzieren', '{703}', null, 1, 3, null, 'Ein Pflichtanteil der Arbeitgeber erhöht die Leistungen bestehender Betriebsrenten, bringt aber nicht mehr Betriebe dazu, überhaupt eine anzubieten, und könnte kleine Betriebe eher abschrecken. Per Bundesgesetz umsetzbar.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=15', null, 'gemischt', '2026-09-29', false, true, null),
  (6222, 7, 16, null, 'Mindestlohn von mindestens 15 Euro, ab 2026 16 Euro', '{702}', 6181, 1, 3, null, 'Ein höherer Mindestlohn erhöht die Rentenansprüche von Geringverdienenden; auch mit 15 Euro liegt die Rente nach Lücken im Erwerbsleben oft nahe der Grundsicherung. Per Bundesgesetz umsetzbar, bisher entscheidet die Mindestlohnkommission.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=15', null, 'gemischt', '2026-09-29', false, true, null),
  (6236, 10, 11, null, 'Pflegezusatzversicherungen steuerlich besser absetzbar machen (Prüfauftrag)', '{1002}', 6225, 1, 3, null, 'Zusatzversicherungen können künftige Eigenanteile abdecken; bisher haben nur wenige eine, Geringverdienende und heute Pflegebedürftige erreicht die Förderung kaum. Per Bundesgesetz umsetzbar.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=71', null, 'gemischt', '2026-09-29', false, true, null),
  (6237, 10, 11, null, 'Pflegebudget, das flexibel für pflegerische Leistungen eingesetzt werden kann', '{1004}', 6226, 2, 3, null, 'Setzt daran an, dass Entlastungsleistungen wenig genutzt werden, weil sie kompliziert und starr sind; ob ein Budget die Nutzung deutlich erhöht, ist noch wenig untersucht. Per Bundesgesetz umsetzbar, erste Schritte gibt es seit 2025.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=71', null, 'gemischt', '2026-09-29', false, true, null),
  (6238, 10, 11, null, 'Pflegebedürftigkeit durch Prävention und Reha aufschieben', '{1003}', 6234, 1, 3, null, 'Prävention und Rehabilitation können Pflegebedürftigkeit bei Einzelnen verzögern; an der Alterung der Bevölkerung ändern sie nichts, und ihre Wirkung auf die Zahl der Pflegebedürftigen ist schwer zu belegen. Per Bundesgesetz umsetzbar.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=72', null, 'gemischt', '2026-09-29', false, true, null),
  (6239, 10, 11, null, 'Planbare Einsatzzeiten, Springerpools, Aufstiegsmöglichkeiten', '{1001}', 6229, 2, 2, null, 'Bessere Arbeitsbedingungen setzen am wichtigsten Grund an, warum Pflegekräfte den Beruf verlassen oder in Teilzeit gehen; eine verbindliche Personalbemessung braucht aber zunächst mehr Personal. Per Bundesgesetz umsetzbar, die Umsetzung dauert Jahre.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=72', null, 'gemischt', '2026-09-29', false, true, null),
  (6240, 10, 11, null, 'Pflegekräfte im Ausland anwerben', '{1001}', 6231, 2, 2, null, 'Zuwanderung hat einen großen Teil des Beschäftigungszuwachses in der Pflege getragen; lange Anerkennungsverfahren und Sprachhürden bremsen, und die Anerkennung liegt bei den Ländern. Der Bund kann Verfahren vereinfachen und Anwerbung fördern.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=72', null, 'gemischt', '2026-09-29', false, true, null),
  (6241, 10, 11, null, 'Rolle der Pflegefachpersonen stärken, Dokumentation vereinfachen', '{1001}', 6232, 1, 3, null, 'Mehr Verantwortung und Aufstiegsmöglichkeiten machen den Beruf attraktiver; wie stark das die Zahl der Pflegekräfte erhöht, ist kaum belegt. Per Bundesgesetz umsetzbar, erste Schritte wurden 2025 beschlossen.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=72', null, 'gemischt', '2026-09-29', false, true, null),
  (6242, 10, 12, null, 'Pflegekosten-Deckel: Eigenanteile in der stationären Pflege auf 1.000 Euro im Monat begrenzen', '{1002}', null, 2, 2, null, 'Ein Deckel senkt die pflegebedingten Eigenanteile direkt und für alle Heimbewohner; Unterkunft, Verpflegung und Investitionskosten bleiben aber, und die Mehrkosten von mehreren Milliarden Euro im Jahr müssen über Beiträge oder Steuern finanziert werden.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=31', null, 'gemischt', '2026-09-29', false, true, null),
  (6243, 10, 12, null, 'Investitionskosten der Heime nicht mehr vollständig auf die Bewohner umlegen', '{1005}', 6223, 2, 1, null, 'Die Investitionskosten machen einen spürbaren Teil der Eigenanteile im Heim aus; übernehmen die Länder sie, sinkt die Belastung direkt. Der Bund kann es vorschreiben, zahlen müssten aber die Länder, deren Finanzierung offen ist.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=31', null, 'gemischt', '2026-09-29', false, true, null),
  (6244, 10, 12, null, 'Private Pflegeversicherungen in den Risikostrukturausgleich einbeziehen', '{1002}', 6224, 1, 2, null, 'Ein Ausgleich zwischen sozialer und privater Pflegeversicherung verbreitert die Finanzierung und kann Beiträge oder Eigenanteile entlasten; wie viel davon bei den Eigenanteilen ankommt, hängt von der Verwendung ab. Verfassungsrechtlich umstritten, aber per Bundesgesetz möglich.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=31', null, 'gemischt', '2026-09-29', false, true, null),
  (6245, 10, 12, null, 'Familienpflegezeit und Familienpflegegeld analog zum Elterngeld', '{1004}', 6227, 2, 2, null, 'Ein Lohnersatz ähnlich dem Elterngeld entlastet pflegende Angehörige finanziell und erleichtert, Beruf und Pflege zu verbinden; die Kosten sind je nach Ausgestaltung hoch, und ob mehr Angehörige die Leistung nutzen als die bisherige Pflegezeit, ist offen.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=31', null, 'gemischt', '2026-09-29', false, true, null),
  (6246, 10, 12, null, 'Beratung und Anlaufstellen, Tages- und Nachtpflege ausbauen', '{1004}', 6228, 2, 2, null, 'Mehr erreichbare Entlastungsangebote und Beratung setzen daran an, dass Angehörige die Hauptlast tragen; die Plätze fehlen aber oft auch wegen fehlender Pflegekräfte. Der Bund kann Leistungen und Förderung erhöhen, Planung und Bau liegen bei Ländern und Trägern.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=31', null, 'gemischt', '2026-09-29', false, true, null),
  (6247, 10, 12, null, 'Bundeseinheitliche bedarfsgerechte Personalausstattung', '{1001}', 6229, 2, 2, null, 'Bessere Arbeitsbedingungen setzen am wichtigsten Grund an, warum Pflegekräfte den Beruf verlassen oder in Teilzeit gehen; eine verbindliche Personalbemessung braucht aber zunächst mehr Personal. Per Bundesgesetz umsetzbar, die Umsetzung dauert Jahre.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=32', null, 'gemischt', '2026-09-29', false, true, null),
  (6248, 10, 12, null, 'Tarifgebundene Gehälter refinanzieren', '{1001}', 6233, 2, 2, null, 'Höhere Löhne machen den Beruf attraktiver und halten Pflegekräfte; seit der Tarifpflicht von 2022 sind die Löhne deutlich gestiegen, was aber auch die Eigenanteile erhöht hat. Die Refinanzierung ist per Bundesgesetz möglich, die Finanzierung ist offen.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=32', null, 'gemischt', '2026-09-29', false, true, null),
  (6249, 10, 12, null, 'Befugnisse von Pflegefachpersonen erweitern', '{1001}', 6232, 1, 3, null, 'Mehr Verantwortung und Aufstiegsmöglichkeiten machen den Beruf attraktiver; wie stark das die Zahl der Pflegekräfte erhöht, ist kaum belegt. Per Bundesgesetz umsetzbar, erste Schritte wurden 2025 beschlossen.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=32', null, 'gemischt', '2026-09-29', false, true, null),
  (6250, 10, 12, null, 'Weltweite Anwerbung und Integration von Fachkräften ausbauen', '{1001}', 6231, 2, 2, null, 'Zuwanderung hat einen großen Teil des Beschäftigungszuwachses in der Pflege getragen; lange Anerkennungsverfahren und Sprachhürden bremsen, und die Anerkennung liegt bei den Ländern. Der Bund kann Verfahren vereinfachen und Anwerbung fördern.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=32', null, 'gemischt', '2026-09-29', false, true, null),
  (6251, 10, 12, null, 'Praxisnahe und kostenfreie Ausbildung in den Gesundheitsfachberufen', '{1001}', 6235, 1, 3, null, 'Bessere Ausbildungsbedingungen können mehr Menschen in den Beruf bringen und Abbrüche verringern; die Ausbildung ist seit 2020 bereits vergütet und schulgeldfrei, weitere Effekte sind schwer abzuschätzen. Per Bundesgesetz und mit den Ländern umsetzbar.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=32', null, 'gemischt', '2026-09-29', false, true, null),
  (6252, 10, 13, null, 'Angebote im Quartier fördern, um Pflegebedürftigkeit hinauszuzögern', '{1003}', 6234, 1, 3, null, 'Prävention und Rehabilitation können Pflegebedürftigkeit bei Einzelnen verzögern; an der Alterung der Bevölkerung ändern sie nichts, und ihre Wirkung auf die Zahl der Pflegebedürftigen ist schwer zu belegen. Per Bundesgesetz umsetzbar.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=91', null, 'gemischt', '2026-09-29', false, true, null),
  (6253, 10, 13, null, 'Zeitlich begrenzter Lohnersatz und Rentenbeiträge für Angehörige, die für die Pflege Arbeitszeit reduzieren', '{1004}', 6227, 2, 2, null, 'Ein Lohnersatz ähnlich dem Elterngeld entlastet pflegende Angehörige finanziell und erleichtert, Beruf und Pflege zu verbinden; die Kosten sind je nach Ausgestaltung hoch, und ob mehr Angehörige die Leistung nutzen als die bisherige Pflegezeit, ist offen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=92', null, 'gemischt', '2026-09-29', false, true, null),
  (6254, 10, 13, null, 'Tages- und Kurzzeitpflege stärken und ausbauen', '{1004}', 6228, 2, 2, null, 'Mehr erreichbare Entlastungsangebote und Beratung setzen daran an, dass Angehörige die Hauptlast tragen; die Plätze fehlen aber oft auch wegen fehlender Pflegekräfte. Der Bund kann Leistungen und Förderung erhöhen, Planung und Bau liegen bei Ländern und Trägern.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=92', null, 'gemischt', '2026-09-29', false, true, null),
  (6255, 10, 13, null, 'Leistungen flexibel kombinieren, etwa über ein Pflegebudget', '{1004}', 6226, 2, 3, null, 'Setzt daran an, dass Entlastungsleistungen wenig genutzt werden, weil sie kompliziert und starr sind; ob ein Budget die Nutzung deutlich erhöht, ist noch wenig untersucht. Per Bundesgesetz umsetzbar, erste Schritte gibt es seit 2025.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=92', null, 'gemischt', '2026-09-29', false, true, null),
  (6256, 10, 13, null, 'Rückkehroffensive für ausgestiegene Pflegekräfte', '{1001}', 6230, 2, 2, null, 'Befragungen zeigen, dass viele ehemalige Pflegekräfte bei besseren Bedingungen zurückkehren würden; wie viele es tatsächlich tun, hängt davon ab, ob sich die Bedingungen spürbar ändern. Ohne eigene Maßnahmen bleibt es ein Ziel.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=92', null, 'gemischt', '2026-09-29', false, true, null),
  (6257, 10, 13, null, 'Höhere Personalschlüssel', '{1001}', 6229, 2, 2, null, 'Bessere Arbeitsbedingungen setzen am wichtigsten Grund an, warum Pflegekräfte den Beruf verlassen oder in Teilzeit gehen; eine verbindliche Personalbemessung braucht aber zunächst mehr Personal. Per Bundesgesetz umsetzbar, die Umsetzung dauert Jahre.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=92', null, 'gemischt', '2026-09-29', false, true, null),
  (6258, 10, 13, null, 'Mehr Kompetenzen und Aufstiegschancen für den Pflegeberuf', '{1001}', 6232, 1, 3, null, 'Mehr Verantwortung und Aufstiegsmöglichkeiten machen den Beruf attraktiver; wie stark das die Zahl der Pflegekräfte erhöht, ist kaum belegt. Per Bundesgesetz umsetzbar, erste Schritte wurden 2025 beschlossen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=92', null, 'gemischt', '2026-09-29', false, true, null),
  (6259, 10, 13, null, 'Ausbildungsbedingungen verbessern, Pflegeassistenz bundesweit einheitlich regeln', '{1001}', 6235, 1, 3, null, 'Bessere Ausbildungsbedingungen können mehr Menschen in den Beruf bringen und Abbrüche verringern; die Ausbildung ist seit 2020 bereits vergütet und schulgeldfrei, weitere Effekte sind schwer abzuschätzen. Per Bundesgesetz und mit den Ländern umsetzbar.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=92', null, 'gemischt', '2026-09-29', false, true, null),
  (6260, 10, 13, null, 'Ausgleich zwischen gesetzlicher und privater Pflegeversicherung auf dem Weg zur Pflegebürgerversicherung', '{1002}', 6224, 1, 2, null, 'Ein Ausgleich zwischen sozialer und privater Pflegeversicherung verbreitert die Finanzierung und kann Beiträge oder Eigenanteile entlasten; wie viel davon bei den Eigenanteilen ankommt, hängt von der Verwendung ab. Verfassungsrechtlich umstritten, aber per Bundesgesetz möglich.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=94', null, 'gemischt', '2026-09-29', false, true, null),
  (6261, 10, 14, null, 'Pflegeanbieter von doppelten Prüfungen und unnötigen Dokumentationspflichten befreien', '{1001}', 6229, 2, 2, null, 'Bessere Arbeitsbedingungen setzen am wichtigsten Grund an, warum Pflegekräfte den Beruf verlassen oder in Teilzeit gehen; eine verbindliche Personalbemessung braucht aber zunächst mehr Personal. Per Bundesgesetz umsetzbar, die Umsetzung dauert Jahre.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=34', null, 'gemischt', '2026-09-29', false, true, null),
  (6262, 10, 14, null, 'Niedrigschwellige Beratung ausbauen, auch für pflegende Kinder und Jugendliche', '{1004}', 6228, 2, 2, null, 'Mehr erreichbare Entlastungsangebote und Beratung setzen daran an, dass Angehörige die Hauptlast tragen; die Plätze fehlen aber oft auch wegen fehlender Pflegekräfte. Der Bund kann Leistungen und Förderung erhöhen, Planung und Bau liegen bei Ländern und Trägern.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=34', null, 'gemischt', '2026-09-29', false, true, null),
  (6263, 10, 14, null, 'Mehr Pflegefachkräfte im In- und Ausland gewinnen, Anerkennung drastisch vereinfachen', '{1001}', 6231, 2, 2, null, 'Zuwanderung hat einen großen Teil des Beschäftigungszuwachses in der Pflege getragen; lange Anerkennungsverfahren und Sprachhürden bremsen, und die Anerkennung liegt bei den Ländern. Der Bund kann Verfahren vereinfachen und Anwerbung fördern.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=34', null, 'gemischt', '2026-09-29', false, true, null),
  (6264, 10, 14, null, 'Pflegepersonal durch digitale Anwendungen, Automatisierung und Robotik entlasten', '{1001}', null, 1, 3, null, 'Digitale Dokumentation und Assistenzsysteme können Pflegekräfte von Routinearbeit entlasten; wie viel Zeit das spart und ob Robotik in der Pflege breit einsetzbar ist, ist bisher kaum untersucht. Der Bund kann es fördern.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=35', null, 'offen', '2026-09-29', false, true, null),
  (6265, 10, 14, null, 'Soziale Pflegeversicherung um eine kapitalgedeckte Komponente ergänzen', '{1003}', null, 1, 2, null, 'Ein Kapitalstock kann die Beitragssätze dämpfen, wenn die Zahl der Pflegebedürftigen steigt; der bestehende Pflegevorsorgefonds ist klein, und ein neuer Kapitalstock wirkt erst langfristig. Per Bundesgesetz umsetzbar, der Aufbau braucht zusätzliche Mittel.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=35', null, 'gemischt', '2026-09-29', false, true, null),
  (6266, 10, 14, null, 'Anreize für private Pflegevorsorge, betriebliche Pflegevorsorge der Betriebsrente gleichstellen', '{1002}', 6225, 1, 3, null, 'Zusatzversicherungen können künftige Eigenanteile abdecken; bisher haben nur wenige eine, Geringverdienende und heute Pflegebedürftige erreicht die Förderung kaum. Per Bundesgesetz umsetzbar.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=35', null, 'gemischt', '2026-09-29', false, true, null),
  (6267, 10, 15, null, 'Häusliche Pflege durch Angehörige deutlich höher honorieren', '{1004}', null, 1, 2, null, 'Ein höheres Pflegegeld erkennt die Arbeit pflegender Angehöriger an und entlastet sie finanziell, verringert aber nicht ihre zeitliche und körperliche Belastung. Das Programm nennt keinen Betrag; die Mehrkosten trägt die Pflegeversicherung.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=29', null, 'gemischt', '2026-09-29', false, true, null),
  (6268, 10, 15, null, 'Ambulante und befristete stationäre Angebote für pflegende Angehörige ausweiten', '{1004}', 6228, 2, 2, null, 'Mehr erreichbare Entlastungsangebote und Beratung setzen daran an, dass Angehörige die Hauptlast tragen; die Plätze fehlen aber oft auch wegen fehlender Pflegekräfte. Der Bund kann Leistungen und Förderung erhöhen, Planung und Bau liegen bei Ländern und Trägern.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=29', null, 'gemischt', '2026-09-29', false, true, null),
  (6269, 10, 15, null, 'Ausgebildete Pflegekräfte durch bessere Bedingungen in den Beruf zurückholen', '{1001}', 6230, 2, 2, null, 'Befragungen zeigen, dass viele ehemalige Pflegekräfte bei besseren Bedingungen zurückkehren würden; wie viele es tatsächlich tun, hängt davon ab, ob sich die Bedingungen spürbar ändern. Ohne eigene Maßnahmen bleibt es ein Ziel.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=113', null, 'gemischt', '2026-09-29', false, true, null),
  (6270, 10, 16, null, 'Solidarische Pflegevollversicherung, die alle pflegerischen Leistungen abdeckt', '{1002}', null, 3, 1, null, 'Eine Vollversicherung beseitigt die pflegebedingten Eigenanteile vollständig; Unterkunft und Verpflegung bleiben. Die Mehrkosten liegen bei deutlich über 10 Milliarden Euro im Jahr, die Finanzierung über eine Bürgerversicherung ist politisch und rechtlich offen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=18', null, 'belegt', '2026-09-29', false, true, null),
  (6271, 10, 16, null, 'Bundesweite Offensive zur Rückanwerbung von Pflegekräften', '{1001}', 6230, 2, 2, null, 'Befragungen zeigen, dass viele ehemalige Pflegekräfte bei besseren Bedingungen zurückkehren würden; wie viele es tatsächlich tun, hängt davon ab, ob sich die Bedingungen spürbar ändern. Ohne eigene Maßnahmen bleibt es ein Ziel.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=18', null, 'gemischt', '2026-09-29', false, true, null),
  (6272, 10, 16, null, 'Ausbildungsoffensive', '{1001}', 6235, 1, 3, null, 'Bessere Ausbildungsbedingungen können mehr Menschen in den Beruf bringen und Abbrüche verringern; die Ausbildung ist seit 2020 bereits vergütet und schulgeldfrei, weitere Effekte sind schwer abzuschätzen. Per Bundesgesetz und mit den Ländern umsetzbar.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=18', null, 'gemischt', '2026-09-29', false, true, null),
  (6273, 10, 16, null, 'Gute Arbeitsbedingungen und Entlastung der Beschäftigten in Pflegeeinrichtungen', '{1001}', 6229, 2, 2, null, 'Bessere Arbeitsbedingungen setzen am wichtigsten Grund an, warum Pflegekräfte den Beruf verlassen oder in Teilzeit gehen; eine verbindliche Personalbemessung braucht aber zunächst mehr Personal. Per Bundesgesetz umsetzbar, die Umsetzung dauert Jahre.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=20', null, 'gemischt', '2026-09-29', false, true, null),
  (6274, 10, 16, null, 'Länder verpflichten, Investitions- und Ausbildungskosten zu übernehmen; Kosten für Unterkunft und Verpflegung deckeln', '{1002,1005}', 6223, 2, 1, null, 'Die Investitionskosten machen einen spürbaren Teil der Eigenanteile im Heim aus; übernehmen die Länder sie, sinkt die Belastung direkt. Der Bund kann es vorschreiben, zahlen müssten aber die Länder, deren Finanzierung offen ist.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=20', null, 'gemischt', '2026-09-29', false, true, null),
  (6275, 10, 16, null, 'Schonvermögen für Pflegebedürftige erhöhen', '{1002}', null, 1, 3, null, 'Ein höheres Schonvermögen schützt Erspartes, bevor die Sozialhilfe einspringt; die Eigenanteile selbst sinken dadurch nicht. Per Bundesgesetz umsetzbar, die Mehrkosten tragen die Sozialhilfeträger.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=20', null, 'gemischt', '2026-09-29', false, true, null),
  (6276, 10, 16, null, 'Lohnlücke zwischen Alten- und Krankenpflege von rund 300 Euro schließen', '{1001}', 6233, 2, 2, null, 'Höhere Löhne machen den Beruf attraktiver und halten Pflegekräfte; seit der Tarifpflicht von 2022 sind die Löhne deutlich gestiegen, was aber auch die Eigenanteile erhöht hat. Die Refinanzierung ist per Bundesgesetz möglich, die Finanzierung ist offen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=20', null, 'gemischt', '2026-09-29', false, true, null),
  (6277, 10, 16, null, 'Sechs Wochen Freistellung mit vollem, arbeitgeberfinanziertem Lohnausgleich beim ersten Pflegefall in der Familie', '{1004}', null, 1, 2, null, 'Eine bezahlte Freistellung hilft Angehörigen, einen neuen Pflegefall zu organisieren; die langfristige Belastung bleibt. Die Kosten tragen die Arbeitgeber, was vor allem kleine Betriebe belastet.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=20', null, 'gemischt', '2026-09-29', false, true, null),
  (6278, 10, 16, null, 'Wohnortnahe, nichtkommerzielle Tages- und Kurzzeitpflege', '{1004}', 6228, 2, 2, null, 'Mehr erreichbare Entlastungsangebote und Beratung setzen daran an, dass Angehörige die Hauptlast tragen; die Plätze fehlen aber oft auch wegen fehlender Pflegekräfte. Der Bund kann Leistungen und Förderung erhöhen, Planung und Bau liegen bei Ländern und Trägern.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=20', null, 'gemischt', '2026-09-29', false, true, null),
  (6435, 7, 17, null, 'Alle Erwerbstätigen, auch Abgeordnete und Minister, zahlen in die gesetzliche Rente ein', '{701}', 6176, 1, 2, null, 'Mehr Einzahlende verbessern das Verhältnis zu den Rentnern zunächst, später entstehen aus den Beiträgen aber auch Ansprüche; für Beamte kostet der Übergang Bund und Länder anfangs viel Geld. Per Bundesgesetz möglich, mit langen Übergangszeiten.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=23', null, 'gemischt', '2026-09-29', false, true, null),
  (6436, 7, 17, null, 'Alle Selbstständigen in die Sozialversicherungen einbeziehen', '{702}', 6175, 2, 3, null, 'Viele Solo-Selbstständige sorgen kaum vor und sind im Alter häufiger arm; eine Vorsorgepflicht setzt direkt an dieser Lücke an, wirkt aber erst über Jahrzehnte, und Pflichtbeiträge belasten Selbstständige mit geringem Einkommen. Per Bundesgesetz umsetzbar.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=15', null, 'gemischt', '2026-09-29', false, true, null),
  (6437, 7, 17, null, 'Mindestlohn sofort auf 15 Euro anheben', '{702}', 6181, 1, 3, null, 'Ein höherer Mindestlohn erhöht die Rentenansprüche von Geringverdienenden; auch mit 15 Euro liegt die Rente nach Lücken im Erwerbsleben oft nahe der Grundsicherung. Per Bundesgesetz umsetzbar, bisher entscheidet die Mindestlohnkommission.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=21', null, 'gemischt', '2026-09-29', false, true, null),
  (6438, 7, 17, null, 'Mindestrente von 1.500 Euro nach 40 Versicherungsjahren, gestaffelt nach Versicherungsjahren', '{702}', null, 2, 1, null, 'Eine Mindestrente hebt niedrige Renten nach langen Versicherungszeiten direkt an; wer große Lücken im Erwerbsleben hat, erreicht die Stufen oft nicht. Die Kosten wären hoch, die Finanzierung nennt das Programm nicht.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=22', null, 'gemischt', '2026-09-29', false, true, null),
  (6439, 7, 17, null, 'Leistungsniveau von mindestens 75 Prozent des früheren Nettoeinkommens', '{701}', null, 1, 1, null, 'Ein deutlich höheres Leistungsniveau erhöht die Renten aller, gleicht aber nur die Folgen des steigenden Verhältnisses von Rentnern zu Beitragszahlenden aus; die Mehrkosten wären sehr hoch und sind nicht geklärt.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=23', null, 'gemischt', '2026-09-29', false, true, null),
  (6440, 10, 17, null, 'Pflegevollversicherung, überwiegend aus Steuermitteln finanziert', '{1002}', null, 3, 1, null, 'Eine Vollversicherung beseitigt die pflegebedingten Eigenanteile vollständig; Unterkunft und Verpflegung bleiben. Die Mehrkosten liegen bei deutlich über 10 Milliarden Euro im Jahr, eine Finanzierung überwiegend aus Steuern ist offen.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=27', null, 'belegt', '2026-09-29', false, true, null),
  (6441, 10, 17, null, 'Mehr Pflegepersonal ausbilden', '{1001}', 6235, 1, 3, null, 'Bessere Ausbildungsbedingungen können mehr Menschen in den Beruf bringen und Abbrüche verringern; die Ausbildung ist seit 2020 bereits vergütet und schulgeldfrei, weitere Effekte sind schwer abzuschätzen. Per Bundesgesetz und mit den Ländern umsetzbar.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=27', null, 'gemischt', '2026-09-29', false, true, null),
  (6442, 10, 17, null, 'Bessere Bezahlung in der Pflege', '{1001}', 6233, 2, 2, null, 'Höhere Löhne machen den Beruf attraktiver und halten Pflegekräfte; seit der Tarifpflicht von 2022 sind die Löhne deutlich gestiegen, was aber auch die Eigenanteile erhöht hat. Die Refinanzierung ist per Bundesgesetz möglich, die Finanzierung ist offen.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=27', null, 'gemischt', '2026-09-29', false, true, null),
  (6443, 10, 17, null, 'Pflegegeld deutlich erhöhen, orientiert an der Bezahlung professioneller Pflegekräfte', '{1004}', null, 1, 1, null, 'Ein höheres Pflegegeld erkennt die Arbeit pflegender Angehöriger an und entlastet sie finanziell, verringert aber nicht ihre zeitliche und körperliche Belastung. Eine Orientierung am Lohn von Pflegekräften würde ein Vielfaches kosten, die Finanzierung ist offen.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=33', null, 'gemischt', '2026-09-29', false, true, null),
  (6450, 10, 11, 'MV', 'Landesbeteiligung an Investitionskosten und Ausbildungsumlage, Landesinvestitionsprogramm für Pflegeeinrichtungen', '{1005}', 6448, 1, 3, null, 'Eine Landesbeteiligung an den Investitionskosten senkt den Eigenanteil; ohne Angabe, wie viel das Land übernimmt, bleibt die Entlastung offen. Das Land kann es selbst regeln.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=78', null, 'gemischt', '2026-09-29', false, true, null),
  (6451, 10, 12, 'ST', 'Investitionen in Pflegeeinrichtungen fördern, wo die Versorgung sonst nicht gesichert wäre', '{1005}', 6449, 1, 3, null, 'Fördergeld für Bau und Sanierung dämpft, was Heime als Investitionskosten weitergeben, betrifft aber nur geförderte Einrichtungen und senkt den laufenden Eigenanteil der übrigen Bewohner nicht. Das Land kann ein Programm selbst auflegen.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=13', null, 'gemischt', '2026-09-29', false, true, null),
  (6452, 10, 13, 'ST', 'Land übernimmt Investitions- und Ausbildungskosten aus dem Eigenanteil', '{1005}', 6447, 2, 2, null, 'Übernimmt das Land die Investitionskosten, sinkt der Eigenanteil im Heim direkt um im Schnitt rund 500 Euro im Monat; Unterkunft, Verpflegung und pflegebedingte Kosten bleiben. Das Land kann es selbst regeln, die Kosten von vielen Millionen Euro im Jahr muss es dauerhaft im Haushalt tragen.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=86', null, 'gemischt', '2026-09-29', false, true, null),
  (6453, 10, 15, 'BE', 'Investitionskostenzuschuss des Landes auf 300 Euro je Person und Monat erhöhen; 40.000 Euro je neuem Heimplatz', '{1005}', null, 2, 2, null, 'Ein Zuschuss von 300 Euro im Monat deckt einen großen Teil der Investitionskosten und senkt den Eigenanteil spürbar; das Programm nennt keine Finanzierung, und Berlin müsste dafür dauerhaft einen dreistelligen Millionenbetrag im Jahr aufbringen.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=71', null, 'gemischt', '2026-09-29', false, true, null),
  (6454, 10, 16, 'ST', 'Land übernimmt die Investitionskosten der Pflegeeinrichtungen vollständig', '{1005}', 6447, 2, 2, null, 'Übernimmt das Land die Investitionskosten, sinkt der Eigenanteil im Heim direkt um im Schnitt rund 500 Euro im Monat; Unterkunft, Verpflegung und pflegebedingte Kosten bleiben. Das Land kann es selbst regeln, die Kosten von vielen Millionen Euro im Jahr muss es dauerhaft im Haushalt tragen.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=56', null, 'gemischt', '2026-09-29', false, true, null),
  (6455, 10, 16, 'MV', 'Sanierungen vollstationärer Einrichtungen durch ein Investitionsprogramm unterstützen', '{1005}', 6449, 1, 3, null, 'Fördergeld für Bau und Sanierung dämpft, was Heime als Investitionskosten weitergeben, betrifft aber nur geförderte Einrichtungen und senkt den laufenden Eigenanteil der übrigen Bewohner nicht. Das Land kann ein Programm selbst auflegen.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=12', null, 'gemischt', '2026-09-29', false, true, null),
  (6456, 10, 16, 'BE', 'Pflegewohngeld: Land übernimmt Investitionskosten für Heimbewohner', '{1005}', null, 2, 2, null, 'Ein Pflegewohngeld übernimmt die Investitionskosten für Bewohner, die sie nicht selbst tragen können, und entlastet sie direkt; wer mehr Einkommen oder Vermögen hat, zahlt weiter. Das Land kann es selbst einführen, die Kosten muss es dauerhaft tragen.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=140', null, 'gemischt', '2026-09-29', false, true, null),
  (6457, 10, 17, 'MV', 'Eigenanteile senken: Land übernimmt die Investitionskosten auf Grundlage der Landespflegeplanung', '{1005}', 6447, 2, 2, null, 'Übernimmt das Land die Investitionskosten, sinkt der Eigenanteil im Heim direkt um im Schnitt rund 500 Euro im Monat; Unterkunft, Verpflegung und pflegebedingte Kosten bleiben. Das Land kann es selbst regeln, die Kosten von vielen Millionen Euro im Jahr muss es dauerhaft im Haushalt tragen.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=66', null, 'gemischt', '2026-09-29', false, true, null),
  (6643, 2, 13, null, 'Mietwucher leichter ahnden (§ 5 Wirtschaftsstrafgesetz), Indexmieten durch Obergrenzen begrenzen', '{202,204}', null, 1, 3, '{"mieter":{"wert":1,"begruendung":"Stärkt die Rechte von Mieterinnen und Mietern unmittelbar."}}'::jsonb, 'Erleichtert es, überhöhte Mieten zurückzufordern, und begrenzt Erhöhungen bei Indexmieten; wirkt nur für einen Teil der Verträge und schafft keine Wohnungen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=69', null, 'offen', '2026-09-30', false, true, null),
  (6644, 2, 15, null, 'Keine Zuweisung von Asylberechtigten und Asylbewerbern mehr in angespannte Wohnungsmärkte', '{205}', null, 1, 2, null, 'Verringert die Nachfrage in angespannten Märkten nur für eine kleine Gruppe und verlagert sie in andere Regionen; anerkannte Flüchtlinge dürfen nur befristet und zur Integration an einen Wohnort gebunden werden (§ 12a AufenthG).', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=111', null, 'offen', '2026-09-30', false, true, null),
  (6651, 2, 11, 'ST', 'Sozialen Wohnungsbau fördern, Wohnraumförderprogramme des Bundes weiter kofinanzieren', '{206}', 6645, 1, 3, null, 'Hält den Neubau geförderter Wohnungen aufrecht, bremst aber den Rückgang des Bestands nicht, solange mehr Wohnungen aus der Bindung fallen als neu gefördert werden.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=65', null, 'belegt', '2026-09-30', false, true, null),
  (6652, 2, 12, 'ST', 'Sozialen Wohnungsbau stärken, Bundesmittel nutzen und kofinanzieren', '{206}', 6646, 2, 2, null, 'Mehr geförderte Neubauten wirken dem Rückgang des Bestands direkt entgegen; das Land muss dafür zusätzliche Haushaltsmittel bereitstellen, und die Wirkung hängt davon ab, dass Bauherren die Förderung annehmen.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=43', null, 'belegt', '2026-09-30', false, true, null),
  (6653, 2, 13, 'ST', 'Sozialen Wohnungsbau und die Bundesmittel dafür in Sachsen-Anhalt nutzbar machen', '{206}', 6646, 2, 2, null, 'Mehr geförderte Neubauten wirken dem Rückgang des Bestands direkt entgegen; das Land muss dafür zusätzliche Haushaltsmittel bereitstellen, und die Wirkung hängt davon ab, dass Bauherren die Förderung annehmen.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=91', null, 'belegt', '2026-09-30', false, true, null),
  (6654, 2, 15, 'ST', '1:1-Kofinanzierung der Bundesmittel für den sozialen Wohnungsbau wiederbeleben', '{206}', 6646, 2, 2, null, 'Mehr geförderte Neubauten wirken dem Rückgang des Bestands direkt entgegen; das Land muss dafür zusätzliche Haushaltsmittel bereitstellen, und die Wirkung hängt davon ab, dass Bauherren die Förderung annehmen.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=190', null, 'belegt', '2026-09-30', false, true, null),
  (6655, 2, 16, 'ST', 'Wohnungsbauförderung nur noch für unbefristet gebundenen sozialen Mietwohnungsbau', '{206}', 6647, 2, 3, null, 'Verhindert, dass künftig geförderte Wohnungen nach einigen Jahren aus der Bindung fallen; das Land kann das im eigenen Förderrecht regeln. Private Bauherren nehmen eine Förderung mit Dauerbindung womöglich seltener an.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=83', null, 'gemischt', '2026-09-30', false, true, null),
  (6656, 2, 16, 'ST', 'Landeswohnungsbaugesellschaft gründen, deren Wohnungen nicht aus der Sozialbindung fallen', '{206}', null, 2, 2, null, 'Eine eigene Gesellschaft kann dauerhaft gebundene Wohnungen bauen, wo andere nicht investieren; Aufbau und Eigenkapital kosten Zeit und Geld, und in vielen Regionen Sachsen-Anhalts fehlt eher Nachfrage als Angebot.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=84', null, 'offen', '2026-09-30', false, true, null),
  (6657, 2, 17, 'ST', 'Sozialen und gemeinnützigen Wohnungsbau deutlich ausweiten', '{206}', 6646, 2, 2, null, 'Mehr geförderte Neubauten wirken dem Rückgang des Bestands direkt entgegen; das Land muss dafür zusätzliche Haushaltsmittel bereitstellen, und die Wirkung hängt davon ab, dass Bauherren die Förderung annehmen.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=30', null, 'belegt', '2026-09-30', false, true, null),
  (6658, 2, 11, 'MV', 'Eigenes Landesprogramm zur Förderung des Mietwohnungsbaus, vor allem für kommunale und genossenschaftliche Wohnungsunternehmen', '{206}', null, 1, 3, null, 'Mehr geförderte Mietwohnungen kommunaler und genossenschaftlicher Unternehmen können günstige Wohnungen sichern; das Programm nennt aber weder Miet- noch Belegungsbindungen noch einen Umfang.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=19', null, 'offen', '2026-09-30', false, true, null),
  (6659, 2, 12, 'MV', 'Landesförderprogramm für sozialen Wohnungsneubau fortführen', '{206}', 6645, 1, 3, null, 'Hält den Neubau geförderter Wohnungen aufrecht, bremst aber den Rückgang des Bestands nicht, solange mehr Wohnungen aus der Bindung fallen als neu gefördert werden.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=54', null, 'belegt', '2026-09-30', false, true, null),
  (6660, 2, 13, 'MV', 'Landesprogramm „Wohnungsbau Sozial“ aufstocken, höhere Zuschüsse für Sozialwohnungen', '{206}', 6646, 2, 2, null, 'Mehr geförderte Neubauten wirken dem Rückgang des Bestands direkt entgegen; das Land muss dafür zusätzliche Haushaltsmittel bereitstellen, und die Wirkung hängt davon ab, dass Bauherren die Förderung annehmen.', 'https://gruene-mv.de/?wpdmdl=33772#page=53', null, 'belegt', '2026-09-30', false, true, null),
  (6661, 2, 13, 'MV', 'Sozialbindung entfristen', '{206}', 6647, 2, 3, null, 'Verhindert, dass künftig geförderte Wohnungen nach einigen Jahren aus der Bindung fallen; das Land kann das im eigenen Förderrecht regeln. Private Bauherren nehmen eine Förderung mit Dauerbindung womöglich seltener an.', 'https://gruene-mv.de/?wpdmdl=33772#page=54', null, 'gemischt', '2026-09-30', false, true, null),
  (6662, 2, 13, 'MV', 'Höhere Quote für Sozialwohnungen bei Neubauten', '{206}', 6648, 2, 2, null, 'Sichert in neuen Quartieren mehr Sozialwohnungen ohne volle Landesförderung; eine sehr hohe Quote kann private Bauvorhaben unwirtschaftlich machen und den Neubau bremsen.', 'https://gruene-mv.de/?wpdmdl=33772#page=54', null, 'gemischt', '2026-09-30', false, true, null),
  (6663, 2, 16, 'MV', 'Förderprogramme für den sozialen Wohnungsbau reformieren und attraktiver machen', '{206}', 6646, 2, 2, null, 'Mehr geförderte Neubauten wirken dem Rückgang des Bestands direkt entgegen; das Land muss dafür zusätzliche Haushaltsmittel bereitstellen, und die Wirkung hängt davon ab, dass Bauherren die Förderung annehmen.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=6', null, 'belegt', '2026-09-30', false, true, null),
  (6664, 2, 17, 'MV', 'Sozialen Wohnungsbau mit verlässlichen Landesprogrammen bedarfsgerecht ausbauen', '{206}', 6646, 2, 2, null, 'Mehr geförderte Neubauten wirken dem Rückgang des Bestands direkt entgegen; das Land muss dafür zusätzliche Haushaltsmittel bereitstellen, und die Wirkung hängt davon ab, dass Bauherren die Förderung annehmen.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=21', null, 'belegt', '2026-09-30', false, true, null),
  (6665, 2, 11, 'BE', 'Wohnraumförderung fortführen (rund 5.000 neue Sozialwohnungen im Jahr, Wohnraumförderfonds)', '{206}', 6645, 1, 3, null, 'Hält den Neubau geförderter Wohnungen aufrecht, bremst aber den Rückgang des Bestands nicht, solange mehr Wohnungen aus der Bindung fallen als neu gefördert werden.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=29', null, 'belegt', '2026-09-30', false, true, null),
  (6666, 2, 11, 'BE', 'Einkommensprüfung in Sozialwohnungen mit Mietzuschlag, Einnahmen für neue Sozialwohnungen', '{206}', 6649, 1, 3, null, 'Lenkt Sozialwohnungen stärker zu Bedürftigen und bringt Geld für neue Förderung; schafft selbst kaum neue Wohnungen, der Verwaltungsaufwand ist hoch, und Besserverdienende ziehen aus, was die Durchmischung verringern kann.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=31', null, 'gemischt', '2026-09-30', false, true, null),
  (6667, 2, 12, 'BE', 'Quote für Sozialwohnungen im kooperativen Baulandmodell von 30 auf 50 Prozent erhöhen', '{206}', 6648, 2, 2, null, 'Sichert in neuen Quartieren mehr Sozialwohnungen ohne volle Landesförderung; eine sehr hohe Quote kann private Bauvorhaben unwirtschaftlich machen und den Neubau bremsen.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=18', null, 'gemischt', '2026-09-30', false, true, null),
  (6668, 2, 12, 'BE', 'Eigentümer ab 50 Wohnungen verpflichten, einen Anteil an Haushalte mit Wohnberechtigungsschein zu vermieten', '{206}', 6650, 2, 1, null, 'Würde den Bestand an Wohnungen für Haushalte mit geringem Einkommen schnell erweitern; ob ein Land das regeln darf, ist fraglich, denn das Mietrecht ist Bundessache (Bundesverfassungsgericht 2021 zum Berliner Mietendeckel).', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=21', null, 'offen', '2026-09-30', false, true, null),
  (6669, 2, 13, 'BE', 'Quote für mietpreisgebundene Wohnungen in der kooperativen Baulandentwicklung auf 50 Prozent erhöhen', '{206}', 6648, 2, 2, null, 'Sichert in neuen Quartieren mehr Sozialwohnungen ohne volle Landesförderung; eine sehr hohe Quote kann private Bauvorhaben unwirtschaftlich machen und den Neubau bremsen.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=60', null, 'gemischt', '2026-09-30', false, true, null),
  (6670, 2, 14, 'BE', 'Fehlbelegungsabgabe am Marktpreis orientiert', '{206}', 6649, 1, 3, null, 'Lenkt Sozialwohnungen stärker zu Bedürftigen und bringt Geld für neue Förderung; schafft selbst kaum neue Wohnungen, der Verwaltungsaufwand ist hoch, und Besserverdienende ziehen aus, was die Durchmischung verringern kann.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=42', null, 'gemischt', '2026-09-30', false, true, null),
  (6671, 2, 15, 'BE', 'Fehlbelegungsabgabe wieder einführen', '{206}', 6649, 1, 3, null, 'Lenkt Sozialwohnungen stärker zu Bedürftigen und bringt Geld für neue Förderung; schafft selbst kaum neue Wohnungen, der Verwaltungsaufwand ist hoch, und Besserverdienende ziehen aus, was die Durchmischung verringern kann.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=6', null, 'gemischt', '2026-09-30', false, true, null),
  (6672, 2, 16, 'BE', 'Bestände mit auslaufenden Bindungen ankaufen, Förderprogramm zur Verlängerung auslaufender Bindungen', '{206}', null, 2, 2, null, 'Setzt direkt am Auslaufen der Bindungen an; Ankäufe und Verlängerungen sind teuer und schaffen keine zusätzlichen Wohnungen.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=33', null, 'gemischt', '2026-09-30', false, true, null),
  (6673, 2, 16, 'BE', 'Kooperative Baulandentwicklung: mindestens zwei Drittel mietpreis- und belegungsgebundene Wohnungen', '{206}', 6648, 2, 2, null, 'Sichert in neuen Quartieren mehr Sozialwohnungen ohne volle Landesförderung; eine sehr hohe Quote kann private Bauvorhaben unwirtschaftlich machen und den Neubau bremsen.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=36', null, 'gemischt', '2026-09-30', false, true, null),
  (6674, 2, 16, 'BE', 'Sicher-Wohnen-Gesetz: große Vermieter müssen einen Teil frei werdender Wohnungen zu Sozialmieten vermieten', '{206}', 6650, 2, 1, null, 'Würde den Bestand an Wohnungen für Haushalte mit geringem Einkommen schnell erweitern; ob ein Land das regeln darf, ist fraglich, denn das Mietrecht ist Bundessache (Bundesverfassungsgericht 2021 zum Berliner Mietendeckel).', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=23', null, 'offen', '2026-09-30', false, true, null),
  (6675, 2, 17, 'BE', 'Mindestens 6.000 neue Sozialwohnungen pro Jahr', '{206}', 6646, 2, 2, null, 'Mehr geförderte Neubauten wirken dem Rückgang des Bestands direkt entgegen; das Land muss dafür zusätzliche Haushaltsmittel bereitstellen, und die Wirkung hängt davon ab, dass Bauherren die Förderung annehmen.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=7', null, 'belegt', '2026-09-30', false, true, null),
  (6676, 2, 17, 'BE', 'Öffentlich geförderte Wohnungen dauerhaft binden', '{206}', 6647, 2, 3, null, 'Verhindert, dass künftig geförderte Wohnungen nach einigen Jahren aus der Bindung fallen; das Land kann das im eigenen Förderrecht regeln. Private Bauherren nehmen eine Förderung mit Dauerbindung womöglich seltener an.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=7', null, 'gemischt', '2026-09-30', false, true, null),
  (6682, 1, 11, null, 'Hausarztpraxen sollen Patientinnen und Patienten stärker steuern, um Wartezeiten zu senken', '{102}', 6677, 2, 2, null, 'Lenkt Patientinnen und Patienten gezielter und kann unnötige Facharztbesuche vermeiden; die Erfahrungen aus Ländern mit Primärarztsystem sind überwiegend positiv. Es setzt aber voraus, dass genug Hausarztpraxen da sind, die schon heute knapp sind.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=70', null, 'gemischt', '2026-09-30', false, true, null),
  (6683, 1, 11, null, 'Andere Gesundheitsberufe sollen mehr Verantwortung für die Versorgung übernehmen', '{102}', 6678, 2, 2, null, 'Entlastet Ärztinnen und Ärzte, sodass mehr Termine frei werden; internationale Studien zeigen gute Qualität bei übertragenen Aufgaben. Braucht neue Ausbildungswege und Änderungen im Berufsrecht, das dauert.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=69', null, 'belegt', '2026-09-30', false, true, null),
  (6684, 1, 12, null, 'Gründung kommunaler MVZ erleichtern', '{101}', 6679, 2, 2, null, 'Angestelltenverhältnisse und Teamarbeit entsprechen den Wünschen vieler junger Ärztinnen und Ärzte und können Praxissitze in unterversorgten Regionen besetzen; wie viele Zentren tatsächlich entstehen, hängt von Kommunen und Finanzierung ab.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=29', null, 'gemischt', '2026-09-30', false, true, null),
  (6685, 1, 12, null, 'Advanced Practice Nurses und Gemeindeschwestern einführen', '{102}', 6678, 2, 2, null, 'Entlastet Ärztinnen und Ärzte, sodass mehr Termine frei werden; internationale Studien zeigen gute Qualität bei übertragenen Aufgaben. Braucht neue Ausbildungswege und Änderungen im Berufsrecht, das dauert.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=29', null, 'belegt', '2026-09-30', false, true, null),
  (6686, 1, 12, null, 'Termingarantie: Gesetzlich Versicherte sollen so schnell wie Privatversicherte einen Termin bekommen, sonst sinkt ihr Beitrag', '{102,103}', null, 1, 2, null, 'Setzt Krankenkassen und Kassenärztliche Vereinigungen unter Druck, Termine zu vermitteln, schafft aber selbst keine zusätzlichen Termine; Terminservicestellen gibt es bereits.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=29', null, 'offen', '2026-09-30', false, true, null),
  (6687, 1, 12, null, 'Bürgerversicherung mit einheitlichem Vergütungssystem', '{103}', 6681, 2, 1, null, 'Nimmt Praxen den finanziellen Anreiz, Privatversicherte bei Terminen vorzuziehen; ob die Wartezeiten insgesamt sinken, hängt von der Höhe der neuen Vergütung ab. Der Umbau der privaten Krankenversicherung ist rechtlich und praktisch sehr aufwendig.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=29', null, 'gemischt', '2026-09-30', false, true, null),
  (6688, 1, 13, null, 'Hausärztlich-zentrierte Primärversorgung stärken', '{102}', 6677, 2, 2, null, 'Lenkt Patientinnen und Patienten gezielter und kann unnötige Facharztbesuche vermeiden; die Erfahrungen aus Ländern mit Primärarztsystem sind überwiegend positiv. Es setzt aber voraus, dass genug Hausarztpraxen da sind, die schon heute knapp sind.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=88', null, 'gemischt', '2026-09-30', false, true, null),
  (6689, 1, 13, null, 'Zusammenarbeit mit anderen Gesundheitsberufen wie Community Health Nurses ausbauen', '{102}', 6678, 2, 2, null, 'Entlastet Ärztinnen und Ärzte, sodass mehr Termine frei werden; internationale Studien zeigen gute Qualität bei übertragenen Aufgaben. Braucht neue Ausbildungswege und Änderungen im Berufsrecht, das dauert.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=88', null, 'belegt', '2026-09-30', false, true, null),
  (6690, 1, 13, null, 'Gründung kommunaler MVZ und Primärversorgungszentren fördern', '{101}', 6679, 2, 2, null, 'Angestelltenverhältnisse und Teamarbeit entsprechen den Wünschen vieler junger Ärztinnen und Ärzte und können Praxissitze in unterversorgten Regionen besetzen; wie viele Zentren tatsächlich entstehen, hängt von Kommunen und Finanzierung ab.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=88', null, 'gemischt', '2026-09-30', false, true, null),
  (6691, 1, 13, null, 'Mehr Sprechstunden für gesetzlich Versicherte', '{103}', null, 1, 3, null, 'Verschiebt Termine zu gesetzlich Versicherten; Mindestsprechstunden gibt es schon, und ohne mehr Ärztinnen und Ärzte entstehen insgesamt kaum zusätzliche Termine.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=88', null, 'offen', '2026-09-30', false, true, null),
  (6692, 1, 13, null, 'Anspruch auf Patientenlotsen', '{102}', null, 1, 2, null, 'Lotsen können Wege durch das System verkürzen, vor allem für chronisch Kranke; für die Terminlage insgesamt ist die Wirkung klein, und es braucht zusätzliches Personal.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=89', null, 'offen', '2026-09-30', false, true, null),
  (6693, 1, 14, null, 'Primärarztsystem: Haus- und Kinderärzte als erste Anlaufstelle', '{102}', 6677, 2, 2, null, 'Lenkt Patientinnen und Patienten gezielter und kann unnötige Facharztbesuche vermeiden; die Erfahrungen aus Ländern mit Primärarztsystem sind überwiegend positiv. Es setzt aber voraus, dass genug Hausarztpraxen da sind, die schon heute knapp sind.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=33', null, 'gemischt', '2026-09-30', false, true, null),
  (6694, 1, 14, null, 'Ungekürzte Vergütung, Behandlung ohne Budgetierung', '{101,103}', 6680, 1, 2, null, 'Voll bezahlte Leistungen machen Kassenpatienten für Praxen attraktiver und verringern den Vergütungsabstand zu Privatversicherten; ob dadurch spürbar mehr Termine entstehen, ist nicht belegt, und die Mehrkosten tragen die Beitragszahlenden.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=33', null, 'gemischt', '2026-09-30', false, true, null),
  (6695, 1, 15, null, 'Budgetierung ärztlicher Leistungen beenden', '{101,103}', 6680, 1, 2, null, 'Voll bezahlte Leistungen machen Kassenpatienten für Praxen attraktiver und verringern den Vergütungsabstand zu Privatversicherten; ob dadurch spürbar mehr Termine entstehen, ist nicht belegt, und die Mehrkosten tragen die Beitragszahlenden.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=28', null, 'gemischt', '2026-09-30', false, true, null),
  (6696, 1, 15, null, 'Gestaffelte Bonus- und Rückvergütungssysteme gegen Bagatellbehandlungen', '{102}', null, 1, 2, null, 'Finanzielle Anreize können Arztbesuche etwas senken; die Praxisgebühr von 2004 bis 2012 hatte nur kurz Wirkung und belastete vor allem Menschen mit geringem Einkommen.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=28', null, 'gemischt', '2026-09-30', false, true, null),
  (6697, 1, 15, null, 'Finanzielle und organisatorische Niederlassungshilfen für Ärzte auf dem Land', '{101}', null, 1, 3, null, 'Zuschüsse für die Niederlassung gibt es bereits bei Kassenärztlichen Vereinigungen und Ländern; sie wirken bisher nur begrenzt, weil viele junge Ärztinnen und Ärzte eine Anstellung bevorzugen.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=28', null, 'gemischt', '2026-09-30', false, true, null),
  (6698, 1, 15, null, 'Mehr Studienplätze in Human- und Zahnmedizin', '{101}', 6824, 2, 2, null, 'Mehr Absolventinnen und Absolventen setzen am Nachwuchsmangel an, wirken aber erst nach etwa zwölf Jahren Studium und Weiterbildung; ob sie Hausärzte auf dem Land werden, ist offen. Studienplätze finanzieren die Länder, der Bund kann nur mitfinanzieren.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=34', null, 'gemischt', '2026-09-30', false, true, null),
  (6699, 1, 16, null, 'Kommunale Versorgungszentren als Rückgrat der wohnortnahen Versorgung fördern', '{101}', 6679, 2, 2, null, 'Angestelltenverhältnisse und Teamarbeit entsprechen den Wünschen vieler junger Ärztinnen und Ärzte und können Praxissitze in unterversorgten Regionen besetzen; wie viele Zentren tatsächlich entstehen, hängt von Kommunen und Finanzierung ab.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=19', null, 'gemischt', '2026-09-30', false, true, null),
  (6700, 1, 16, null, 'Kleinere Versorgungsbezirke, von Ländern und Kommunen bestimmt', '{101}', null, 1, 2, null, 'Kleinere Planungsbereiche machen Unterversorgung in einzelnen Stadtteilen und Dörfern sichtbar und können Niederlassungen dorthin lenken; zusätzliche Ärztinnen und Ärzte entstehen dadurch nicht.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=19', null, 'offen', '2026-09-30', false, true, null),
  (6701, 1, 16, null, 'Befugnisse der Heilberufe ausweiten', '{102}', 6678, 2, 2, null, 'Entlastet Ärztinnen und Ärzte, sodass mehr Termine frei werden; internationale Studien zeigen gute Qualität bei übertragenen Aufgaben. Braucht neue Ausbildungswege und Änderungen im Berufsrecht, das dauert.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=19', null, 'belegt', '2026-09-30', false, true, null),
  (6702, 1, 16, null, 'Privatversicherte in die gesetzliche Krankenversicherung übernehmen', '{103}', 6681, 2, 1, null, 'Nimmt Praxen den finanziellen Anreiz, Privatversicherte bei Terminen vorzuziehen; ob die Wartezeiten insgesamt sinken, hängt von der Höhe der neuen Vergütung ab. Der Umbau der privaten Krankenversicherung ist rechtlich und praktisch sehr aufwendig.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=18', null, 'gemischt', '2026-09-30', false, true, null),
  (6710, 3, 11, null, 'Netzentgelte senken und neu regeln', '{301}', 6703, 2, 2, null, 'Senkt einen großen Teil des Strompreises direkt und spürbar; die Kosten des Netzausbaus trägt dann der Bundeshaushalt, und die Finanzierung muss auf Dauer gesichert werden.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=22', null, 'belegt', '2026-09-30', false, true, null),
  (6711, 3, 11, null, 'Stromsteuer für alle senken', '{302}', 6704, 2, 2, null, 'Senkt den Strompreis für Haushalte um gut 2 Cent je Kilowattstunde; kostet den Bundeshaushalt mehrere Milliarden Euro im Jahr.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=22', null, 'belegt', '2026-09-30', false, true, null),
  (6712, 3, 11, null, 'Klimabonus als sozialer Ausgleich für den CO₂-Preis', '{302}', 6705, 1, 2, null, 'Gleicht höhere Heizkosten durch den CO₂-Preis vor allem für Haushalte mit geringem Einkommen aus, senkt die Preise selbst aber nicht; ein Auszahlungsweg muss erst aufgebaut werden.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=24', null, 'belegt', '2026-09-30', false, true, null),
  (6713, 3, 11, null, 'Prüfen, ob die zuletzt abgeschalteten Kernkraftwerke wieder in Betrieb gehen können', '{304}', 6708, 1, 1, null, 'Mehr Kraftwerksleistung könnte die Börsenpreise in einzelnen Stunden senken; die abgeschalteten Kernkraftwerke sind weitgehend zurückgebaut, eine Wiederinbetriebnahme wäre teuer, langwierig und rechtlich neu zu regeln, und Kohlestrom wird durch den Emissionshandel teurer.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=22', null, 'gemischt', '2026-09-30', false, true, null),
  (6714, 3, 11, null, 'Smart Meter und Digitalisierung, damit Verbraucher flexibler auf den Strompreis reagieren können', '{304}', 6709, 1, 3, null, 'Haushalte, die Strom in günstigen Stunden nutzen können, sparen; für viele Haushalte ohne Wärmepumpe, E-Auto oder Batterie ist die Ersparnis gering.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=22', null, 'gemischt', '2026-09-30', false, true, null),
  (6715, 3, 11, null, 'Investitionen in Energieeffizienz steuerlich schneller absetzbar', '{305}', null, 1, 2, null, 'Macht Sanierungen und Heizungstausch für Eigentümer günstiger und senkt langfristig den Verbrauch; Mieterinnen und Mieter profitieren nur indirekt, und der Steuervorteil hilft Haushalten mit hohem Einkommen mehr.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=24', null, 'gemischt', '2026-09-30', false, true, null),
  (6716, 3, 12, null, 'Übertragungsnetzentgelte stabilisieren und auf 3 Cent pro Kilowattstunde deckeln', '{301}', 6703, 2, 2, null, 'Senkt einen großen Teil des Strompreises direkt und spürbar; die Kosten des Netzausbaus trägt dann der Bundeshaushalt, und die Finanzierung muss auf Dauer gesichert werden.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=7', null, 'belegt', '2026-09-30', false, true, null),
  (6717, 3, 12, null, 'Klimageld, wenn ab 2027 der europäische CO₂-Preis gilt', '{302}', 6705, 1, 2, null, 'Gleicht höhere Heizkosten durch den CO₂-Preis vor allem für Haushalte mit geringem Einkommen aus, senkt die Preise selbst aber nicht; ein Auszahlungsweg muss erst aufgebaut werden.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=34', null, 'belegt', '2026-09-30', false, true, null),
  (6718, 3, 12, null, 'Wind- und Solarenergie konsequent ausbauen, Speicher einbinden', '{304}', 6707, 2, 2, null, 'Mehr Wind- und Solarstrom verdrängt teure Gaskraftwerke an der Börse und senkt dort die Preise; zugleich kostet der dafür nötige Netzausbau Geld, das über die Netzentgelte bezahlt wird.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=34', null, 'gemischt', '2026-09-30', false, true, null),
  (6719, 3, 12, null, 'Soziales Wärmepumpen-Leasing für ärmere Haushalte', '{305}', null, 1, 2, null, 'Senkt die Hürde, von Gas oder Öl auf eine Wärmepumpe umzusteigen, für Haushalte ohne Ersparnisse; die meisten ärmeren Haushalte wohnen zur Miete und entscheiden nicht über die Heizung.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=34', null, 'offen', '2026-09-30', false, true, null),
  (6720, 3, 13, null, 'Netzentgelte für überregionale Stromleitungen aus dem Deutschlandfonds bezahlen', '{301}', 6703, 2, 2, null, 'Senkt einen großen Teil des Strompreises direkt und spürbar; die Kosten des Netzausbaus trägt dann der Bundeshaushalt, und die Finanzierung muss auf Dauer gesichert werden.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=17', null, 'belegt', '2026-09-30', false, true, null),
  (6721, 3, 13, null, 'Stromsteuer auf das europäische Minimum senken', '{302}', 6704, 2, 2, null, 'Senkt den Strompreis für Haushalte um gut 2 Cent je Kilowattstunde; kostet den Bundeshaushalt mehrere Milliarden Euro im Jahr.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=17', null, 'belegt', '2026-09-30', false, true, null),
  (6722, 3, 13, null, 'Sozial gestaffeltes Klimageld', '{302}', 6705, 1, 2, null, 'Gleicht höhere Heizkosten durch den CO₂-Preis vor allem für Haushalte mit geringem Einkommen aus, senkt die Preise selbst aber nicht; ein Auszahlungsweg muss erst aufgebaut werden.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=40', null, 'belegt', '2026-09-30', false, true, null),
  (6723, 3, 13, null, 'Dynamische Stromtarife und flexible Netze', '{304}', 6709, 1, 3, null, 'Haushalte, die Strom in günstigen Stunden nutzen können, sparen; für viele Haushalte ohne Wärmepumpe, E-Auto oder Batterie ist die Ersparnis gering.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=42', null, 'gemischt', '2026-09-30', false, true, null),
  (6724, 3, 13, null, 'Strom in spätestens zehn Jahren vollständig erneuerbar', '{304}', 6707, 2, 2, null, 'Mehr Wind- und Solarstrom verdrängt teure Gaskraftwerke an der Börse und senkt dort die Preise; zugleich kostet der dafür nötige Netzausbau Geld, das über die Netzentgelte bezahlt wird.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=43', null, 'gemischt', '2026-09-30', false, true, null),
  (6725, 3, 13, null, 'Förderung von bis zu 70 Prozent für fossilfreie Heizungen', '{305}', null, 2, 3, null, 'Macht den Umstieg von Gas und Öl auf Wärmepumpen und Wärmenetze bezahlbarer und koppelt die Heizkosten von fossilen Preisen ab; die Förderung besteht bereits, der Umstieg dauert aber Jahre und hängt vom Strompreis ab.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=44', null, 'gemischt', '2026-09-30', false, true, null),
  (6726, 3, 14, null, 'Stromsteuer auf das EU-Mindestmaß senken, langfristig abschaffen', '{302}', 6704, 2, 2, null, 'Senkt den Strompreis für Haushalte um gut 2 Cent je Kilowattstunde; kostet den Bundeshaushalt mehrere Milliarden Euro im Jahr.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=17', null, 'belegt', '2026-09-30', false, true, null),
  (6727, 3, 14, null, 'Netzausbau günstiger: Freileitungen statt Erdkabel, dynamische Netzentgelte', '{301}', null, 2, 2, null, 'Freileitungen sind deutlich billiger als Erdkabel und dämpfen so den Anstieg der Netzentgelte; für viele bereits geplante Leitungen wäre ein Wechsel aufwendig, und Freileitungen stoßen vor Ort häufiger auf Widerstand.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=17', null, 'gemischt', '2026-09-30', false, true, null),
  (6728, 3, 14, null, 'Klimadividende: Einnahmen aus dem Emissionshandel pro Kopf zurückzahlen', '{302}', 6705, 1, 2, null, 'Gleicht höhere Heizkosten durch den CO₂-Preis vor allem für Haushalte mit geringem Einkommen aus, senkt die Preise selbst aber nicht; ein Auszahlungsweg muss erst aufgebaut werden.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=40', null, 'belegt', '2026-09-30', false, true, null),
  (6729, 3, 15, null, 'CO₂-Abgabe abschaffen', '{302,305}', 6706, 2, 1, null, 'Würde Gas- und Heizölpreise direkt senken; ab 2028 gilt aber der europäische Emissionshandel für Gebäude und Verkehr, den Deutschland nicht allein abschaffen kann.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=14', null, 'belegt', '2026-09-30', false, true, null),
  (6730, 3, 15, null, 'Energiesteuer reduzieren, Stromsteuer auf das Minimum senken', '{302}', 6704, 2, 2, null, 'Senkt den Strompreis für Haushalte um gut 2 Cent je Kilowattstunde; kostet den Bundeshaushalt mehrere Milliarden Euro im Jahr.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=14', null, 'belegt', '2026-09-30', false, true, null),
  (6731, 3, 15, null, 'Kohlekraftwerke länger betreiben, Wiedereinstieg in die Kernenergie', '{304}', 6708, 1, 1, null, 'Mehr Kraftwerksleistung könnte die Börsenpreise in einzelnen Stunden senken; die abgeschalteten Kernkraftwerke sind weitgehend zurückgebaut, eine Wiederinbetriebnahme wäre teuer, langwierig und rechtlich neu zu regeln, und Kohlestrom wird durch den Emissionshandel teurer.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=14', null, 'gemischt', '2026-09-30', false, true, null),
  (6732, 3, 15, null, 'Nord-Stream-Pipelines reparieren und wieder in Betrieb nehmen', '{303}', 6828, 1, 0, null, 'Mehr Pipelinegas könnte den Gaspreis senken, würde die Abhängigkeit von einem einzelnen Lieferland aber wieder erhöhen; die EU hat mit der Verordnung (EU) 2026/261 die Einfuhr von russischem Gas verboten (Pipelinegas spätestens ab Herbst 2027), eine Wiederaufnahme wäre EU-rechtswidrig.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=14', null, 'gemischt', '2026-09-30', false, true, null),
  (6733, 3, 15, null, 'Ausbau der Windenergie stoppen, um höhere Netzentgelte zu verhindern', '{301}', null, 1, 3, null, 'Weniger neue Windparks bedeuten weniger neuen Netzausbau; zugleich fehlt günstiger Windstrom, sodass teurere Kraftwerke den Börsenpreis öfter bestimmen.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=14', null, 'gemischt', '2026-09-30', false, true, null),
  (6734, 3, 16, null, 'Soziales Klimageld von 320 Euro pro Person und Jahr', '{302}', 6705, 1, 2, null, 'Gleicht höhere Heizkosten durch den CO₂-Preis vor allem für Haushalte mit geringem Einkommen aus, senkt die Preise selbst aber nicht; ein Auszahlungsweg muss erst aufgebaut werden.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=7', null, 'belegt', '2026-09-30', false, true, null),
  (6735, 3, 16, null, 'Neue Netzentgeltstruktur: Stromerzeuger und Stromhandel an den Transportkosten beteiligen', '{301}', null, 1, 1, null, 'Würde Haushalte bei den Netzentgelten entlasten; Entgelte für Erzeuger begrenzt das EU-Recht eng, und die Kosten würden zum Teil über höhere Strompreise wieder bei den Verbrauchern landen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=32', null, 'offen', '2026-09-30', false, true, null),
  (6736, 3, 16, null, 'Stromsteuer auf den europäischen Mindeststeuersatz senken', '{302}', 6704, 2, 2, null, 'Senkt den Strompreis für Haushalte um gut 2 Cent je Kilowattstunde; kostet den Bundeshaushalt mehrere Milliarden Euro im Jahr.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=32', null, 'belegt', '2026-09-30', false, true, null),
  (6737, 3, 16, null, 'Schnellstmöglich auf erneuerbare Energien umsteigen', '{304}', 6707, 2, 2, null, 'Mehr Wind- und Solarstrom verdrängt teure Gaskraftwerke an der Börse und senkt dort die Preise; zugleich kostet der dafür nötige Netzausbau Geld, das über die Netzentgelte bezahlt wird.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=32', null, 'gemischt', '2026-09-30', false, true, null),
  (6738, 3, 16, null, 'Keine CO₂-Preise im Wärmebereich', '{302,305}', 6706, 2, 1, null, 'Würde Gas- und Heizölpreise direkt senken; ab 2028 gilt aber der europäische Emissionshandel für Gebäude und Verkehr, den Deutschland nicht allein abschaffen kann.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=34', null, 'belegt', '2026-09-30', false, true, null),
  (6739, 3, 16, null, 'Heizungstausch nach Einkommen gestaffelt fördern, bis zu 100 Prozent', '{305}', null, 2, 2, null, 'Ermöglicht auch Eigentümern mit wenig Geld den Umstieg von Gas und Öl und koppelt die Heizkosten von fossilen Preisen ab; das Programm soll 25 Milliarden Euro im Jahr kosten, die Finanzierung ist offen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=34', null, 'gemischt', '2026-09-30', false, true, null),
  (6755, 8, 11, null, 'Auskömmliche Finanzierung des Nahverkehrs sichern', '{801}', 6740, 2, 2, null, 'Mehr Geld erlaubt den Ländern, mehr Züge und Busse zu bestellen; ob es beim Angebot auf dem Land ankommt oder etwa für gestiegene Kosten oder Ticketpreise gebraucht wird, entscheiden die Länder.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=74', null, 'gemischt', '2026-09-30', false, true, null),
  (6756, 8, 11, null, 'Infrastruktur und Transport der Deutschen Bahn stärker trennen', '{802}', 6741, 1, 2, null, 'Soll Wettbewerb und klare Verantwortung für das Netz schaffen; in anderen Ländern hat die Trennung nicht einheitlich zu einem besseren Netz geführt, und die Umstrukturierung bindet Jahre.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=74', null, 'gemischt', '2026-09-30', false, true, null),
  (6757, 8, 11, null, 'Dauerhafte, vom Haushalt unabhängige Finanzierung der Infrastruktur', '{802}', 6742, 2, 2, null, 'Verlässliche Mittel über mehrere Jahre erleichtern die Planung von Sanierungen, wie der Bahninfrastrukturfonds der Schweiz zeigt; ohne bessere Steuerung ist nicht gesichert, dass mehr Geld den Zustand verbessert.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=74', null, 'gemischt', '2026-09-30', false, true, null),
  (6758, 8, 11, null, 'Berufskraftfahrerqualifikation reformieren gegen den Fahrermangel bei Bus und Lkw', '{803}', 6743, 1, 2, null, 'Senkt eine Hürde für den Berufseinstieg; die Regeln stammen zum großen Teil aus EU-Richtlinien, und Bezahlung und Arbeitszeiten bleiben die Hauptgründe für den Mangel.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=75', null, 'gemischt', '2026-09-30', false, true, null),
  (6759, 8, 12, null, 'Rekordinvestitionen in die Schiene fortsetzen, Generalsanierung wichtiger Strecken', '{802}', 6744, 2, 2, null, 'Setzt direkt am maroden Netz an, wirkt wegen Bauzeiten aber erst nach Jahren; der Bundesrechnungshof bezweifelt, dass mehr Mittel ohne bessere Steuerung den Zustand verbessern.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=35', null, 'gemischt', '2026-09-30', false, true, null),
  (6760, 8, 12, null, 'DB InfraGO und Gesamtkonzern mit mehr Kontrolle und Steuerung des Bundes', '{802}', 6745, 2, 3, null, 'Setzt an der vom Bundesrechnungshof kritisierten Steuerung an; wie viel das für Pünktlichkeit bringt, ist kaum untersucht.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=35', null, 'offen', '2026-09-30', false, true, null),
  (6761, 8, 12, null, 'Finanzierung des Nahverkehrs mit Ländern und Kommunen dauerhaft stärken', '{801}', 6740, 2, 2, null, 'Mehr Geld erlaubt den Ländern, mehr Züge und Busse zu bestellen; ob es beim Angebot auf dem Land ankommt oder etwa für gestiegene Kosten oder Ticketpreise gebraucht wird, entscheiden die Länder.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=35', null, 'gemischt', '2026-09-30', false, true, null),
  (6762, 8, 12, null, 'Personalübernahme beim Betreiberwechsel und Tariftreue in Vergabeverfahren', '{803}', 6746, 2, 2, null, 'Bessere Bedingungen machen den Fahrdienst attraktiver und halten Beschäftigte im Beruf; die Kosten tragen Länder und Kommunen, und Vergaben regeln vor allem die Länder.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=35', null, 'gemischt', '2026-09-30', false, true, null),
  (6763, 8, 13, null, 'Überjährige Finanzierung für Schiene und Nahverkehr über den Deutschlandfonds', '{802}', 6742, 2, 2, null, 'Verlässliche Mittel über mehrere Jahre erleichtern die Planung von Sanierungen, wie der Bahninfrastrukturfonds der Schweiz zeigt; ohne bessere Steuerung ist nicht gesichert, dass mehr Geld den Zustand verbessert.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=47', null, 'gemischt', '2026-09-30', false, true, null),
  (6764, 8, 13, null, 'Stillgelegte Bahntrassen auf dem Land reaktivieren', '{801}', 6747, 1, 2, null, 'Verbessert die Anbindung einzelner ländlicher Orte deutlich, erreicht insgesamt aber nur wenige Menschen; Planung und Bau dauern viele Jahre.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=47', null, 'gemischt', '2026-09-30', false, true, null),
  (6765, 8, 13, null, 'Bundesmittel für den Nahverkehr gemeinsam mit den Ländern steigern', '{801}', 6740, 2, 2, null, 'Mehr Geld erlaubt den Ländern, mehr Züge und Busse zu bestellen; ob es beim Angebot auf dem Land ankommt oder etwa für gestiegene Kosten oder Ticketpreise gebraucht wird, entscheiden die Länder.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=49', null, 'gemischt', '2026-09-30', false, true, null),
  (6766, 8, 13, null, 'Im ganzen Land ein alltagstaugliches Angebot mit verlässlichen Takten garantieren', '{801}', 6748, 2, 2, null, 'Setzt direkt am fehlenden Grundangebot an; ein flächendeckender Takt ist teuer und scheitert derzeit auch am fehlenden Fahrpersonal. Zuständig sind die Länder, der Bund kann über Geld und Rahmenrecht beitragen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=49', null, 'offen', '2026-09-30', false, true, null),
  (6767, 8, 13, null, 'Marodes Schienennetz mit Hochdruck sanieren', '{802}', 6744, 2, 2, null, 'Setzt direkt am maroden Netz an, wirkt wegen Bauzeiten aber erst nach Jahren; der Bundesrechnungshof bezweifelt, dass mehr Mittel ohne bessere Steuerung den Zustand verbessern.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=50', null, 'gemischt', '2026-09-30', false, true, null),
  (6768, 8, 13, null, 'Bessere Arbeitsbedingungen und gute Bezahlung im Nah- und Fernverkehr', '{803}', 6746, 2, 2, null, 'Bessere Bedingungen machen den Fahrdienst attraktiver und halten Beschäftigte im Beruf; die Kosten tragen Länder und Kommunen, und Vergaben regeln vor allem die Länder.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=50', null, 'gemischt', '2026-09-30', false, true, null),
  (6769, 8, 14, null, 'Netz und Betrieb bei der Deutschen Bahn trennen', '{802}', 6741, 1, 2, null, 'Soll Wettbewerb und klare Verantwortung für das Netz schaffen; in anderen Ländern hat die Trennung nicht einheitlich zu einem besseren Netz geführt, und die Umstrukturierung bindet Jahre.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=43', null, 'gemischt', '2026-09-30', false, true, null),
  (6770, 8, 14, null, 'Bus-Führerschein und Berufskraftfahrerqualifikation günstiger machen', '{803}', 6743, 1, 2, null, 'Senkt eine Hürde für den Berufseinstieg; die Regeln stammen zum großen Teil aus EU-Richtlinien, und Bezahlung und Arbeitszeiten bleiben die Hauptgründe für den Mangel.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=42', null, 'gemischt', '2026-09-30', false, true, null),
  (6771, 8, 14, null, 'Starre Linienverkehre durch flexible, bedarfsgerechte Angebote ergänzen', '{801}', null, 1, 2, null, 'On-Demand-Angebote können Lücken im ländlichen Raum schließen, befördern aber wenige Menschen je Fahrt und sind teuer; Angebot und Finanzierung liegen bei Ländern und Kommunen.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=43', null, 'gemischt', '2026-09-30', false, true, null),
  (6772, 8, 15, null, 'Bahnkonzern in eine GmbH umwandeln, damit der Bund die Infrastruktur wirksam steuern kann', '{802}', 6745, 2, 3, null, 'Setzt an der vom Bundesrechnungshof kritisierten Steuerung an; wie viel das für Pünktlichkeit bringt, ist kaum untersucht.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=46', null, 'offen', '2026-09-30', false, true, null),
  (6773, 8, 15, null, 'Vernachlässigtes Schienennetz ausbauen, Engpässe beseitigen', '{802}', 6744, 2, 2, null, 'Setzt direkt am maroden Netz an, wirkt wegen Bauzeiten aber erst nach Jahren; der Bundesrechnungshof bezweifelt, dass mehr Mittel ohne bessere Steuerung den Zustand verbessern.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=46', null, 'gemischt', '2026-09-30', false, true, null),
  (6774, 8, 15, null, 'ÖPNV im ländlichen Raum bedarfsgerecht ausbauen', '{801}', null, 1, 2, null, 'Benennt das Ziel eines besseren Angebots auf dem Land, aber keinen Weg und keine Finanzierung; Angebot und Bestellung liegen bei Ländern und Kommunen.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=40', null, 'offen', '2026-09-30', false, true, null),
  (6775, 8, 16, null, 'Verkehrsträgerübergreifender Infrastrukturfonds nach Schweizer Vorbild', '{802}', 6742, 2, 2, null, 'Verlässliche Mittel über mehrere Jahre erleichtern die Planung von Sanierungen, wie der Bahninfrastrukturfonds der Schweiz zeigt; ohne bessere Steuerung ist nicht gesichert, dass mehr Geld den Zustand verbessert.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=36', null, 'gemischt', '2026-09-30', false, true, null),
  (6776, 8, 16, null, 'Jede Ortschaft tagsüber mindestens stündlich an Bus und Bahn anbinden', '{801}', 6748, 2, 2, null, 'Setzt direkt am fehlenden Grundangebot an; ein flächendeckender Takt ist teuer und scheitert derzeit auch am fehlenden Fahrpersonal. Zuständig sind die Länder, der Bund kann über Geld und Rahmenrecht beitragen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=36', null, 'offen', '2026-09-30', false, true, null),
  (6777, 8, 16, null, 'Mehr Personal durch bessere Bezahlung und Arbeitsbedingungen', '{803}', 6746, 2, 2, null, 'Bessere Bedingungen machen den Fahrdienst attraktiver und halten Beschäftigte im Beruf; die Kosten tragen Länder und Kommunen, und Vergaben regeln vor allem die Länder.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=36', null, 'gemischt', '2026-09-30', false, true, null),
  (6778, 8, 16, null, 'Netz sanieren, elektrifizieren und ausbauen', '{802}', 6744, 2, 2, null, 'Setzt direkt am maroden Netz an, wirkt wegen Bauzeiten aber erst nach Jahren; der Bundesrechnungshof bezweifelt, dass mehr Mittel ohne bessere Steuerung den Zustand verbessern.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=37', null, 'gemischt', '2026-09-30', false, true, null),
  (6779, 8, 16, null, 'Stillgelegte Strecken reaktivieren', '{801}', 6747, 1, 2, null, 'Verbessert die Anbindung einzelner ländlicher Orte deutlich, erreicht insgesamt aber nur wenige Menschen; Planung und Bau dauern viele Jahre.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=37', null, 'gemischt', '2026-09-30', false, true, null),
  (6780, 8, 11, 'ST', 'Sachsen-Anhalt-Takt erweitern, alle Ober- und Mittelzentren verbinden', '{801}', 6749, 2, 2, null, 'Häufigere Fahrten und direkte Verbindungen verbessern das Angebot spürbar und ziehen mehr Fahrgäste an; das Land muss die zusätzlichen Fahrten dauerhaft bezahlen und braucht Fahrpersonal.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=62', null, 'belegt', '2026-09-30', false, true, null),
  (6781, 8, 11, 'ST', 'Rufverkehre, Bürgerbusse und autonome Angebote im ländlichen Raum', '{801}', 6750, 1, 3, null, 'Schließt Lücken dort, wo Linienbusse fast leer fahren würden; Rufbusse befördern wenige Menschen je Fahrt und sind teuer, ersetzen also keinen dichten Takt.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=63', null, 'gemischt', '2026-09-30', false, true, null),
  (6782, 8, 12, 'ST', 'Mobilitätsgarantie für alle Regionen', '{801}', 6751, 2, 2, null, 'Setzt direkt am fehlenden Grundangebot an; ein flächendeckender Takt ist teuer und braucht Fahrpersonal, das derzeit fehlt.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=41', null, 'offen', '2026-09-30', false, true, null),
  (6783, 8, 12, 'ST', 'Stillgelegte Strecken reaktivieren, zusätzliche Haltepunkte', '{801}', 6752, 1, 2, null, 'Verbessert die Anbindung einzelner Orte deutlich, erreicht insgesamt aber wenige Menschen; Planung und Bau dauern Jahre.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=42', null, 'gemischt', '2026-09-30', false, true, null),
  (6784, 8, 12, 'ST', 'ÖPNV-Leistungen nur bei Anwendung der Tarifverträge vergeben', '{803}', 6753, 2, 3, null, 'Bessere Bezahlung macht den Fahrdienst attraktiver und hält Beschäftigte; das Land kann Tariftreue in der Vergabe und bei eigenen Unternehmen durchsetzen, muss die Mehrkosten aber tragen.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=41', null, 'gemischt', '2026-09-30', false, true, null),
  (6785, 8, 13, 'ST', 'Busverkehr so ausbauen, dass jedes Dorf mindestens stündlich erreicht wird', '{801}', 6751, 2, 2, null, 'Setzt direkt am fehlenden Grundangebot an; ein flächendeckender Takt ist teuer und braucht Fahrpersonal, das derzeit fehlt.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=29', null, 'offen', '2026-09-30', false, true, null),
  (6786, 8, 14, 'ST', 'Landes-Bus-Netz ausbauen, On-Demand-Shuttles und Rufbusse in Taktverkehre einbinden', '{801}', 6749, 2, 2, null, 'Häufigere Fahrten und direkte Verbindungen verbessern das Angebot spürbar und ziehen mehr Fahrgäste an; das Land muss die zusätzlichen Fahrten dauerhaft bezahlen und braucht Fahrpersonal.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=67', null, 'belegt', '2026-09-30', false, true, null),
  (6787, 8, 14, 'ST', 'Schülerbeförderung aus dem Landeshaushalt bezahlen, damit mehr Regionalisierungsmittel für das Angebot bleiben', '{801}', null, 2, 2, null, 'Macht Geld für zusätzliche Fahrten frei, ohne neue Bundesmittel; das Land muss die Schülerbeförderung dafür dauerhaft aus dem eigenen Haushalt bezahlen.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=69', null, 'offen', '2026-09-30', false, true, null),
  (6788, 8, 14, 'ST', 'Offensive für Fahrpersonal: schnellere Qualifizierung, Anerkennung ausländischer Abschlüsse', '{803}', 6754, 2, 3, null, 'Schnellere Qualifizierung, Anerkennung ausländischer Abschlüsse und eigene Ausbildung setzen direkt am Mangel an; ohne bessere Bedingungen verlassen viele den Beruf wieder.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=68', null, 'gemischt', '2026-09-30', false, true, null),
  (6789, 8, 15, 'ST', 'Flächendeckendes Nahverkehrsangebot sichern statt Buslinien kürzen', '{801}', null, 1, 2, null, 'Sichert das bestehende Angebot gegen Kürzungen, nennt aber weder Umfang noch Finanzierung eines Ausbaus.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=191', null, 'offen', '2026-09-30', false, true, null),
  (6790, 8, 15, 'ST', 'Heidebahn Wittenberg–Eilenburg regelmäßig befahren', '{801}', 6752, 1, 2, null, 'Verbessert die Anbindung einzelner Orte deutlich, erreicht insgesamt aber wenige Menschen; Planung und Bau dauern Jahre.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=200', null, 'gemischt', '2026-09-30', false, true, null),
  (6791, 8, 16, 'ST', 'Landesbedeutsame Buslinien mit engerem Takt zum Zug', '{801}', 6749, 2, 2, null, 'Häufigere Fahrten und direkte Verbindungen verbessern das Angebot spürbar und ziehen mehr Fahrgäste an; das Land muss die zusätzlichen Fahrten dauerhaft bezahlen und braucht Fahrpersonal.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=103', null, 'belegt', '2026-09-30', false, true, null),
