  (8942, 19, 16, 'BE', 'Zugriffsberechtigungen und Speicherung in Verwaltungsdatenbanken diskriminierungskritisch überprüfen.', '{1904}', 8712, 1, 3, null, 'Kann diskriminierende Abläufe in Behörden sichtbar machen und abbauen, bleibt aber oft unverbindlich und ohne Anspruch für Betroffene; die Wirkung solcher Strategien ist kaum untersucht.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=286', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8943, 19, 16, 'BE', 'Kriminalitätsbelastete Orte und Waffenverbotszonen abschaffen, da sie Racial Profiling begünstigen.', '{1904}', 8710, 2, 3, null, 'Setzt an Befugnissen an, die diskriminierende Kontrollen ermöglichen, und ist im Landespolizeirecht regelbar; Studien zur Wirkung einer Abschaffung solcher Befugnisse fehlen, Sicherheitsfolgen sind umstritten.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=290', null, 'offen', '2026-10-10', false, true, 'blind'),
  (8944, 19, 16, 'BE', 'Kontrollquittungen: Polizei muss bei Identitätsfeststellung und Durchsuchung Grund und Rechtsgrundlage schriftlich angeben.', '{1904}', 8711, 2, 3, null, 'Dokumentation macht Kontrollen überprüfbar; in Fuenlabrada sanken Kontrollzahl und Überrepräsentation marokkanischer Personen bei höherer Trefferquote. Belege stammen aus einem Pilotort und von Befürwortern.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=290', 'https://liberties.eu/en/news/stop-forms-ethnic-profiling-spain/16436', 'offen', '2026-10-10', false, true, 'blind'),
  (8945, 19, 16, 'BE', 'Rassistische Polizeipraktiken offenlegen und bekämpfen; Beratungsstellen unterstützen, die polizeiliches Handeln beobachten.', '{1904}', 8712, 1, 3, null, 'Kann diskriminierende Abläufe in Behörden sichtbar machen und abbauen, bleibt aber oft unverbindlich und ohne Anspruch für Betroffene; die Wirkung solcher Strategien ist kaum untersucht.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=290', null, 'offen', '2026-10-10', false, true, 'blind'),
