  (9093, 22, 13, 'BE', 'Unterstützung moderierter Bürger*innenräte mit gelosten Bürger*innen für Handlungsempfehlungen an Debatte und Parlament', '{2205}', 8997, 2, 3, null, 'Deliberation senkte im Feldexperiment affektive Polarisierung deutlich und gibt Mitsprache. Dagegen: erreicht direkt nur wenige; Effekte auf Vertrauen der übrigen Bevölkerung uneinheitlich.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=174', 'https://deliberation.stanford.edu/publications/journal-articles/deliberation-antidote-extreme-partisan-polarization-reflections', 'gemischt', '2026-10-10', false, true, 'blind'),
  (9094, 22, 13, 'BE', 'Unterstützung des Dialogs der verschiedenen Glaubensgemeinschaften und interreligiöser Formen des Gedenkens', '{2205}', 9000, 2, 3, null, 'Kontakt verringert Vorurteile laut Metaanalysen und Feldexperimenten. Dagegen: neuere vorregistrierte Studien finden kleinere Effekte, die oft auf die getroffenen Personen begrenzt bleiben.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=171', 'https://forrt.org/open-social-psychology/chapter12.html', 'gemischt', '2026-10-10', false, true, 'blind'),
  (9095, 22, 13, 'BE', 'Moderierte Debattenräume an Hochschulen und Dialogförderung in Zeiten politischer Unsicherheit', '{2205}', 9000, 2, 3, null, 'Kontakt verringert Vorurteile laut Metaanalysen und Feldexperimenten. Dagegen: neuere vorregistrierte Studien finden kleinere Effekte, die oft auf die getroffenen Personen begrenzt bleiben.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=199', 'https://forrt.org/open-social-psychology/chapter12.html', 'gemischt', '2026-10-10', false, true, 'blind'),
